contracts/analysis/MBARFreeEnergyEstimat.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";

interface IMBARScalarMath {
    function numericalMath() external view returns (address);
    function ln(bytes16) external view returns (bytes16);
    function exp(bytes16) external view returns (bytes16);
}

/// @notice General sampled-state MBAR fixed-point equations, resumable by cell.
/// @dev Convergence alone is not an overlap, equilibration or uncertainty claim.
contract MBARFreeEnergyEstimator {
    error InvalidInput(); error UnknownAnalysis(); error Terminal(); error DependencyChanged();
    enum Status { Missing, Denominators, Update, Normalize, FinalDenominators, Converged, MaxIterations }
    ReducedPotentialCollector public immutable collector;
    FloatMath public immutable numericalMath;
    IMBARScalarMath public immutable scalarMath;
    bytes32[3] public dependencyHashes;
    bytes32 public immutable configurationHash;
    uint256 public constant MAX_WORK = 32;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant MAX_FREE_ENERGY = 0x40050000000000000000000000000000; // 64
    struct Analysis {
        bytes32 seriesId; bytes32 sampleDigest; bytes32 commitment;
        uint32 samples; uint8 states; uint32 iterations; uint32 maxIterations;
        uint32 n; uint8 k; Status status; bytes16 tolerance; bytes16 accumulator; bytes16 residual;
        bytes16[16] f; bytes16[16] next; bytes16[16] logCounts;
        mapping(uint256 => bytes16) logDenominator;
    }
    mapping(uint256=>Analysis) private _analyses;
    uint256 public nextAnalysisId=1;
    event AnalysisCreated(uint256 indexed id,bytes32 indexed seriesId,bytes32 commitment);
    event IterationCompleted(uint256 indexed id,uint32 iteration,bytes16 residual,Status status);
    constructor(address collector_,address math_,address scalar_) {
        if (collector_.code.length==0 || math_.code.length==0 || scalar_.code.length==0
            || address(ReducedPotentialCollector(collector_).numericalMath())!=math_
            || IMBARScalarMath(scalar_).numericalMath()!=math_) revert InvalidInput();
        collector=ReducedPotentialCollector(collector_); numericalMath=FloatMath(math_); scalarMath=IMBARScalarMath(scalar_);
        dependencyHashes=[collector_.codehash,math_.codehash,scalar_.codehash];
        configurationHash=keccak256(abi.encode(collector_,math_,scalar_,dependencyHashes));
    }
    function createAnalysis(bytes32 seriesId,bytes16 tolerance,uint32 maxIterations) external returns(uint256 id) {
        _dependencies();
        if (!numericalMath.isFinite(tolerance) || numericalMath.compare(tolerance,bytes16(0))<=0
            || numericalMath.compare(tolerance,ONE)>=0 || maxIterations==0 || maxIterations>10000) revert InvalidInput();
        bytes32 digest=collector.assertSealed(seriesId);
        (ReducedPotentialCollector.Configuration memory config,,uint32 count,)=collector.seriesInfo(seriesId);
        if(tolerance!=config.mbarTolerance)revert InvalidInput();
        id=nextAnalysisId++; Analysis storage a=_analyses[id];
        a.seriesId=seriesId;a.sampleDigest=digest;a.samples=count;a.states=config.stateCount;
        a.maxIterations=maxIterations;a.tolerance=tolerance;a.status=Status.Denominators;
        a.commitment=keccak256(abi.encode(bytes32("ORVIA-MBAR-v1"),block.chainid,address(this),id,
            seriesId,digest,configurationHash,tolerance,maxIterations));
        for(uint256 k;k<a.states;++k) a.logCounts[k]=scalarMath.ln(numericalMath.fromUInt(collector.stateCount(seriesId,k)));
        emit AnalysisCreated(id,seriesId,a.commitment);
    }
    function advanceAnalysis(uint256 id,uint256 workLimit) external returns(uint256 processed,bool terminal) {
        if(workLimit==0 || workLimit>MAX_WORK) revert InvalidInput();
        _dependencies(); Analysis storage a=_get(id);
        if(a.status>=Status.Converged) revert Terminal();
        if(collector.assertSealed(a.seriesId)!=a.sampleDigest) revert DependencyChanged();
        while(processed<workLimit && a.status<Status.Converged) {
            if(a.status==Status.Denominators || a.status==Status.FinalDenominators) _denominator(a);
            else if(a.status==Status.Update) _update(a);
            else _normalize(a,id);
            ++processed;
        }
        terminal=a.status>=Status.Converged;
    }
    function _denominator(Analysis storage a) private {
        FloatMath m=numericalMath;
        bytes16 term=m.sub(m.add(a.logCounts[a.k],a.f[a.k]),collector.potential(a.seriesId,a.n,a.k));
        a.accumulator=a.k==0?term:_logAdd(a.accumulator,term);
        ++a.k;
        if(a.k==a.states) {
            a.logDenominator[a.n]=a.accumulator;a.k=0;++a.n;
            if(a.n==a.samples) {a.n=0;a.status=a.status==Status.FinalDenominators?Status.Converged:Status.Update;}
        }
    }
    function _update(Analysis storage a) private {
        bytes16 term=numericalMath.neg(numericalMath.add(collector.potential(a.seriesId,a.n,a.k),a.logDenominator[a.n]));
        a.accumulator=a.n==0?term:_logAdd(a.accumulator,term);
        ++a.n;
        if(a.n==a.samples) {
            a.next[a.k]=numericalMath.neg(a.accumulator);a.n=0;++a.k;
            if(a.k==a.states){a.k=0;a.residual=bytes16(0);a.status=Status.Normalize;}
        }
    }
    function _normalize(Analysis storage a,uint256 id) private {
        FloatMath m=numericalMath;
        bytes16 next=m.sub(a.next[a.k],a.next[0]);
        if(m.compare(m.abs(next),MAX_FREE_ENERGY)>0) revert InvalidInput();
        bytes16 change=m.abs(m.sub(next,a.f[a.k]));
        if(m.compare(change,a.residual)>0)a.residual=change;
        a.f[a.k]=next;++a.k;
        if(a.k==a.states){
            a.k=0;++a.iterations;
            if(m.compare(a.residual,a.tolerance)<=0)a.status=Status.FinalDenominators;
            else if(a.iterations==a.maxIterations)a.status=Status.MaxIterations;
            else a.status=Status.Denominators;
            emit IterationCompleted(id,a.iterations,a.residual,a.status);
        }
    }
    function _logAdd(bytes16 a,bytes16 b) private view returns(bytes16) {
        FloatMath m=numericalMath;
        if(m.compare(a,b)<0)(a,b)=(b,a);
        bytes16 delta=m.sub(b,a);
        bytes16 correction=scalarMath.exp(delta);
        correction=m.add(ONE,correction);
        correction=scalarMath.ln(correction);
        return m.add(a,correction);
    }
    function runInfo(uint256 id) external view returns(bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states,
        uint32 iterations,uint32 maxIterations,uint32 sampleCursor,uint8 stateCursor,Status status,bytes16 residual,bytes16 tolerance) {
        Analysis storage a=_get(id);return(a.seriesId,a.commitment,a.samples,a.states,a.iterations,a.maxIterations,a.n,a.k,a.status,a.residual,a.tolerance);
    }
    function fAt(uint256 id,uint256 k) external view returns(bytes16){Analysis storage a=_get(id);if(k>=a.states)revert InvalidInput();return a.f[k];}
    function logDenominatorAt(uint256 id,uint256 n) external view returns(bytes16){Analysis storage a=_get(id);if(n>=a.samples || a.status!=Status.Converged)revert InvalidInput();return a.logDenominator[n];}
    function assertConverged(uint256 id) external view returns(bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states){
        _dependencies();Analysis storage a=_get(id);if(a.status!=Status.Converged)revert InvalidInput();
        if(collector.assertSealed(a.seriesId)!=a.sampleDigest)revert DependencyChanged();return(a.seriesId,a.commitment,a.samples,a.states);
    }
    function _dependencies() private view {if(address(collector).codehash!=dependencyHashes[0] || address(numericalMath).codehash!=dependencyHashes[1] || address(scalarMath).codehash!=dependencyHashes[2])revert DependencyChanged();}
    function _get(uint256 id) private view returns(Analysis storage a){a=_analyses[id];if(a.status==Status.Missing)revert UnknownAnalysis();}
}

contracts/analysis/ReducedPotentialColle.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice Immutable-writer collection of complete cross-state energy samples.
/// @dev A trusted simulation writer must supply computed energies. The collector
///      converts them on-chain; it does not certify equilibrium or independence.
contract ReducedPotentialCollector {
    error Unauthorized(); error InvalidInput(); error UnknownSeries(); error Frozen();
    error DependencyChanged();
    address public immutable writer;
    bytes32 public immutable writerCodeHash;
    FloatMath public immutable numericalMath;
    bytes32 public immutable mathCodeHash;
    uint256 public constant MAX_STATES = 16;
    uint256 public constant MAX_SAMPLES = 4096;
    bytes16 private constant MAX_DIFFERENCE = 0x40040000000000000000000000000000; // 32

    struct Configuration {
        bytes32 protocolHash; bytes32 runHash; bytes32 leg; bytes32 repeatSeed;
        uint8 stateCount; uint32 expectedSamples; bytes16 kT;
        uint64 stride; uint64 equilibrationEnd;
        bytes16 mbarTolerance; bytes16 overlapThreshold; bytes16 minimumESS; bytes16 normalizationTolerance;
    }
    struct Series {
        Configuration config; bytes32 digest; uint32 count; bool isSealed;
        uint32[16] stateCounts; uint64[16] lastStep;
        bytes16[] reduced; bytes16[] referenceEnergy; uint8[] sampledStates; uint64[] steps;
    }
    mapping(bytes32 => Series) private _series;
    event SeriesCreated(bytes32 indexed id, bytes32 digest);
    event SampleRecorded(bytes32 indexed id, uint32 sample, uint8 state, uint64 step, bytes32 digest);
    event SeriesSealed(bytes32 indexed id, bytes32 digest);

    constructor(address writer_, address math_) {
        if (writer_.code.length == 0 || math_.code.length == 0) revert InvalidInput();
        writer = writer_; writerCodeHash = writer_.codehash;
        numericalMath = FloatMath(math_); mathCodeHash = math_.codehash;
    }
    function createSeries(bytes32 id, Configuration calldata config) external {
        _writer();
        if (id == bytes32(0) || _series[id].config.stateCount != 0 || config.protocolHash == bytes32(0)
            || config.runHash == bytes32(0) || config.leg == bytes32(0) || config.repeatSeed == bytes32(0)
            || config.stateCount < 2 || config.stateCount > MAX_STATES || config.expectedSamples < config.stateCount
            || config.expectedSamples > MAX_SAMPLES || config.stride == 0
            || !numericalMath.isFinite(config.kT) || numericalMath.compare(config.kT, bytes16(0)) <= 0) revert InvalidInput();
        _validatePolicy(config);
        Series storage s = _series[id]; s.config = config;
        s.digest = keccak256(abi.encode(bytes32("ORVIA-REDUCED-SERIES-v1"),block.chainid,address(this),id,
            writer,writerCodeHash,address(numericalMath),mathCodeHash,config));
        emit SeriesCreated(id,s.digest);
    }
    function _validatePolicy(Configuration calldata c) private view {
        FloatMath m=numericalMath;bytes16 one=m.fromUInt(1);
        if(!m.isFinite(c.mbarTolerance)||!m.isFinite(c.overlapThreshold)||!m.isFinite(c.minimumESS)||!m.isFinite(c.normalizationTolerance)
            ||m.compare(c.mbarTolerance,bytes16(0))<=0||m.compare(c.mbarTolerance,one)>=0
            ||m.compare(c.overlapThreshold,bytes16(0))<=0||m.compare(c.overlapThreshold,one)>=0
            ||m.compare(c.normalizationTolerance,bytes16(0))<=0||m.compare(c.normalizationTolerance,one)>=0
            ||m.compare(c.minimumESS,one)<0||m.compare(c.minimumESS,m.fromUInt(c.expectedSamples))>0)revert InvalidInput();
    }
    function appendSample(bytes32 id, uint8 sampledState, uint64 step, bytes16[] calldata energies) external {
        _writer(); Series storage s = _get(id);
        if (s.isSealed) revert Frozen();
        if (s.count >= s.config.expectedSamples || sampledState >= s.config.stateCount || energies.length != s.config.stateCount
            || step <= s.config.equilibrationEnd || (s.stateCounts[sampledState] != 0
                && (step <= s.lastStep[sampledState] || step - s.lastStep[sampledState] < s.config.stride))) revert InvalidInput();
        FloatMath m = numericalMath;
        if (!m.isFinite(energies[0])) revert InvalidInput();
        for (uint256 k; k < energies.length; ++k) {
            if (!m.isFinite(energies[k])) revert InvalidInput();
            bytes16 reduced = m.div(m.sub(energies[k],energies[0]),s.config.kT);
            if (m.compare(m.abs(reduced),MAX_DIFFERENCE) > 0) revert InvalidInput();
            s.reduced.push(reduced);
        }
        s.referenceEnergy.push(energies[0]); s.sampledStates.push(sampledState); s.steps.push(step);
        s.lastStep[sampledState] = step; ++s.stateCounts[sampledState];
        s.digest = keccak256(abi.encode(s.digest,s.count,sampledState,step,energies));
        emit SampleRecorded(id,s.count,sampledState,step,s.digest); ++s.count;
    }
    function seal(bytes32 id) external {
        _writer(); Series storage s = _get(id);
        if (s.isSealed) revert Frozen();
        if (s.count != s.config.expectedSamples) revert InvalidInput();
        for (uint256 k; k < s.config.stateCount; ++k) if (s.stateCounts[k] == 0) revert InvalidInput();
        s.isSealed = true; emit SeriesSealed(id,s.digest);
    }
    function seriesInfo(bytes32 id) external view returns (Configuration memory config, bytes32 digest, uint32 count, bool isSealed) {
        Series storage s = _get(id); return (s.config,s.digest,s.count,s.isSealed);
    }
    function stateCount(bytes32 id, uint256 k) external view returns (uint32) {
        Series storage s = _get(id); if (k >= s.config.stateCount) revert InvalidInput(); return s.stateCounts[k];
    }
    function potential(bytes32 id,uint256 n,uint256 k) external view returns (bytes16) {
        Series storage s = _get(id); if (n >= s.count || k >= s.config.stateCount) revert InvalidInput();
        return s.reduced[n*s.config.stateCount+k];
    }
    function sampleInfo(bytes32 id,uint256 n) external view returns (uint8 sampledState,uint64 step,bytes16 referenceEnergy) {
        Series storage s = _get(id); if (n >= s.count) revert InvalidInput();
        return (s.sampledStates[n],s.steps[n],s.referenceEnergy[n]);
    }
    function assertSealed(bytes32 id) external view returns (bytes32) {
        _dependencies(); Series storage s = _get(id); if (!s.isSealed) revert InvalidInput(); return s.digest;
    }
    function _writer() private view { if (msg.sender != writer) revert Unauthorized(); _dependencies(); }
    function _dependencies() private view {
        if (writer.codehash != writerCodeHash || address(numericalMath).codehash != mathCodeHash) revert DependencyChanged();
    }
    function _get(bytes32 id) private view returns (Series storage s) {
        s = _series[id]; if (s.config.stateCount == 0) revert UnknownSeries();
    }
}

contracts/analysis/SamplingDiagnostics.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";
import {MBARFreeEnergyEstimator,IMBARScalarMath} from "./MBARFreeEnergyEstimator.sol";

/// @notice Resumable MBAR weight ESS and overlap diagnostics.
/// @dev Weight ESS does not correct temporal correlation or prove equilibration.
contract SamplingDiagnostics {
    error InvalidInput();error UnknownDiagnostic();error Terminal();error DependencyChanged();
    enum Status { Missing, Weights, Overlap, Summary, Completed }
    MBARFreeEnergyEstimator public immutable estimator;
    ReducedPotentialCollector public immutable collector;
    FloatMath public immutable numericalMath;
    IMBARScalarMath public immutable scalarMath;
    bytes32[4] public dependencyHashes;
    bytes32 public immutable configurationHash;
    bytes16 private constant ONE=0x3fff0000000000000000000000000000;
    uint256 public constant MAX_WORK=32;
    struct Diagnostic {
        uint256 analysisId;bytes32 seriesId;bytes32 analysisCommitment;bytes32 commitment;
        uint32 samples;uint8 states;uint32 n;uint8 i;uint8 j;Status status;
        bytes16 edgeThreshold;bytes16 minimumESS;bytes16 normalizationTolerance;
        bool normalized;bool sufficientESS;bool connected;
        bytes16 accumulator;bytes16[16] weightSum;bytes16[16] weightSquared;bytes16[16] effectiveSamples;
        uint16[16] adjacency;
        mapping(uint256=>bytes16) weights;mapping(uint256=>bytes16) overlaps;
    }
    mapping(uint256=>Diagnostic) private _diagnostics;uint256 public nextDiagnosticId=1;
    event DiagnosticCreated(uint256 indexed id,uint256 indexed analysisId,bytes32 commitment);
    event DiagnosticCompleted(uint256 indexed id,bool normalized,bool sufficientESS,bool connected);
    constructor(address estimator_) {
        if(estimator_.code.length==0)revert InvalidInput();
        estimator=MBARFreeEnergyEstimator(estimator_);collector=estimator.collector();numericalMath=estimator.numericalMath();scalarMath=estimator.scalarMath();
        dependencyHashes=[estimator_.codehash,address(collector).codehash,address(numericalMath).codehash,address(scalarMath).codehash];
        configurationHash=keccak256(abi.encode(estimator_,address(collector),address(numericalMath),address(scalarMath),dependencyHashes));
    }
    function createDiagnostic(uint256 analysisId,bytes16 edgeThreshold,bytes16 minimumESS,bytes16 normalizationTolerance)external returns(uint256 id){
        _dependencies();FloatMath m=numericalMath;
        if(!m.isFinite(edgeThreshold)||!m.isFinite(minimumESS)||!m.isFinite(normalizationTolerance)
            ||m.compare(edgeThreshold,bytes16(0))<=0||m.compare(edgeThreshold,ONE)>=0
            ||m.compare(minimumESS,ONE)<0||m.compare(normalizationTolerance,bytes16(0))<=0||m.compare(normalizationTolerance,ONE)>=0)revert InvalidInput();
        (bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states)=estimator.assertConverged(analysisId);
        if(m.compare(minimumESS,m.fromUInt(samples))>0)revert InvalidInput();
        _assertPolicy(seriesId,edgeThreshold,minimumESS,normalizationTolerance);
        id=nextDiagnosticId++;Diagnostic storage d=_diagnostics[id];
        d.analysisId=analysisId;d.seriesId=seriesId;d.analysisCommitment=commitment;d.samples=samples;d.states=states;
        d.edgeThreshold=edgeThreshold;d.minimumESS=minimumESS;d.normalizationTolerance=normalizationTolerance;
        d.normalized=true;d.sufficientESS=true;d.status=Status.Weights;
        d.commitment=_commitment(d,id);
        emit DiagnosticCreated(id,analysisId,d.commitment);
    }
    function _assertPolicy(bytes32 seriesId,bytes16 edge,bytes16 ess,bytes16 normalization)private view{
        (ReducedPotentialCollector.Configuration memory c,,,)=collector.seriesInfo(seriesId);
        if(edge!=c.overlapThreshold||ess!=c.minimumESS||normalization!=c.normalizationTolerance)revert InvalidInput();
    }
    function _commitment(Diagnostic storage d,uint256 id)private view returns(bytes32){
        bytes32 thresholds=keccak256(abi.encode(d.edgeThreshold,d.minimumESS,d.normalizationTolerance));
        return keccak256(abi.encode(bytes32("ORVIA-MBAR-DIAG-v1"),block.chainid,address(this),id,
            configurationHash,d.analysisId,d.analysisCommitment,thresholds));
    }
    function advanceDiagnostic(uint256 id,uint256 workLimit)external returns(uint256 processed,bool complete){
        if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();_dependencies();Diagnostic storage d=_get(id);
        if(d.status==Status.Completed)revert Terminal();
        (,bytes32 commitment,,)=estimator.assertConverged(d.analysisId);if(commitment!=d.analysisCommitment)revert DependencyChanged();
        while(processed<workLimit&&d.status!=Status.Completed){
            if(d.status==Status.Weights)_weight(d);else if(d.status==Status.Overlap)_overlap(d);else _summary(d,id);++processed;
        }complete=d.status==Status.Completed;
    }
    function _weight(Diagnostic storage d)private{
        FloatMath m=numericalMath;
        bytes16 exponent=m.sub(estimator.fAt(d.analysisId,d.i),collector.potential(d.seriesId,d.n,d.i));
        exponent=m.sub(exponent,estimator.logDenominatorAt(d.analysisId,d.n));
        bytes16 weight=scalarMath.exp(exponent);d.weights[uint256(d.n)*d.states+d.i]=weight;
        d.weightSum[d.i]=m.add(d.weightSum[d.i],weight);d.weightSquared[d.i]=m.add(d.weightSquared[d.i],m.mul(weight,weight));
        ++d.i;if(d.i==d.states){d.i=0;++d.n;if(d.n==d.samples){d.n=0;d.status=Status.Overlap;}}
    }
    function _overlap(Diagnostic storage d)private{
        FloatMath m=numericalMath;uint256 offset=uint256(d.n)*d.states;
        bytes16 product=m.mul(d.weights[offset+d.i],d.weights[offset+d.j]);
        d.accumulator=d.n==0?product:m.add(d.accumulator,product);++d.n;
        if(d.n==d.samples){
            bytes16 value=m.mul(m.fromUInt(collector.stateCount(d.seriesId,d.j)),d.accumulator);
            d.overlaps[uint256(d.i)*d.states+d.j]=value;d.n=0;++d.j;
            if(d.j==d.states){d.j=0;++d.i;if(d.i==d.states){d.i=0;d.status=Status.Summary;}}
        }
    }
    function _summary(Diagnostic storage d,uint256 id)private{
        FloatMath m=numericalMath;uint256 i=d.i;
        if(m.compare(m.abs(m.sub(d.weightSum[i],ONE)),d.normalizationTolerance)>0)d.normalized=false;
        bytes16 ess=m.div(m.mul(d.weightSum[i],d.weightSum[i]),d.weightSquared[i]);d.effectiveSamples[i]=ess;
        if(m.compare(ess,d.minimumESS)<0)d.sufficientESS=false;
        uint16 edges=uint16(uint256(1)<<i);
        for(uint256 j;j<d.states;++j){
            if(m.compare(d.overlaps[i*d.states+j],d.edgeThreshold)>=0
                &&m.compare(d.overlaps[j*d.states+i],d.edgeThreshold)>=0)edges|=uint16(uint256(1)<<j);
        }d.adjacency[i]=edges;++d.i;
        if(d.i==d.states){
            uint16 reached=1;
            for(uint256 pass;pass<d.states;++pass){uint16 next=reached;for(uint256 j;j<d.states;++j)if(reached&(uint16(uint256(1)<<j))!=0)next|=d.adjacency[j];if(next==reached)break;reached=next;}
            d.connected=uint256(reached)==(uint256(1)<<d.states)-1;d.status=Status.Completed;
            emit DiagnosticCompleted(id,d.normalized,d.sufficientESS,d.connected);
        }
    }
    function runInfo(uint256 id)external view returns(uint256 analysisId,bytes32 commitment,Status status,uint32 sampleCursor,uint8 rowCursor,uint8 columnCursor,bool normalized,bool sufficientESS,bool connected){
        Diagnostic storage d=_get(id);return(d.analysisId,d.commitment,d.status,d.n,d.i,d.j,d.normalized,d.sufficientESS,d.connected);
    }
    function stateDiagnostics(uint256 id,uint256 k)external view returns(bytes16 weightSum,bytes16 effectiveSamples){Diagnostic storage d=_get(id);if(k>=d.states||d.status!=Status.Completed)revert InvalidInput();return(d.weightSum[k],d.effectiveSamples[k]);}
    function overlap(uint256 id,uint256 i,uint256 j)external view returns(bytes16){Diagnostic storage d=_get(id);if(i>=d.states||j>=d.states||d.status!=Status.Completed)revert InvalidInput();return d.overlaps[i*d.states+j];}
    function assertAccepted(uint256 id)external view returns(uint256 analysisId,bytes32 commitment){
        _dependencies();Diagnostic storage d=_get(id);if(d.status!=Status.Completed||!d.normalized||!d.sufficientESS||!d.connected)revert InvalidInput();
        (,bytes32 actual,,)=estimator.assertConverged(d.analysisId);if(actual!=d.analysisCommitment)revert DependencyChanged();return(d.analysisId,d.commitment);
    }
    function _dependencies()private view{if(address(estimator).codehash!=dependencyHashes[0]||address(collector).codehash!=dependencyHashes[1]||address(numericalMath).codehash!=dependencyHashes[2]||address(scalarMath).codehash!=dependencyHashes[3])revert DependencyChanged();}
    function _get(uint256 id)private view returns(Diagnostic storage d){d=_diagnostics[id];if(d.status==Status.Missing)revert UnknownDiagnostic();}
}

contracts/analysis/TimeSeriesDiagnostics.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Bounded single-series initial-positive/monotone autocorrelation analysis.
/// @dev The stationary reversible-chain interpretation is a model assumption;
///      these diagnostics cannot establish stationarity or validate all observables.
contract TimeSeriesDiagnostics {
    error Unauthorized();error InvalidInput();error UnknownSeries();error InvalidStage();error DependencyChanged();
    enum Status { Missing, Collecting, Mean, Covariance, Sequence, Completed }
    struct Configuration {
        bytes32 protocolHash;bytes32 runHash;bytes32 replicaHash;bytes32 observableHash;
        uint32 state;uint32 expectedSamples;uint64 firstStep;uint64 stride;uint16 maxLag;uint32 minimumSamples;
    }
    struct Series {
        Configuration config;bytes32 digest;bytes32 resultDigest;Status status;
        uint32 count;uint32 cursor;uint16 lag;uint16 pair;uint16 usedLag;
        bytes16 mean;bytes16 m2;bytes16 covarianceSum;bytes16 pairSum;bytes16 previousPair;bytes16 g;bytes16 effectiveSamples;
        bool constantSeries;bool shortSeries;bool truncated;bool hasVariation;
        bytes16[] values;mapping(uint256=>bytes16) covariance;
    }
    struct Summary {
        bytes32 inputDigest;bytes32 resultDigest;Status status;uint32 samples;uint32 cursor;uint16 lag;uint16 usedLag;
        bytes16 mean;bytes16 populationVariance;bytes16 sampleVariance;bytes16 g;bytes16 effectiveSamples;
        bool constantSeries;bool shortSeries;bool truncated;bool validEstimate;
    }
    address public immutable writer;FloatMath public immutable numericalMath;
    bytes32 public immutable writerCodeHash;bytes32 public immutable mathCodeHash;
    uint256 public constant MAX_SAMPLES=4096;uint256 public constant MAX_LAG=255;
    uint256 public constant MAX_APPEND=64;uint256 public constant MAX_WORK=32;
    bytes16 private constant ONE=0x3fff0000000000000000000000000000;
    bytes16 private constant TWO=0x40000000000000000000000000000000;
    mapping(bytes32=>Series)private _series;
    event SeriesRegistered(bytes32 indexed id,bytes32 digest);
    event SeriesSealed(bytes32 indexed id,bytes32 digest);
    event DiagnosticsCompleted(bytes32 indexed id,bytes32 resultDigest,bool validEstimate);
    constructor(address writer_,address math_){
        if(writer_.code.length==0||math_.code.length==0)revert InvalidInput();
        writer=writer_;numericalMath=FloatMath(math_);writerCodeHash=writer_.codehash;mathCodeHash=math_.codehash;
    }
    function createSeries(bytes32 id,Configuration calldata c)external{
        _writer();
        if(id==bytes32(0)||_series[id].status!=Status.Missing||c.protocolHash==bytes32(0)||c.runHash==bytes32(0)
            ||c.replicaHash==bytes32(0)||c.observableHash==bytes32(0)||c.expectedSamples==0||c.expectedSamples>MAX_SAMPLES
            ||c.stride==0||c.minimumSamples<4||c.minimumSamples>MAX_SAMPLES||c.maxLag>MAX_LAG
            ||(c.expectedSamples==1?c.maxLag!=0:(c.maxLag==0||c.maxLag%2!=1||c.maxLag>=c.expectedSamples))
            ||uint256(c.firstStep)+uint256(c.expectedSamples-1)*c.stride>type(uint64).max)revert InvalidInput();
        Series storage s=_series[id];s.config=c;s.status=Status.Collecting;
        s.shortSeries=c.expectedSamples<c.minimumSamples;
        s.digest=keccak256(abi.encode(bytes32("ORVIA-TIMESERIES-v1"),block.chainid,address(this),id,
            writer,writerCodeHash,address(numericalMath),mathCodeHash,c));
        emit SeriesRegistered(id,s.digest);
    }
    function append(bytes32 id,uint64 firstStep,bytes16[] calldata values)external{
        _writer();Series storage s=_get(id);if(s.status!=Status.Collecting)revert InvalidStage();
        if(values.length==0||values.length>MAX_APPEND||uint256(s.count)+values.length>s.config.expectedSamples
            ||uint256(firstStep)!=uint256(s.config.firstStep)+uint256(s.count)*s.config.stride)revert InvalidInput();
        for(uint256 i;i<values.length;++i){
            if(!numericalMath.isFinite(values[i]))revert InvalidInput();
            bytes16 value=numericalMath.add(values[i],bytes16(0));
            if(s.count!=0&&numericalMath.compare(value,s.values[0])!=0)s.hasVariation=true;
            s.values.push(value);
            s.digest=keccak256(abi.encode(s.digest,s.count,uint256(firstStep)+i*s.config.stride,value));++s.count;
        }
    }
    function seal(bytes32 id)external{
        _writer();Series storage s=_get(id);if(s.status!=Status.Collecting)revert InvalidStage();
        if(s.count!=s.config.expectedSamples)revert InvalidInput();s.status=Status.Mean;emit SeriesSealed(id,s.digest);
    }
    function advance(bytes32 id,uint256 workLimit)external returns(uint256 processed,bool completed){
        _dependencies();if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();Series storage s=_get(id);
        if(s.status<Status.Mean||s.status==Status.Completed)revert InvalidStage();
        while(processed<workLimit&&s.status!=Status.Completed){
            if(s.status==Status.Mean)_mean(s,id);else if(s.status==Status.Covariance)_covariance(s);else _sequence(s,id);++processed;
        }completed=s.status==Status.Completed;
    }
    function _mean(Series storage s,bytes32 id)private{
        FloatMath m=numericalMath;bytes16 x=s.values[s.cursor];bytes16 delta=m.sub(x,s.mean);++s.cursor;
        bytes16 increment=m.div(delta,m.fromUInt(s.cursor));s.mean=m.add(s.mean,increment);
        s.m2=m.add(s.m2,m.mul(delta,m.sub(x,s.mean)));
        if(s.cursor==s.count){
            if(m.compare(s.m2,bytes16(0))<0)revert InvalidInput();
            s.covariance[0]=m.div(s.m2,m.fromUInt(s.count));s.cursor=0;
            if(m.isZero(s.covariance[0])){if(s.hasVariation)revert InvalidInput();s.constantSeries=true;_complete(s,id);}
            else{s.lag=1;s.status=Status.Covariance;}
        }
    }
    function _covariance(Series storage s)private{
        FloatMath m=numericalMath;
        bytes16 a=m.sub(s.values[s.cursor],s.mean);bytes16 b=m.sub(s.values[s.cursor+s.lag],s.mean);
        s.covarianceSum=m.add(s.covarianceSum,m.mul(a,b));++s.cursor;
        if(s.cursor==s.count-s.lag){
            s.covariance[s.lag]=m.div(s.covarianceSum,m.fromUInt(s.count));s.cursor=0;s.covarianceSum=bytes16(0);
            if(s.lag==s.config.maxLag)s.status=Status.Sequence;else ++s.lag;
        }
    }
    function _sequence(Series storage s,bytes32 id)private{
        FloatMath m=numericalMath;uint256 lag=uint256(s.pair)*2;
        bytes16 pair=m.add(s.covariance[lag],s.covariance[lag+1]);
        if(m.compare(pair,bytes16(0))<=0){_complete(s,id);return;}
        if(s.pair!=0&&m.compare(pair,s.previousPair)>0)pair=s.previousPair;
        s.previousPair=pair;s.pairSum=m.add(s.pairSum,pair);s.usedLag=uint16(lag+1);++s.pair;
        if(s.usedLag==s.config.maxLag){s.truncated=true;_complete(s,id);}
    }
    function _complete(Series storage s,bytes32 id)private{
        if(!s.constantSeries){
            FloatMath m=numericalMath;bytes16 ratio=m.div(s.pairSum,s.covariance[0]);
            s.g=m.sub(m.mul(TWO,ratio),ONE);if(m.compare(s.g,ONE)<0)s.g=ONE;
            s.effectiveSamples=m.div(m.fromUInt(s.count),s.g);
        }
        s.status=Status.Completed;
        s.resultDigest=keccak256(abi.encode(s.digest,s.mean,s.covariance[0],s.g,s.effectiveSamples,s.usedLag,s.constantSeries,s.shortSeries,s.truncated));
        emit DiagnosticsCompleted(id,s.resultDigest,!s.constantSeries&&!s.shortSeries&&!s.truncated);
    }
    function configuration(bytes32 id)external view returns(Configuration memory){return _get(id).config;}
    function valueAt(bytes32 id,uint256 index)external view returns(bytes16){Series storage s=_get(id);if(index>=s.count)revert InvalidInput();return s.values[index];}
    function covarianceAt(bytes32 id,uint256 lag)external view returns(bytes16){Series storage s=_get(id);if(s.status!=Status.Completed||lag>s.config.maxLag)revert InvalidInput();if(s.constantSeries)return bytes16(0);return s.covariance[lag];}
    function summary(bytes32 id)external view returns(Summary memory out){
        Series storage s=_get(id);out.inputDigest=s.digest;out.resultDigest=s.resultDigest;out.status=s.status;out.samples=s.count;out.cursor=s.cursor;
        out.lag=s.lag;out.usedLag=s.usedLag;out.mean=s.mean;out.populationVariance=s.covariance[0];
        if(s.count>1&&s.status==Status.Completed)out.sampleVariance=numericalMath.div(s.m2,numericalMath.fromUInt(s.count-1));
        out.g=s.g;out.effectiveSamples=s.effectiveSamples;out.constantSeries=s.constantSeries;out.shortSeries=s.shortSeries;out.truncated=s.truncated;
        out.validEstimate=s.status==Status.Completed&&!s.constantSeries&&!s.shortSeries&&!s.truncated;
    }
    function assertCompleted(bytes32 id)external view returns(bytes32 digest,bool validEstimate){
        _dependencies();Series storage s=_get(id);if(s.status!=Status.Completed)revert InvalidStage();return(s.resultDigest,!s.constantSeries&&!s.shortSeries&&!s.truncated);
    }
    function _writer()private view{if(msg.sender!=writer)revert Unauthorized();_dependencies();}
    function _dependencies()private view{if(writer.codehash!=writerCodeHash||address(numericalMath).codehash!=mathCodeHash)revert DependencyChanged();}
    function _get(bytes32 id)private view returns(Series storage s){s=_series[id];if(s.status==Status.Missing)revert UnknownSeries();}
}

contracts/analysis/UncertaintyAndResults.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";
import {MBARFreeEnergyEstimator} from "./MBARFreeEnergyEstimator.sol";
import {SamplingDiagnostics} from "./SamplingDiagnostics.sol";

/// @notice Mean and SEM of a complete preregistered set of paired leg estimates.
/// @dev Repeat-level SEM is not MBAR covariance, a confidence interval, proof of
///      equilibration, or a remedy for shared systematic bias among repeats.
contract UncertaintyAndResults {
    error Unauthorized();error InvalidInput();error UnknownResult();error Terminal();error DependencyChanged();
    address public immutable owner;
    SamplingDiagnostics public immutable diagnostics;MBARFreeEnergyEstimator public immutable estimator;
    ReducedPotentialCollector public immutable collector;FloatMath public immutable numericalMath;
    bytes32[4] public dependencyHashes;bytes32 public immutable configurationHash;
    bytes32 public constant COMPLEX_LEG=keccak256("ORVIA.COMPLEX.v1");
    bytes32 public constant SOLVENT_LEG=keccak256("ORVIA.SOLVENT.v1");
    uint256 public constant MAX_REPEATS=32;uint256 public constant MAX_WORK=8;
    struct Plan {
        bytes32 campaignHash;bytes32 protocolHash;bytes32 policyHash;bytes32 commitment;bytes16 kT;uint8 states;
        bytes32[] complexSeries;bytes32[] solventSeries;mapping(bytes32=>bool) seeds;
    }
    struct Result {
        bytes32 planId;bytes32 commitment;uint8 cursor;bool completed;bytes16 mean;bytes16 m2;bytes16 sem;
        uint256[] complexDiagnostics;uint256[] solventDiagnostics;
    }
    struct LegResult {ReducedPotentialCollector.Configuration config;bytes32 seriesId;bytes32 commitment;bytes16 g;}
    mapping(bytes32=>bytes32)public campaignPlan;
    mapping(bytes32=>Plan)private _plans;mapping(uint256=>Result)private _results;uint256 public nextResultId=1;
    event PlanRegistered(bytes32 indexed planId,bytes32 indexed campaignHash,bytes32 commitment);
    event ResultCreated(uint256 indexed id,bytes32 indexed planId,bytes32 commitment);
    event ResultCompleted(uint256 indexed id,bytes16 deltaDeltaG,bytes16 repeatSEM,uint8 repeats);
    constructor(address diagnostics_,address owner_){
        if(diagnostics_.code.length==0||owner_==address(0))revert InvalidInput();owner=owner_;diagnostics=SamplingDiagnostics(diagnostics_);
        estimator=diagnostics.estimator();collector=diagnostics.collector();numericalMath=diagnostics.numericalMath();
        dependencyHashes=[diagnostics_.codehash,address(estimator).codehash,address(collector).codehash,address(numericalMath).codehash];
        configurationHash=keccak256(abi.encode(owner_,diagnostics_,address(estimator),address(collector),address(numericalMath),dependencyHashes));
    }
    function registerPlan(bytes32 planId,bytes32 campaignHash,bytes32[] calldata complexSeries,bytes32[] calldata solventSeries)external{
        if(msg.sender!=owner)revert Unauthorized();_dependencies();
        if(planId==bytes32(0)||campaignHash==bytes32(0)||campaignPlan[campaignHash]!=bytes32(0)||_plans[planId].campaignHash!=bytes32(0)
            ||complexSeries.length<3||complexSeries.length>MAX_REPEATS||complexSeries.length!=solventSeries.length)revert InvalidInput();
        campaignPlan[campaignHash]=planId;
        Plan storage p=_plans[planId];p.campaignHash=campaignHash;p.complexSeries=complexSeries;p.solventSeries=solventSeries;
        p.commitment=keccak256(abi.encode(bytes32("ORVIA-REPEAT-PLAN-v1"),block.chainid,address(this),planId,
            configurationHash,campaignHash,complexSeries,solventSeries));
        for(uint256 i;i<complexSeries.length;++i)_registerPair(p,complexSeries[i],solventSeries[i],i);
        emit PlanRegistered(planId,campaignHash,p.commitment);
    }
    function _registerPair(Plan storage p,bytes32 complexId,bytes32 solventId,uint256 index)private{
        (ReducedPotentialCollector.Configuration memory c,bytes32 cd,uint32 cn,bool cs)=collector.seriesInfo(complexId);
        (ReducedPotentialCollector.Configuration memory s,bytes32 sd,uint32 sn,bool ss)=collector.seriesInfo(solventId);
        if(cn!=0||sn!=0||cs||ss||c.leg!=COMPLEX_LEG||s.leg!=SOLVENT_LEG||c.protocolHash!=s.protocolHash
            ||c.repeatSeed!=s.repeatSeed||c.kT!=s.kT||c.stateCount!=s.stateCount||p.seeds[c.repeatSeed])revert InvalidInput();
        bytes32 policy=_policy(c);if(policy!=_policy(s))revert InvalidInput();
        if(index==0){p.protocolHash=c.protocolHash;p.policyHash=policy;p.kT=c.kT;p.states=c.stateCount;}
        else if(p.protocolHash!=c.protocolHash||p.policyHash!=policy||p.kT!=c.kT||p.states!=c.stateCount)revert InvalidInput();
        p.seeds[c.repeatSeed]=true;p.commitment=keccak256(abi.encode(p.commitment,index,cd,sd,c.repeatSeed));
    }
    function createResult(bytes32 planId,uint256[] calldata complexDiagnostics,uint256[] calldata solventDiagnostics)external returns(uint256 id){
        _dependencies();Plan storage p=_plan(planId);
        if(complexDiagnostics.length!=p.complexSeries.length||solventDiagnostics.length!=p.solventSeries.length)revert InvalidInput();
        id=nextResultId++;Result storage r=_results[id];r.planId=planId;
        r.complexDiagnostics=complexDiagnostics;r.solventDiagnostics=solventDiagnostics;
        r.commitment=keccak256(abi.encode(bytes32("ORVIA-REPEAT-RESULT-v1"),block.chainid,address(this),id,
            configurationHash,planId,p.commitment,complexDiagnostics,solventDiagnostics));
        emit ResultCreated(id,planId,r.commitment);
    }
    function advanceResult(uint256 id,uint256 workLimit)external returns(uint256 processed,bool completed){
        _dependencies();if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();Result storage r=_get(id);if(r.completed)revert Terminal();
        while(processed<workLimit&&!r.completed){_repeat(r);++processed;}
        completed=r.completed;if(completed)emit ResultCompleted(id,r.mean,r.sem,r.cursor);
    }
    function _repeat(Result storage r)private{
        Plan storage p=_plan(r.planId);
        LegResult memory c=_leg(r.complexDiagnostics[r.cursor],COMPLEX_LEG);
        LegResult memory s=_leg(r.solventDiagnostics[r.cursor],SOLVENT_LEG);
        if(c.seriesId!=p.complexSeries[r.cursor]||s.seriesId!=p.solventSeries[r.cursor])revert InvalidInput();
        r.commitment=keccak256(abi.encode(r.commitment,r.cursor,c.commitment,s.commitment));
        _accumulate(r,numericalMath.sub(c.g,s.g));
    }
    function _policy(ReducedPotentialCollector.Configuration memory c)private pure returns(bytes32){
        return keccak256(abi.encode(c.mbarTolerance,c.overlapThreshold,c.minimumESS,c.normalizationTolerance));
    }
    function _accumulate(Result storage r,bytes16 value)private{
        FloatMath m=numericalMath;++r.cursor;bytes16 delta=m.sub(value,r.mean);
        bytes16 meanIncrement=m.div(delta,m.fromUInt(r.cursor));r.mean=m.add(r.mean,meanIncrement);
        r.m2=m.add(r.m2,m.mul(delta,m.sub(value,r.mean)));
        if(r.cursor==r.complexDiagnostics.length){
            if(m.compare(r.m2,bytes16(0))<0)revert InvalidInput();
            bytes16 denominator=m.fromUInt(uint256(r.cursor)*(r.cursor-1));
            r.sem=m.sqrt(m.div(r.m2,denominator));r.completed=true;
        }
    }
    function _leg(uint256 diagnosticId,bytes32 expectedLeg)private view returns(LegResult memory out){
        (uint256 analysisId,bytes32 diagnosticCommitment)=diagnostics.assertAccepted(diagnosticId);
        (bytes32 seriesId,bytes32 analysisCommitment,,uint8 states)=estimator.assertConverged(analysisId);
        (out.config,,,)=collector.seriesInfo(seriesId);if(out.config.leg!=expectedLeg)revert InvalidInput();out.seriesId=seriesId;
        bytes16 difference=numericalMath.sub(estimator.fAt(analysisId,states-1),estimator.fAt(analysisId,0));
        out.g=numericalMath.mul(out.config.kT,difference);
        out.commitment=keccak256(abi.encode(diagnosticId,diagnosticCommitment,analysisId,analysisCommitment));
    }
    function planInfo(bytes32 planId)external view returns(bytes32 campaignHash,bytes32 protocolHash,bytes32 commitment,bytes32[] memory complexSeries,bytes32[] memory solventSeries){
        Plan storage p=_plan(planId);return(p.campaignHash,p.protocolHash,p.commitment,p.complexSeries,p.solventSeries);
    }
    function resultInfo(uint256 id)external view returns(bytes32 planId,bytes32 protocolHash,bytes32 commitment,uint8 repeatsCompleted,uint256 repeatsExpected,bool completed,bytes16 deltaDeltaG,bytes16 repeatSEM){
        Result storage r=_get(id);return(r.planId,_plans[r.planId].protocolHash,r.commitment,r.cursor,r.complexDiagnostics.length,r.completed,r.mean,r.sem);
    }
    function _dependencies()private view{if(address(diagnostics).codehash!=dependencyHashes[0]||address(estimator).codehash!=dependencyHashes[1]||address(collector).codehash!=dependencyHashes[2]||address(numericalMath).codehash!=dependencyHashes[3])revert DependencyChanged();}
    function _plan(bytes32 planId)private view returns(Plan storage p){p=_plans[planId];if(p.campaignHash==bytes32(0))revert InvalidInput();}
    function _get(uint256 id)private view returns(Result storage r){r=_results[id];if(r.planId==bytes32(0))revert UnknownResult();}
}

contracts/core/AlchemicalHamiltonianEval.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";
import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {HarmonicBondKernel} from "../kernels/HarmonicBondKernel.sol";
import {HarmonicAngleKernel} from "../kernels/HarmonicAngleKernel.sol";
import {PeriodicTorsionKernel} from "../kernels/PeriodicTorsionKernel.sol";
import {LennardJonesKernel} from "../kernels/LennardJonesKernel.sol";
import {SoftcoreLennardJonesKernel} from "../kernels/SoftcoreLennardJonesKernel.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {EwaldRealSpaceKernel} from "../kernels/EwaldRealSpaceKernel.sol";
import {EwaldReciprocalKernel} from "../kernels/EwaldReciprocalKernel.sol";
import {EwaldCorrections} from "../kernels/EwaldCorrections.sol";

interface IProductionWordState {
    function writer() external view returns (address);
    function createNamespace(bytes32 id, uint32 capacity) external;
    function writeWord(bytes32 id, uint256 index, bytes32 value) external;
    function writeWords(bytes32 id, uint256 start, bytes32[] calldata values) external;
    function readWord(bytes32 id, uint256 index) external view returns (bytes32);
    function namespaceInfo(bytes32 id) external view returns (uint32 capacity, bool isSealed);
    function sealNamespace(bytes32 id) external;
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external returns (bytes32);
    function snapshotInfo(bytes32 id) external view returns (bytes32 source, uint64 epoch, uint32 capacity, bytes32 writeDigest, bytes32 commitment);
}
interface IProductionMathIdentity { function numericalMath() external view returns (address); }

/// @notice One complete on-chain hybrid Hamiltonian on an immutable molecular snapshot.
/// @dev NVT fixed orthorhombic box; bonded endpoint interpolation, switched dual
///      soft-core LJ and interpolated-charge finite tin-foil Ewald. No CMAP,
///      Urey-Bradley, harmonic improper, constraints, PME or tail correction is
///      silently supplied. The catalog accepts only its explicit supported schema.
contract AlchemicalHamiltonianEvaluator {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged(); error NotConfigured();
    enum Stage { Missing, Atoms, Bonds, Angles, Torsions, Exceptions, Pairs, ModeSetup, StructureFactor, ModeForces, Background, Complete }
    struct Modules {
        address registry; address topology; address math; address geometry;
        address bond; address angle; address torsion; address lj; address softcore;
        address realSpace; address reciprocal; address corrections;
    }
    struct Input { bytes32 protocol; bytes32 topology; uint8 state; address sourcePage; bytes32 sourceNamespace; uint32 offset; uint32 stride; }
    struct Run {
        Input input; Stage stage; uint64 cursor; uint64 pairs; uint32 modeIndex; uint32 modes;
        bytes32 topologyCommitment; bytes32 snapshotCommitment; bytes32 sourceHash; bytes32 sourceWriterHash;
        address sourceWriter; bytes32 outputNamespace; bytes32 commitment;
        bytes16 lambda; bytes16 totalCharge; bool anyCharge;
        int32[3] mode; bytes16[3] wave; bytes16 coefficient; bytes16 cosine; bytes16 sine;
    }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigmaA; bytes16 epsilonA; bytes16 desiredA; bytes16 sigmaB; bytes16 epsilonB; bytes16 desiredB; }
    struct Evaluation { bytes16 energy; bytes16[3][4] forces; }
    address public immutable owner;
    Modules public modules;
    bytes32[12] public moduleHashes;
    bytes32 public immutable coreConfigurationHash;
    IProductionWordState public outputPage;
    bytes32 public outputPageHash;
    uint256 public nextEvaluation = 1;
    uint256 public constant MAX_WORK = 8;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    mapping(uint256 => Run) private runs;
    mapping(uint256 => mapping(uint64 => uint64)) private exceptionIndex;
    event EvaluationRegistered(uint256 indexed id, bytes32 commitment, bytes32 snapshotCommitment);
    event EvaluationAdvanced(uint256 indexed id, Stage stage, uint64 cursor, uint32 mode);

    constructor(address owner_, Modules memory m) {
        if (owner_ == address(0)) revert InvalidInput(); owner = owner_; modules = m;
        address[12] memory addresses = _addresses(m);
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidInput(); moduleHashes[i] = addresses[i].codehash;
            if (i >= 3 && IProductionMathIdentity(addresses[i]).numericalMath() != m.math) revert InvalidInput();
        }
        if (address(AlchemicalTopologyCatalog(m.topology).numericalMath()) != m.math
            || address(AlchemicalTopologyCatalog(m.topology).geometry()) != m.geometry) revert InvalidInput();
        // All Ewald kernels must share their actual scalar implementation.
        if (address(EwaldRealSpaceKernel(m.realSpace).scalarMath()) != address(EwaldCorrections(m.corrections).scalarMath())
            || address(EwaldRealSpaceKernel(m.realSpace).scalarMath()) != address(EwaldReciprocalKernel(m.reciprocal).scalarMath())) revert InvalidInput();
        coreConfigurationHash = keccak256(abi.encode(m, moduleHashes));
    }
    function bindOutputPage(address page) external {
        if (msg.sender != owner) revert Unauthorized(); if (address(outputPage) != address(0)) revert WrongStage();
        if (page.code.length == 0 || IProductionWordState(page).writer() != address(this)) revert InvalidInput();
        outputPage = IProductionWordState(page); outputPageHash = page.codehash;
    }
    function registerEvaluation(bytes32 protocolId, bytes32 topologyId, uint8 state, address sourcePage,
        bytes32 sourceNamespace, uint32 offset, uint32 stride) external returns (uint256 id)
    {
        if (msg.sender != owner) revert Unauthorized();
        return _register(Input(protocolId,topologyId,state,sourcePage,sourceNamespace,offset,stride));
    }
    function _register(Input memory input) private returns(uint256 id) {
        bytes32 manifest = _dependencies(input.protocol);
        AlchemicalTopologyCatalog catalog = AlchemicalTopologyCatalog(modules.topology);
        bytes32 topologyCommitment = catalog.assertTopology(input.topology);
        AlchemicalTopologyCatalog.Definition memory d = catalog.definition(input.topology);
        if (input.state >= catalog.stateCount(input.topology) || input.sourcePage.code.length == 0 || input.stride < 3) revert InvalidInput();
        bytes32 snapshot = _checkSource(input,d.atoms);
        id = nextEvaluation++; Run storage r = runs[id];
        r.input = input;
        r.stage = Stage.Atoms; r.pairs = uint64(uint256(d.atoms) * (d.atoms - 1) / 2);
        r.topologyCommitment = topologyCommitment; r.snapshotCommitment = snapshot;
        r.sourceHash = input.sourcePage.codehash;
        r.sourceWriter = IProductionWordState(input.sourcePage).writer(); r.sourceWriterHash = r.sourceWriter.codehash;
        r.lambda = catalog.lambdaAt(input.topology, input.state); r.modes = _modeCount(d.ewaldExtent);
        r.outputNamespace = keccak256(abi.encode(bytes32("ORVIA-HAMILTONIAN-OUTPUT-v1"), block.chainid, address(this), id));
        r.commitment = _commitment(r,id,manifest);
        outputPage.createNamespace(r.outputNamespace, d.atoms * 3 + 10);
        emit EvaluationRegistered(id, r.commitment, snapshot);
    }
    function _checkSource(Input memory input,uint32 atoms) private view returns(bytes32 snapshot) {
        (uint32 capacity, bool frozen) = IProductionWordState(input.sourcePage).namespaceInfo(input.sourceNamespace);
        (,,,,snapshot) = IProductionWordState(input.sourcePage).snapshotInfo(input.sourceNamespace);
        if (!frozen || snapshot == bytes32(0) || uint256(input.offset) + uint256(atoms - 1) * input.stride + 3 > capacity) revert InvalidInput();
        address writer = IProductionWordState(input.sourcePage).writer();
        ExperimentRegistry(modules.registry).assertModule(input.protocol, input.sourcePage, input.sourcePage.codehash);
        ExperimentRegistry(modules.registry).assertModule(input.protocol, writer, writer.codehash);
    }
    function _commitment(Run storage r,uint256 id,bytes32 manifest) private view returns(bytes32) {
        bytes32 source = keccak256(abi.encode(r.input,r.snapshotCommitment,r.sourceHash,r.sourceWriter,r.sourceWriterHash));
        bytes32 configuration = keccak256(abi.encode(coreConfigurationHash,address(outputPage),outputPageHash));
        return keccak256(abi.encode(bytes32("ORVIA-HAMILTONIAN-v1"), block.chainid, address(this), id,
            manifest, configuration, r.topologyCommitment, source));
    }
    function advance(uint256 id, uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput(); Run storage r = _get(id);
        _assertRun(r);
        // Anyone may finish this job before its pipeline writer next advances.
        // Preserve authenticated completed results for that writer to consume.
        if (r.stage == Stage.Complete) return (0, true);
        AlchemicalTopologyCatalog.Definition memory d = AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology);
        while (processed < work && r.stage != Stage.Complete) { _one(id, r, d); ++processed; }
        complete = r.stage == Stage.Complete; emit EvaluationAdvanced(id, r.stage, r.cursor, r.modeIndex);
    }
    function result(uint256 id) external view returns (bytes32 outputNamespace, bytes32 commitment, bytes16 energy) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        AlchemicalTopologyCatalog.Definition memory d = AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology);
        return (r.outputNamespace, r.commitment, _decode(outputPage.readWord(r.outputNamespace, uint256(d.atoms) * 3)));
    }
    function forceAt(uint256 id, uint32 atom) external view returns (bytes16[3] memory force) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        if (atom >= AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology).atoms) revert InvalidInput();
        for (uint256 axis; axis < 3; ++axis) force[axis] = _decode(outputPage.readWord(r.outputNamespace, uint256(atom) * 3 + axis));
    }
    function components(uint256 id) external view returns (bytes16[10] memory values) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        uint256 start = uint256(AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology).atoms) * 3;
        for (uint256 k; k < 10; ++k) values[k] = _decode(outputPage.readWord(r.outputNamespace, start + k));
    }
    function moduleConfiguration()external view returns(Modules memory){return modules;}
    function runInfo(uint256 id) external view returns (Stage stage, uint64 cursor, uint32 mode, Input memory input, bytes32 snapshotCommitment) {
        Run storage r = _get(id); return (r.stage, r.cursor, r.modeIndex, r.input, r.snapshotCommitment);
    }
    function _one(uint256 id, Run storage r, AlchemicalTopologyCatalog.Definition memory d) private {
        FloatMath m = FloatMath(modules.math);
        if (r.stage == Stage.Atoms) {
            _position(r, uint32(r.cursor)); bytes16 q = _charge(r, d, uint32(r.cursor));
            r.anyCharge = r.anyCharge || !m.isZero(q); r.totalCharge = m.add(r.totalCharge, q);
            _energy(r, d, 6, EwaldCorrections(modules.corrections).selfEnergy(q, d.ewaldAlpha, d.prefactor));
            if (++r.cursor == d.atoms) { r.cursor = 0; r.stage = Stage.Bonds; }
        } else if (r.stage == Stage.Bonds || r.stage == Stage.Angles || r.stage == Stage.Torsions) {
            uint64 count = r.stage == Stage.Bonds ? d.bonds : r.stage == Stage.Angles ? d.angles : d.torsions;
            if (count != 0) { _bonded(r, d); ++r.cursor; }
            if (r.cursor == count) { r.cursor = 0; r.stage = Stage(uint8(r.stage) + 1); }
        } else if (r.stage == Stage.Exceptions) {
            if (d.exceptions != 0) {
                Pair memory p = _exception(r, d, r.cursor);
                exceptionIndex[id][uint64(uint256(p.a) * d.atoms + p.b)] = r.cursor + 1;
                _exceptionPair(r, d, p); ++r.cursor;
            }
            if (r.cursor == d.exceptions) { r.cursor = 0; r.stage = Stage.Pairs; }
        } else if (r.stage == Stage.Pairs) {
            (uint32 a, uint32 b) = _pairIndices(r.cursor, d.atoms);
            if (exceptionIndex[id][uint64(uint256(a) * d.atoms + b)] == 0) _normalPair(r, d, a, b);
            if (++r.cursor == r.pairs) { r.cursor = 0; r.stage = r.anyCharge ? Stage.ModeSetup : Stage.Background; }
        } else if (r.stage == Stage.ModeSetup) {
            r.mode = _modeAt(r.modeIndex, d.ewaldExtent);
            (r.wave, r.coefficient) = EwaldReciprocalKernel(modules.reciprocal).waveVector(r.mode, d.box, d.ewaldAlpha, d.prefactor);
            r.cosine = bytes16(0); r.sine = bytes16(0); r.cursor = 0; r.stage = Stage.StructureFactor;
        } else if (r.stage == Stage.StructureFactor) {
            (bytes16 c, bytes16 s) = _term(r, d, uint32(r.cursor)); r.cosine = m.add(r.cosine, c); r.sine = m.add(r.sine, s);
            if (++r.cursor == d.atoms) {
                _energy(r, d, 5, EwaldReciprocalKernel(modules.reciprocal).modeEnergy(r.coefficient, r.cosine, r.sine));
                r.cursor = 0; r.stage = Stage.ModeForces;
            }
        } else if (r.stage == Stage.ModeForces) {
            (bytes16 c, bytes16 s) = _term(r, d, uint32(r.cursor));
            _force(r, uint32(r.cursor), EwaldReciprocalKernel(modules.reciprocal).forceContribution(r.wave, r.coefficient, c, s, r.cosine, r.sine), false);
            if (++r.cursor == d.atoms) { r.cursor = 0; r.stage = ++r.modeIndex == r.modes ? Stage.Background : Stage.ModeSetup; }
        } else if (r.stage == Stage.Background) {
            _energy(r, d, 7, EwaldCorrections(modules.corrections).backgroundEnergy(r.totalCharge, d.box, d.ewaldAlpha, d.prefactor));
            outputPage.sealNamespace(r.outputNamespace); r.stage = Stage.Complete;
        } else revert WrongStage();
    }
    function _bonded(Run storage r, AlchemicalTopologyCatalog.Definition memory d) private {
        uint32[4] memory atoms; uint64 width = r.stage == Stage.Bonds ? 4 : r.stage == Stage.Angles ? 5 : 7;
        uint64 n = r.stage == Stage.Bonds ? 2 : r.stage == Stage.Angles ? 3 : 4;
        bytes32 sa = r.stage == Stage.Bonds ? d.a.bonds : r.stage == Stage.Angles ? d.a.angles : d.a.torsions;
        bytes32 sb = r.stage == Stage.Bonds ? d.b.bonds : r.stage == Stage.Angles ? d.b.angles : d.b.torsions;
        for (uint64 k; k < n; ++k) atoms[k] = uint32(uint256(_word(sa, r.cursor * width + k)));
        Evaluation memory a;
        Evaluation memory b;
        if(r.lambda==ONE){b=_bondedEndpoint(r,d,sb,width,atoms);a=b;}
        else{a=_bondedEndpoint(r,d,sa,width,atoms);b=r.lambda==bytes16(0)||sa==sb?a:_bondedEndpoint(r,d,sb,width,atoms);}
        _energy(r, d, uint8(r.stage) - uint8(Stage.Bonds), _mix(a.energy, b.energy, r.lambda));
        for (uint256 k; k < n; ++k) _force(r, atoms[k], _mixVector(a.forces[k], b.forces[k], r.lambda), false);
    }
    function _bondedEndpoint(Run storage r, AlchemicalTopologyCatalog.Definition memory d, bytes32 stream, uint64 width, uint32[4] memory atoms)
        private view returns (Evaluation memory e)
    {
        if(width==4)return _bondEvaluation(r,d,stream,atoms);
        if(width==5)return _angleEvaluation(r,d,stream,atoms);
        return _torsionEvaluation(r,d,stream,atoms);
    }
    function _bondEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*4+2);if(k==bytes16(0))return e;
        bytes16 r0=_value(stream,r.cursor*4+3);
        bytes16[3] memory zero;
        bytes16[3] memory displacement=_bondedDisplacement(r,d,atoms[0],atoms[1]);
        (e.energy,e.forces[0])=HarmonicBondKernel(modules.bond).evaluate(zero,displacement,k,r0);
        e.forces[1]=_negative(e.forces[0]);
    }
    function _angleEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*5+3);if(k==bytes16(0))return e;bytes16 theta=_value(stream,r.cursor*5+4);
        bytes16[3] memory zero;bytes16[3] memory a=_bondedDisplacement(r,d,atoms[1],atoms[0]);bytes16[3] memory c=_bondedDisplacement(r,d,atoms[1],atoms[2]);
        (e.energy,e.forces[0],e.forces[1],e.forces[2])=HarmonicAngleKernel(modules.angle).evaluate(a,zero,c,k,theta);
    }
    function _torsionEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*7+5);if(k==bytes16(0))return e;
        bytes16[3][4] memory p;p[0]=_bondedDisplacement(r,d,atoms[1],atoms[0]);p[2]=_bondedDisplacement(r,d,atoms[1],atoms[2]);
        bytes16[3] memory last=_bondedDisplacement(r,d,atoms[2],atoms[3]);
        for(uint256 axis;axis<3;++axis)p[3][axis]=FloatMath(modules.math).add(p[2][axis],last[axis]);
        uint32 n=uint32(uint256(_word(stream,r.cursor*7+4)));bytes16 phase=_value(stream,r.cursor*7+6);
        return _torsionCall(p,n,k,phase);
    }
    function _torsionCall(bytes16[3][4] memory p,uint32 n,bytes16 k,bytes16 phase)private view returns(Evaluation memory e){
        (e.energy,e.forces[0],e.forces[1],e.forces[2],e.forces[3])=PeriodicTorsionKernel(modules.torsion).evaluate(p[0],p[1],p[2],p[3],n,k,phase);
    }
    function _normalPair(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private {
        bytes16[3] memory displacement = _displacement(r, d, a, b);
        Pair memory p; p.a = a; p.b = b;
        (p.sigmaA, p.epsilonA) = _mixParticle(d.a.nonbonded, a, b);
        (p.sigmaB, p.epsilonB) = _mixParticle(d.b.nonbonded, a, b);
        (bytes16 energy, bytes16[3] memory force) = _lj(r, d, p, displacement, false);
        _energy(r, d, 3, energy); _force(r, a, force, false); _force(r, b, force, true);
        bytes16 chargeProduct = FloatMath(modules.math).mul(_charge(r, d, a), _charge(r, d, b));
        if (chargeProduct != bytes16(0)) {
            (energy, force) = EwaldRealSpaceKernel(modules.realSpace).evaluate(displacement,
                chargeProduct, d.prefactor, d.ewaldAlpha, d.cutoff);
            _energy(r, d, 4, energy); _force(r, a, force, false); _force(r, b, force, true);
        }
    }
    function _exceptionPair(Run storage r, AlchemicalTopologyCatalog.Definition memory d, Pair memory p) private {
        bytes16[3] memory displacement = _bondedDisplacement(r, d, p.a, p.b);
        if (p.kind == 2) {
            (bytes16 e, bytes16[3] memory f) = _lj(r, d, p, displacement, true);
            _energy(r, d, 3, e); _force(r, p.a, f, false); _force(r, p.b, f, true);
        }
        if (r.anyCharge || p.desiredA != bytes16(0) || p.desiredB != bytes16(0)) {
            (bytes16 e, bytes16[3] memory f) = EwaldCorrections(modules.corrections).exception(displacement,
                FloatMath(modules.math).mul(_charge(r, d, p.a), _charge(r, d, p.b)), _mix(p.desiredA, p.desiredB, r.lambda), d.prefactor, d.ewaldAlpha);
            _energy(r, d, 8, e); _force(r, p.a, f, false); _force(r, p.b, f, true);
        }
    }
    function _lj(Run storage r, AlchemicalTopologyCatalog.Definition memory d, Pair memory p, bytes16[3] memory displacement, bool direct)
        private view returns (bytes16 energy, bytes16[3] memory force)
    {
        FloatMath m = FloatMath(modules.math);
        if (p.epsilonA == bytes16(0) && p.epsilonB == bytes16(0)) return (energy, force);
        bytes16 squared;
        for (uint256 k; k < 3; ++k) squared = m.add(squared, m.mul(displacement[k], displacement[k]));
        bytes16 distance = m.sqrt(squared);
        if (!direct && m.compare(distance, d.cutoff) >= 0) return (energy, force);
        if (p.sigmaA == p.sigmaB && p.epsilonA == p.epsilonB) {
            bytes16[3] memory zero; (energy, force) = LennardJonesKernel(modules.lj).evaluate(zero, displacement, p.sigmaA, p.epsilonA);
        } else {
            SoftcoreLennardJonesKernel.Configuration memory c = SoftcoreLennardJonesKernel.Configuration(
                SoftcoreLennardJonesKernel.Endpoint(p.sigmaA,p.epsilonA),SoftcoreLennardJonesKernel.Endpoint(p.sigmaB,p.epsilonB),r.lambda,d.softcoreAlpha);
            (energy, force,) = SoftcoreLennardJonesKernel(modules.softcore).evaluate(displacement, c);
        }
        if (!direct && m.compare(distance, d.switchDistance) > 0) {
            return _applySwitch(displacement,distance,d,energy,force);
        }
    }
    function _applySwitch(bytes16[3] memory displacement,bytes16 distance,AlchemicalTopologyCatalog.Definition memory d,bytes16 energy,bytes16[3] memory force)
        private view returns(bytes16,bytes16[3] memory)
    {
        FloatMath m=FloatMath(modules.math);
        (bytes16 switching,bytes16 derivative)=_switch(distance,d.switchDistance,d.cutoff);
        bytes16 correction=m.div(m.mul(energy,derivative),distance);
        force=_combineForce(force,displacement,switching,correction);
        return(m.mul(switching,energy),force);
    }
    function _combineForce(bytes16[3] memory force,bytes16[3] memory displacement,bytes16 scale,bytes16 correction)private view returns(bytes16[3] memory){
        FloatMath m=FloatMath(modules.math);for(uint256 k;k<3;++k)force[k]=m.add(m.mul(scale,force[k]),m.mul(correction,displacement[k]));return force;
    }
    function _switch(bytes16 distance, bytes16 rs, bytes16 rc) private view returns (bytes16 value, bytes16 derivative) {
        FloatMath m = FloatMath(modules.math); bytes16 width = m.sub(rc, rs);
        bytes16 x = m.div(m.sub(distance, rs), width); bytes16 t = m.div(m.sub(rc, distance), width); bytes16 t2 = m.mul(t, t);
        value = m.mul(m.mul(t2,t), m.add(m.sub(m.fromUInt(10),m.mul(m.fromUInt(15),t)),m.mul(m.fromUInt(6),t2)));
        derivative = m.neg(m.div(m.mul(m.fromUInt(30),m.mul(m.mul(x,x),t2)),width));
    }
    function _mixParticle(bytes32 stream, uint32 a, uint32 b) private view returns (bytes16 sigma, bytes16 epsilon) {
        FloatMath m = FloatMath(modules.math);
        sigma = m.div(m.add(_value(stream,uint64(a)*3),_value(stream,uint64(b)*3)),TWO);
        epsilon = m.sqrt(m.mul(_value(stream,uint64(a)*3+1),_value(stream,uint64(b)*3+1)));
    }
    function _exception(Run storage, AlchemicalTopologyCatalog.Definition memory d, uint64 index) private view returns (Pair memory p) {
        uint64 offset = index * 6; p.a = uint32(uint256(_word(d.a.exceptions,offset))); p.b = uint32(uint256(_word(d.a.exceptions,offset+1)));
        p.kind = uint32(uint256(_word(d.a.exceptions,offset+2))); p.sigmaA = _value(d.a.exceptions,offset+3); p.epsilonA = _value(d.a.exceptions,offset+4); p.desiredA = _value(d.a.exceptions,offset+5);
        p.sigmaB = _value(d.b.exceptions,offset+3); p.epsilonB = _value(d.b.exceptions,offset+4); p.desiredB = _value(d.b.exceptions,offset+5);
    }
    function _position(Run storage r, uint32 atom) private view returns (bytes16[3] memory p) {
        for (uint256 k; k < 3; ++k) p[k] = _decode(IProductionWordState(r.input.sourcePage).readWord(r.input.sourceNamespace,uint256(r.input.offset)+uint256(atom)*r.input.stride+k));
    }
    function _displacement(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private view returns (bytes16[3] memory) {
        return OrthorhombicGeometry(modules.geometry).displacement(_position(r,a),_position(r,b),d.box);
    }
    function _bondedDisplacement(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private view returns (bytes16[3] memory value) {
        value = _displacement(r,d,a,b); FloatMath m = FloatMath(modules.math);
        for (uint256 k; k < 3; ++k) if (m.compare(m.abs(value[k]),m.div(d.box[k],TWO)) == 0) revert InvalidInput();
    }
    function _charge(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 atom) private view returns (bytes16) {
        return _mix(_value(d.a.nonbonded,uint64(atom)*3+2),_value(d.b.nonbonded,uint64(atom)*3+2),r.lambda);
    }
    function _term(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 atom) private view returns (bytes16,bytes16) {
        return EwaldReciprocalKernel(modules.reciprocal).structureFactorTerm(_position(r,atom),_charge(r,d,atom),r.mode,d.box);
    }
    function _force(Run storage r, uint32 atom, bytes16[3] memory force, bool negative) private {
        if(((uint128(force[0])|uint128(force[1])|uint128(force[2]))&0x7fffffffffffffffffffffffffffffff)==0)return;
        FloatMath m = FloatMath(modules.math); bytes32[] memory words = new bytes32[](3);
        for (uint256 k; k < 3; ++k) { bytes16 old = _decode(outputPage.readWord(r.outputNamespace,uint256(atom)*3+k)); words[k] = _encode(negative ? m.sub(old,force[k]) : m.add(old,force[k])); }
        outputPage.writeWords(r.outputNamespace,uint256(atom)*3,words);
    }
    function _energy(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint256 component, bytes16 energy) private {
        if((uint128(energy)&0x7fffffffffffffffffffffffffffffff)==0)return;
        uint256 start = uint256(d.atoms)*3; FloatMath m = FloatMath(modules.math);
        outputPage.writeWord(r.outputNamespace,start,_encode(m.add(_decode(outputPage.readWord(r.outputNamespace,start)),energy)));
        outputPage.writeWord(r.outputNamespace,start+component+1,_encode(m.add(_decode(outputPage.readWord(r.outputNamespace,start+component+1)),energy)));
    }
    function _mix(bytes16 a, bytes16 b, bytes16 lambda) private view returns (bytes16) {
        if (a == b || lambda == bytes16(0)) return a; if (lambda == ONE) return b;
        FloatMath m = FloatMath(modules.math); return m.add(m.mul(m.sub(ONE,lambda),a),m.mul(lambda,b));
    }
    function _mixVector(bytes16[3] memory a, bytes16[3] memory b, bytes16 lambda) private view returns (bytes16[3] memory out) { for (uint256 k; k < 3; ++k) out[k] = _mix(a[k],b[k],lambda); }
    function _negative(bytes16[3] memory x) private view returns (bytes16[3] memory out) { for (uint256 k; k < 3; ++k) out[k] = FloatMath(modules.math).neg(x[k]); }
    function _word(bytes32 stream, uint64 index) private view returns (bytes32) { return AlchemicalTopologyCatalog(modules.topology).word(stream,index); }
    function _value(bytes32 stream, uint64 index) private view returns (bytes16) { return _decode(_word(stream,index)); }
    function _modeCount(uint32 extent) private pure returns (uint32) { uint32 width = extent*2+1; return extent*(1+width+width*width); }
    function _modeAt(uint32 index,uint32 extent) private pure returns (int32[3] memory mode) {
        uint32 width = extent*2+1;
        if(index<extent){mode[2]=int32(index+1);return mode;}index-=extent;
        if(index<extent*width){mode[1]=int32(index/width+1);mode[2]=int32(index%width)-int32(extent);return mode;}index-=extent*width;
        mode[0]=int32(index/(width*width)+1);mode[1]=int32((index/width)%width)-int32(extent);mode[2]=int32(index%width)-int32(extent);
    }
    function _pairIndices(uint64 index,uint32 count) private pure returns(uint32 a,uint32 b){
        uint256 low;uint256 high=count-1;while(low+1<high){uint256 mid=(low+high)/2;if(mid*(2*uint256(count)-mid-1)/2<=index)low=mid;else high=mid;}
        a=uint32(low);b=uint32(low+1+index-low*(2*uint256(count)-low-1)/2);
    }
    function _assertRun(Run storage r) private view {
        _dependencies(r.input.protocol);
        if (AlchemicalTopologyCatalog(modules.topology).assertTopology(r.input.topology) != r.topologyCommitment
            || r.input.sourcePage.codehash != r.sourceHash || r.sourceWriter.codehash != r.sourceWriterHash) revert DependencyChanged();
        (,bool frozen)=IProductionWordState(r.input.sourcePage).namespaceInfo(r.input.sourceNamespace);
        (,,,,bytes32 snapshot)=IProductionWordState(r.input.sourcePage).snapshotInfo(r.input.sourceNamespace);
        if(!frozen||snapshot!=r.snapshotCommitment)revert DependencyChanged();
    }
    function _dependencies(bytes32 protocol) private view returns (bytes32 manifest) {
        if(address(outputPage)==address(0))revert NotConfigured();address[12] memory addresses=_addresses(modules);
        ExperimentRegistry registry=ExperimentRegistry(modules.registry);manifest=registry.assertProtocol(protocol);
        for(uint256 i;i<12;++i){if(addresses[i].codehash!=moduleHashes[i])revert DependencyChanged();if(i!=0)registry.assertModule(protocol,addresses[i],moduleHashes[i]);}
        if(address(outputPage).codehash!=outputPageHash)revert DependencyChanged();registry.assertModule(protocol,address(outputPage),outputPageHash);registry.assertModule(protocol,address(this),address(this).codehash);
    }
    function _addresses(Modules memory m) private pure returns(address[12] memory){return[m.registry,m.topology,m.math,m.geometry,m.bond,m.angle,m.torsion,m.lj,m.softcore,m.realSpace,m.reciprocal,m.corrections];}
    function _get(uint256 id) private view returns(Run storage r){r=runs[id];if(r.stage==Stage.Missing)revert InvalidInput();}
    function _decode(bytes32 word) private pure returns(bytes16 value){if(uint256(word)>>128!=0)revert InvalidInput();value=bytes16(uint128(uint256(word)));if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();}
    function _encode(bytes16 value) private pure returns(bytes32){if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();return bytes32(uint256(uint128(value)));}
}

contracts/core/AlchemicalTopologyCatalog.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";

interface IAlchemicalInputStreams {
    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 words);
    function readWord(bytes32 id, uint64 index) external view returns (bytes32);
}

/// @notice Complete, aligned endpoint parameter streams for a declared hybrid topology.
/// @dev Validation is incremental and does not certify chemical parameter quality.
///      Both endpoints retain every hybrid atom and have identical masses and term
///      indices. Dummy bonded networks/corrections require an explicit model policy.
contract AlchemicalTopologyCatalog {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged();
    enum Stage { Missing, Atoms, Bonds, Angles, Torsions, Exceptions, Complete }
    struct Endpoint {
        bytes32 particles; // mass, initial vx, vy, vz
        bytes32 nonbonded; // sigma, epsilon, charge
        bytes32 bonds; // atom a,b,k,r0
        bytes32 angles; // a,b,c,k,theta0
        bytes32 torsions; // a,b,c,d,periodicity,k,phase (proper or explicitly ordered periodic improper)
        bytes32 exceptions; // a,b,kind (1 excluded,2 direct),sigma,epsilon,desired charge product
    }
    struct Definition {
        bytes32 modelPolicy; bytes32 dummyPolicy; bytes32 positions;
        Endpoint a; Endpoint b;
        uint32 atoms; uint64 bonds; uint64 angles; uint64 torsions; uint64 exceptions;
        bytes16[3] box; bytes16 switchDistance; bytes16 cutoff; bytes16 prefactor;
        bytes16 ewaldAlpha; uint32 ewaldExtent; bytes16 softcoreAlpha;
    }
    struct Info { Stage stage; uint64 cursor; bytes32 commitment; bytes32 inputDigest; uint64 lastExceptionKey; }
    struct Record { Definition definition; Info info; bytes16[] lambdas; }
    address public immutable owner;
    IAlchemicalInputStreams public immutable inputs;
    FloatMath public immutable numericalMath;
    OrthorhombicGeometry public immutable geometry;
    bytes32[3] public dependencyHashes;
    uint256 public constant MAX_WORK = 8;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    mapping(bytes32 => Record) private records;
    event TopologyCreated(bytes32 indexed id, bytes32 inputDigest);
    event TopologySealed(bytes32 indexed id, bytes32 commitment);

    constructor(address owner_, address inputs_, address math_, address geometry_) {
        if (owner_ == address(0) || inputs_.code.length == 0 || math_.code.length == 0 || geometry_.code.length == 0
            || address(OrthorhombicGeometry(geometry_).numericalMath()) != math_) revert InvalidInput();
        owner = owner_; inputs = IAlchemicalInputStreams(inputs_); numericalMath = FloatMath(math_);
        geometry = OrthorhombicGeometry(geometry_); dependencyHashes = [inputs_.codehash, math_.codehash, geometry_.codehash];
    }

    function create(bytes32 id, Definition calldata d, bytes16[] calldata lambdas) external {
        _dependencies(); if (msg.sender != owner) revert Unauthorized();
        if (id == bytes32(0) || records[id].info.stage != Stage.Missing || d.atoms < 2
            || uint256(d.atoms) * 9 + 1 > type(uint32).max || d.modelPolicy == bytes32(0) || d.dummyPolicy == bytes32(0)
            || lambdas.length < 2 || lambdas.length > 16 || d.ewaldExtent == 0 || d.ewaldExtent > 32) revert InvalidInput();
        _positive(d.switchDistance); _positive(d.cutoff); _nonnegative(d.prefactor); _positive(d.ewaldAlpha); _positive(d.softcoreAlpha);
        if (numericalMath.compare(d.switchDistance, d.cutoff) >= 0
            || numericalMath.compare(numericalMath.mul(d.ewaldAlpha, d.cutoff), numericalMath.fromUInt(16)) > 0) revert InvalidInput();
        geometry.validateBox(d.box, d.cutoff);
        bytes32 digest = keccak256(abi.encode(bytes32("ORVIA-HYBRID-INPUT-v1"), block.chainid, address(this), id, d, lambdas, dependencyHashes));
        digest = _stream(digest, d.positions, uint64(d.atoms) * 3);
        digest = _endpoint(digest, d.a, d); digest = _endpoint(digest, d.b, d);
        if (lambdas[0] != bytes16(0) || lambdas[lambdas.length - 1] != ONE) revert InvalidInput();
        Record storage r = records[id]; r.definition = d; r.info = Info(Stage.Atoms, 0, bytes32(0), digest, 0);
        for (uint256 k; k < lambdas.length; ++k) {
            _nonnegative(lambdas[k]);
            if (numericalMath.compare(lambdas[k], ONE) > 0 || (k != 0 && numericalMath.compare(lambdas[k], lambdas[k-1]) <= 0)) revert InvalidInput();
            r.lambdas.push(lambdas[k]);
        }
        emit TopologyCreated(id, digest);
    }

    function advance(bytes32 id, uint256 work) external returns (uint256 processed, bool complete) {
        _dependencies(); if (work == 0 || work > MAX_WORK) revert InvalidInput(); Record storage r = _get(id);
        if (r.info.stage == Stage.Complete) revert WrongStage();
        while (processed < work && r.info.stage != Stage.Complete) {
            _skipEmpty(r);
            if (r.info.stage == Stage.Complete) break;
            if (r.info.stage == Stage.Atoms) _atom(r, r.info.cursor);
            else if (r.info.stage == Stage.Exceptions) _exception(r, r.info.cursor);
            else _term(r, r.info.cursor);
            ++r.info.cursor; ++processed;
            if (r.info.cursor == _count(r)) { r.info.cursor = 0; r.info.stage = Stage(uint8(r.info.stage) + 1); }
        }
        _skipEmpty(r); complete = r.info.stage == Stage.Complete;
        if (complete && r.info.commitment == bytes32(0)) {
            r.info.commitment = keccak256(abi.encode(r.info.inputDigest, bytes32("ALIGNED-HYBRID-COMPLETE")));
            emit TopologySealed(id, r.info.commitment);
        }
    }
    function definition(bytes32 id) external view returns (Definition memory) { return _get(id).definition; }
    function info(bytes32 id) external view returns (Info memory) { return _get(id).info; }
    function stateCount(bytes32 id) external view returns (uint8) { return uint8(_get(id).lambdas.length); }
    function lambdaAt(bytes32 id, uint8 state) external view returns (bytes16) {
        Record storage r = _get(id); if (state >= r.lambdas.length) revert InvalidInput(); return r.lambdas[state];
    }
    function assertTopology(bytes32 id) external view returns (bytes32) {
        _dependencies(); Record storage r = _get(id); if (r.info.stage != Stage.Complete) revert WrongStage(); return r.info.commitment;
    }
    function word(bytes32 stream, uint64 index) external view returns (bytes32) { _dependencies(); return inputs.readWord(stream, index); }

    function _stream(bytes32 digest, bytes32 id, uint64 count) private view returns (bytes32) {
        if (count == 0) { if (id != bytes32(0)) revert InvalidInput(); return keccak256(abi.encode(digest, id, count)); }
        (bytes32 commitment, uint64 words) = inputs.assertStream(id);
        if (words != count || commitment == bytes32(0)) revert InvalidInput();
        return keccak256(abi.encode(digest, id, commitment, words));
    }
    function _endpoint(bytes32 digest, Endpoint calldata e, Definition calldata d) private view returns (bytes32) {
        digest = _stream(digest, e.particles, uint64(d.atoms) * 4);
        digest = _stream(digest, e.nonbonded, uint64(d.atoms) * 3);
        digest = _stream(digest, e.bonds, _multiply(d.bonds, 4));
        digest = _stream(digest, e.angles, _multiply(d.angles, 5));
        digest = _stream(digest, e.torsions, _multiply(d.torsions, 7));
        return _stream(digest, e.exceptions, _multiply(d.exceptions, 6));
    }
    function _atom(Record storage r, uint64 atom) private view {
        Definition storage d = r.definition;
        for (uint64 k; k < 3; ++k) _decode(inputs.readWord(d.positions, atom * 3 + k));
        bytes16 ma = _decode(inputs.readWord(d.a.particles, atom * 4)); bytes16 mb = _decode(inputs.readWord(d.b.particles, atom * 4));
        _positive(ma); if (ma != mb) revert InvalidInput();
        for (uint64 k = 1; k < 4; ++k) {
            bytes32 a = inputs.readWord(d.a.particles, atom * 4 + k); bytes32 b = inputs.readWord(d.b.particles, atom * 4 + k);
            _decode(a); _decode(b); if (a != b) revert InvalidInput();
        }
        _particle(d.a.nonbonded, atom); _particle(d.b.nonbonded, atom);
    }
    function _particle(bytes32 stream, uint64 atom) private view {
        _positive(_decode(inputs.readWord(stream, atom * 3)));
        _nonnegative(_decode(inputs.readWord(stream, atom * 3 + 1)));
        _decode(inputs.readWord(stream, atom * 3 + 2));
    }
    function _term(Record storage r, uint64 index) private view {
        uint64 width = r.info.stage == Stage.Bonds ? 4 : r.info.stage == Stage.Angles ? 5 : 7;
        uint64 indices = r.info.stage == Stage.Bonds ? 2 : r.info.stage == Stage.Angles ? 3 : 5;
        bytes32 a = r.info.stage == Stage.Bonds ? r.definition.a.bonds : r.info.stage == Stage.Angles ? r.definition.a.angles : r.definition.a.torsions;
        bytes32 b = r.info.stage == Stage.Bonds ? r.definition.b.bonds : r.info.stage == Stage.Angles ? r.definition.b.angles : r.definition.b.torsions;
        for (uint64 k; k < width; ++k) {
            bytes32 x = inputs.readWord(a, index * width + k); bytes32 y = inputs.readWord(b, index * width + k);
            if (k < indices) {
                if (x != y || uint256(x) > type(uint32).max) revert InvalidInput();
                if (r.info.stage == Stage.Torsions && k == 4) { if (uint256(x) == 0 || uint256(x) > 64) revert InvalidInput(); }
                else if (uint256(x) >= r.definition.atoms) revert InvalidInput();
            } else {
                bytes16 va = _decode(x); bytes16 vb = _decode(y);
                if (k == indices) { _nonnegative(va); _nonnegative(vb); }
                else if (r.info.stage == Stage.Bonds) { _nonnegative(va); _nonnegative(vb); }
                else if (r.info.stage == Stage.Angles) {
                    _nonnegative(va); _nonnegative(vb);
                    if (numericalMath.compare(va, bytes16(0x4000921fb54442d18469898cc51701b8)) > 0
                        || numericalMath.compare(vb, bytes16(0x4000921fb54442d18469898cc51701b8)) > 0) revert InvalidInput();
                }
            }
        }
        uint64 atomFields = r.info.stage == Stage.Torsions ? 4 : indices;
        for (uint64 i; i < atomFields; ++i) for (uint64 j; j < i; ++j)
            if (inputs.readWord(a, index * width + i) == inputs.readWord(a, index * width + j)) revert InvalidInput();
    }
    function _exception(Record storage r, uint64 index) private {
        Definition storage d = r.definition; uint64 start = index * 6;
        uint256 a = uint256(inputs.readWord(d.a.exceptions, start)); uint256 b = uint256(inputs.readWord(d.a.exceptions, start + 1));
        if (a >= b || b >= d.atoms) revert InvalidInput();
        uint64 key = uint64(a * d.atoms + b);
        if (index != 0 && key <= r.info.lastExceptionKey) revert InvalidInput(); r.info.lastExceptionKey = key;
        for (uint64 k; k < 3; ++k) if (inputs.readWord(d.a.exceptions, start + k) != inputs.readWord(d.b.exceptions, start + k)) revert InvalidInput();
        uint256 kind = uint256(inputs.readWord(d.a.exceptions, start + 2)); if (kind != 1 && kind != 2) revert InvalidInput();
        for (uint256 endpoint; endpoint < 2; ++endpoint) {
            bytes32 stream = endpoint == 0 ? d.a.exceptions : d.b.exceptions;
            bytes16 sigma = _decode(inputs.readWord(stream, start + 3)); bytes16 epsilon = _decode(inputs.readWord(stream, start + 4));
            bytes16 charge = _decode(inputs.readWord(stream, start + 5));
            if (kind == 1) { if (sigma != bytes16(0) || epsilon != bytes16(0) || charge != bytes16(0)) revert InvalidInput(); }
            else { _positive(sigma); _nonnegative(epsilon); }
        }
    }
    function _count(Record storage r) private view returns (uint64) {
        if (r.info.stage == Stage.Atoms) return r.definition.atoms;
        if (r.info.stage == Stage.Bonds) return r.definition.bonds;
        if (r.info.stage == Stage.Angles) return r.definition.angles;
        if (r.info.stage == Stage.Torsions) return r.definition.torsions;
        if (r.info.stage == Stage.Exceptions) return r.definition.exceptions;
        return 0;
    }
    function _skipEmpty(Record storage r) private { while (r.info.stage != Stage.Complete && _count(r) == 0) { r.info.cursor = 0; r.info.stage = Stage(uint8(r.info.stage) + 1); } }
    function _multiply(uint64 x, uint64 y) private pure returns (uint64) { return x * y; }
    function _decode(bytes32 word_) private pure returns (bytes16 value) {
        if (uint256(word_) >> 128 != 0) revert InvalidInput(); value = bytes16(uint128(uint256(word_)));
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert InvalidInput();
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) value = bytes16(0);
    }
    function _positive(bytes16 x) private view { if (!numericalMath.isFinite(x) || numericalMath.compare(x, bytes16(0)) <= 0) revert InvalidInput(); }
    function _nonnegative(bytes16 x) private view { if (!numericalMath.isFinite(x) || numericalMath.compare(x, bytes16(0)) < 0) revert InvalidInput(); }
    function _dependencies() private view {
        if (address(inputs).codehash != dependencyHashes[0] || address(numericalMath).codehash != dependencyHashes[1]
            || address(geometry).codehash != dependencyHashes[2]) revert DependencyChanged();
    }
    function _get(bytes32 id) private view returns (Record storage r) { r = records[id]; if (r.info.stage == Stage.Missing) revert InvalidInput(); }
}

contracts/core/BankedInputCatalog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One of the catalog's 96 permanent banks. Global indices are namespaced
///      by stream ID; neither another stream nor a later routing cycle aliases them.
contract InputWordBank {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidRange();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    uint8 public immutable bankIndex;
    mapping(bytes32 => mapping(uint64 => bytes32)) private _words;

    constructor(address router_, uint8 bankIndex_) {
        if (router_ != msg.sender || router_.code.length == 0 || bankIndex_ >= 96)
            revert InvalidConfiguration();
        router = router_;
        routerCodeHash = router_.codehash;
        bankIndex = bankIndex_;
    }

    function writeWords(bytes32 stream, uint64 start, bytes32[] calldata values) external {
        if (msg.sender != router || msg.sender.codehash != routerCodeHash) revert Unauthorized();
        _range(start, values.length);
        if (stream == bytes32(0)) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) _words[stream][uint64(uint256(start) + i)] = values[i];
    }

    /// @dev Raw bank reads do not establish stream sealing or coverage. Consumers
    ///      must use the catalog's authenticated, sealed-stream read interface.
    function readWord(bytes32 stream, uint64 index) external view returns (bytes32) {
        _range(index, 1);
        return _words[stream][index];
    }

    function readWords(bytes32 stream, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) values[i] = _words[stream][uint64(uint256(start) + i)];
    }

    function _range(uint64 start, uint256 count) private view {
        if (count == 0 || count > 128 || uint256(start) + count - 1 > type(uint64).max
            || (uint256(start) / 4096) % 96 != bankIndex
            || count > 4096 - uint256(start) % 4096) revert InvalidRange();
    }
}

/// @notice Append-only input streams sharing exactly 96 permanent storage banks.
/// @dev Bank allocation is independent of model size and stream count. Storage
///      slots and gas still grow with words uploaded; 96 banks is not a size cap.
contract BankedInputCatalog {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidBankBatch();
    error BanksIncomplete();
    error BankChanged();
    error StreamExists();
    error UnknownStream();
    error StreamSealed();
    error IncompleteStream();
    error InvalidBatch();
    error InvalidRead();

    uint256 public constant BANK_COUNT = 96;
    uint256 public constant MAX_BANKS_PER_CREATION = 4;
    uint256 public constant PAGE_WORDS = 4096;
    uint256 public constant MAX_BATCH_WORDS = 128;
    address public immutable owner;
    uint8 public bankCount;
    bytes32 public banksCommitment;

    struct Bank { address instance; bytes32 codeHash; }
    struct Stream {
        bytes32 role;
        uint64 totalWords;
        uint64 appendedWords;
        bool isSealed;
        bool exists;
        bytes32 rollingDigest;
        bytes32 commitment;
    }
    Bank[96] private _banks;
    mapping(bytes32 => Stream) private _streams;

    event BankCreated(uint8 indexed bankIndex, address indexed instance, bytes32 codeHash);
    event BanksReady(bytes32 commitment);
    event StreamBegun(bytes32 indexed stream, bytes32 indexed role, uint64 totalWords);
    event WordsAppended(bytes32 indexed stream, uint64 start, uint32 count, bytes32 rollingDigest);
    event StreamFrozen(bytes32 indexed stream, bytes32 commitment, uint64 totalWords);

    modifier onlyOwner() { if (msg.sender != owner) revert Unauthorized(); _; }

    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        banksCommitment = keccak256(abi.encode(bytes32("ORVIA-INPUT-BANKS-v1"),
            block.chainid, address(this), BANK_COUNT, PAGE_WORDS));
    }

    /// @notice Allocate the next 1–4 banks. No other function creates contracts.
    function createBanks(uint8 count) external onlyOwner {
        if (count == 0 || count > MAX_BANKS_PER_CREATION || uint256(bankCount) + count > BANK_COUNT)
            revert InvalidBankBatch();
        for (uint256 i; i < count; ++i) {
            uint8 index = bankCount;
            address instance = address(new InputWordBank{salt: bytes32(uint256(index))}(address(this), index));
            bytes32 codeHash = instance.codehash;
            _banks[index] = Bank(instance, codeHash);
            banksCommitment = keccak256(abi.encode(banksCommitment, index, instance, codeHash));
            ++bankCount;
            emit BankCreated(index, instance, codeHash);
        }
        if (bankCount == BANK_COUNT) emit BanksReady(banksCommitment);
    }

    function bankInfo(uint8 index) external view returns (address instance, bytes32 codeHash) {
        if (index >= BANK_COUNT) revert InvalidRead();
        Bank storage bank = _banks[index];
        return (bank.instance, bank.codeHash);
    }

    function bankForWord(uint64 index) public pure returns (uint8) {
        return uint8((uint256(index) / PAGE_WORDS) % BANK_COUNT);
    }

    function beginStream(bytes32 id, bytes32 role, uint64 totalWords) external onlyOwner {
        if (bankCount != BANK_COUNT) revert BanksIncomplete();
        if (id == bytes32(0) || role == bytes32(0)) revert InvalidConfiguration();
        if (_streams[id].exists) revert StreamExists();
        Stream storage stream = _streams[id];
        stream.role = role;
        stream.totalWords = totalWords;
        stream.exists = true;
        stream.rollingDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-INPUT-v1"),
            block.chainid, address(this), id, role, totalWords, banksCommitment));
        emit StreamBegun(id, role, totalWords);
    }

    /// @notice Append the next canonical words, without caller-selected offsets.
    function appendWords(bytes32 id, bytes32[] calldata values) external onlyOwner {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        uint256 count = values.length;
        if (count == 0 || count > MAX_BATCH_WORDS || count > stream.totalWords - stream.appendedWords)
            revert InvalidBatch();
        uint64 start = stream.appendedWords;
        bytes32 digest = stream.rollingDigest;
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            Bank storage bank = _bank(bankForWord(index));
            InputWordBank(bank.instance).writeWords(id, index, values[done:done + length]);
            for (uint256 i; i < length; ++i)
                digest = keccak256(abi.encode(digest, uint64(uint256(index) + i), values[done + i]));
            done += length;
        }
        stream.appendedWords += uint64(count);
        stream.rollingDigest = digest;
        emit WordsAppended(id, start, uint32(count), digest);
    }

    function sealStream(bytes32 id) external onlyOwner returns (bytes32 commitment) {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        if (stream.appendedWords != stream.totalWords) revert IncompleteStream();
        commitment = keccak256(abi.encode(bytes32("ORVIA-SEALED-BANKS-v1"), block.chainid,
            address(this), id, stream.role, stream.totalWords, stream.rollingDigest, banksCommitment));
        stream.commitment = commitment;
        stream.isSealed = true;
        emit StreamFrozen(id, commitment, stream.totalWords);
    }

    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 wordCount) {
        Stream storage stream = _sealed(id);
        return (stream.commitment, stream.totalWords);
    }

    function readWord(bytes32 id, uint64 index) external view returns (bytes32) {
        Stream storage stream = _sealed(id);
        if (index >= stream.totalWords) revert InvalidRead();
        return InputWordBank(_bank(bankForWord(index)).instance).readWord(id, index);
    }

    function readWords(bytes32 id, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        Stream storage stream = _sealed(id);
        if (count > MAX_BATCH_WORDS || start > stream.totalWords || count > stream.totalWords - start)
            revert InvalidRead();
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            bytes32[] memory words = InputWordBank(_bank(bankForWord(index)).instance)
                .readWords(id, index, uint32(length));
            for (uint256 i; i < length; ++i) values[done + i] = words[i];
            done += length;
        }
    }

    /// @dev ABI-compatible with PartitionedInputCatalog. pageCount is the logical
    ///      4096-word block count, never a count of additional deployed contracts.
    function streamInfo(bytes32 id) external view returns (
        bytes32 role, uint64 totalWords, uint64 appendedWords, uint64 pageCount, bool isSealed, bytes32 commitment
    ) {
        Stream storage stream = _get(id);
        return (stream.role, stream.totalWords, stream.appendedWords,
            uint64((uint256(stream.appendedWords) + PAGE_WORDS - 1) / PAGE_WORDS), stream.isSealed, stream.commitment);
    }

    function _bank(uint8 index) private view returns (Bank storage bank) {
        bank = _banks[index];
        if (bank.instance.code.length == 0 || bank.instance.codehash != bank.codeHash) revert BankChanged();
    }
    function _get(bytes32 id) private view returns (Stream storage stream) {
        stream = _streams[id];
        if (!stream.exists) revert UnknownStream();
    }
    function _sealed(bytes32 id) private view returns (Stream storage stream) {
        stream = _get(id);
        if (!stream.isSealed) revert IncompleteStream();
    }
}

contracts/core/BankedWorkingState.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One member of a fixed, router-created pool. Namespace and GLOBAL word
///      index remain in the key when different logical pages reuse this bank.
contract BankedStateStorageBank {
    error Unauthorized();
    error InvalidRange();
    error InvalidEpoch();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    struct Version { uint64 epoch; bytes32 value; }
    mapping(bytes32 => mapping(uint256 => Version[])) private _history;

    constructor(address router_) {
        if (router_ != msg.sender || router_.code.length == 0) revert Unauthorized();
        router = router_; routerCodeHash = router_.codehash;
    }

    modifier onlyRouter() {
        if (msg.sender != router || router.codehash != routerCodeHash) revert Unauthorized();
        _;
    }

    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values, uint64 epoch)
        external onlyRouter
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, values.length);
        if (values.length == 0) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 length = versions.length;
            if (length != 0 && versions[length - 1].epoch > epoch) revert InvalidEpoch();
            if (length != 0 && versions[length - 1].epoch == epoch) versions[length - 1].value = values[i];
            else versions.push(Version(epoch, values[i]));
        }
    }

    function readWords(bytes32 namespace, uint256 start, uint256 count, uint64 epoch)
        external view onlyRouter returns (bytes32[] memory values)
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 low; uint256 high = versions.length;
            if (high == 0) continue;
            if (versions[high - 1].epoch <= epoch) { values[i] = versions[high - 1].value; continue; }
            // At most one version per strictly increasing uint64 epoch: <=64
            // predecessor-search rounds, independent of namespaces/page count.
            while (low < high) {
                uint256 middle = low + (high - low) / 2;
                if (versions[middle].epoch <= epoch) low = middle + 1;
                else high = middle;
            }
            if (low != 0) values[i] = versions[low - 1].value;
        }
    }

    function _range(uint256 start, uint256 count) private pure {
        if (start >= type(uint32).max || count > 128 || count > 4096 - (start % 4096)
            || count > uint256(type(uint32).max) - start) revert InvalidRange();
    }
}

/// @notice Mutable word namespaces and retained snapshots in a fixed bank pool.
/// @dev Matches the ShardedWorkingState consumer ABI. Provisioning is explicit:
///      reads of unprovisioned, unwritten banks are zero; writes fail closed.
///      No namespace, write, snapshot or seal operation deploys a child contract.
contract BankedWorkingState {
    error Unauthorized();
    error InvalidWriter();
    error InvalidBankCount();
    error InvalidNamespace();
    error NamespaceExists();
    error UnknownNamespace();
    error InvalidCapacity();
    error NamespaceSealed();
    error InvalidBatch();
    error OutOfBounds();
    error InvalidSnapshotSource();
    error NotSnapshot();
    error EpochExhausted();
    error BankUnavailable();
    error BankChanged();

    uint256 public constant MAX_CAPACITY_WORDS = type(uint32).max;
    uint256 public constant MAX_BATCH_WORDS = 128;
    uint256 public constant SHARD_WORDS = 4096;
    uint256 public constant MAX_BANKS = 128;
    uint256 public constant MAX_BANKS_PER_DEPLOY = 4;
    address public immutable writer;
    bytes32 public immutable writerCodeHash;
    uint16 public immutable bankCount;
    uint16 public deployedBankCount;
    bytes32 public bankRuntimeCodeHash;

    struct Bank { address page; bytes32 codeHash; }
    struct Namespace {
        uint32 capacityWords;
        bool isSealed;
        bool isSnapshot;
        uint64 epoch;
        bytes32 source;
        bytes32 writeDigest;
        bytes32 commitment;
    }
    mapping(uint256 => Bank) private _banks;
    mapping(bytes32 => Namespace) private _namespaces;

    event BankDeployed(uint256 indexed index, address indexed page, bytes32 codeHash);
    event NamespaceCreated(bytes32 indexed namespace, uint32 capacityWords);
    event WordsWritten(bytes32 indexed namespace, uint256 start, uint256 count, bytes32 writeDigest);
    event NamespaceFrozen(bytes32 indexed namespace);
    event SnapshotCreated(bytes32 indexed source, bytes32 indexed snapshot, uint64 epoch, bytes32 commitment);

    modifier onlyWriter() {
        if (msg.sender != writer || writer.codehash != writerCodeHash) revert Unauthorized();
        _;
    }

    constructor(address writer_, uint16 bankCount_) {
        if (writer_ == address(0) || writer_.code.length == 0) revert InvalidWriter();
        if (bankCount_ == 0 || bankCount_ > MAX_BANKS) revert InvalidBankCount();
        writer = writer_; writerCodeHash = writer_.codehash; bankCount = bankCount_;
    }

    /// @notice Anyone may pay to provision the next <=4 predetermined banks.
    /// @dev Cannot register arbitrary code, replace a bank or grow the fixed pool.
    function deployBanks(uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_BANKS_PER_DEPLOY) revert InvalidBatch();
        uint256 next = deployedBankCount;
        while (processed < work && next < bankCount) {
            address page = address(new BankedStateStorageBank{salt: bytes32(next)}(address(this)));
            bytes32 codeHash = page.codehash;
            if (next == 0) bankRuntimeCodeHash = codeHash;
            else if (codeHash != bankRuntimeCodeHash) revert BankChanged();
            _banks[next] = Bank(page, codeHash);
            emit BankDeployed(next, page, codeHash);
            ++next; ++processed;
        }
        deployedBankCount = uint16(next);
        complete = next == bankCount;
    }

    function createNamespace(bytes32 namespace, uint32 capacityWords) external onlyWriter {
        if (namespace == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[namespace].capacityWords != 0) revert NamespaceExists();
        if (capacityWords == 0) revert InvalidCapacity();
        Namespace storage n = _namespaces[namespace];
        n.capacityWords = capacityWords; n.epoch = 1;
        n.writeDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-STATE-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, namespace, capacityWords));
        emit NamespaceCreated(namespace, capacityWords);
    }

    function writeWord(bytes32 namespace, uint256 index, bytes32 value) external onlyWriter {
        bytes32[] memory values = new bytes32[](1); values[0] = value;
        _write(namespace, index, values);
    }
    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values) external onlyWriter {
        _write(namespace, start, values);
    }
    function _write(bytes32 namespace, uint256 start, bytes32[] memory values) private {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        if (values.length == 0 || values.length > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(n.capacityWords, start, values.length);
        uint256 done;
        while (done < values.length) {
            uint256 index = start + done;
            uint256 count = values.length - done;
            if (count > SHARD_WORDS - (index % SHARD_WORDS)) count = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page == address(0)) revert BankUnavailable();
            _assertBank(bank);
            bytes32[] memory chunk = new bytes32[](count);
            for (uint256 i; i < count; ++i) {
                chunk[i] = values[done + i];
                n.writeDigest = keccak256(abi.encode(n.writeDigest, index + i, chunk[i]));
            }
            BankedStateStorageBank(bank.page).writeWords(namespace, index, chunk, n.epoch);
            done += count;
        }
        emit WordsWritten(namespace, start, values.length, n.writeDigest);
    }

    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32) {
        return _read(namespace, index, 1)[0];
    }
    function readWords(bytes32 namespace, uint256 start, uint256 count) external view returns (bytes32[] memory) {
        return _read(namespace, start, count);
    }
    function _read(bytes32 namespace, uint256 start, uint256 count) private view returns (bytes32[] memory values) {
        Namespace storage viewNamespace = _get(namespace);
        if (count > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(viewNamespace.capacityWords, start, count);
        bytes32 source = viewNamespace.isSnapshot ? viewNamespace.source : namespace;
        uint64 epoch = viewNamespace.isSnapshot ? viewNamespace.epoch : _namespaces[source].epoch;
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint256 index = start + done;
            uint256 length = count - done;
            if (length > SHARD_WORDS - (index % SHARD_WORDS)) length = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page != address(0)) {
                _assertBank(bank);
                bytes32[] memory chunk = BankedStateStorageBank(bank.page).readWords(source, index, length, epoch);
                for (uint256 i; i < length; ++i) values[done + i] = chunk[i];
            }
            done += length;
        }
    }

    /// @dev Only the pinned writer establishes scientific completion and derives
    ///      snapshot names from complete run/step identity. Storage does not infer it.
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external onlyWriter returns (bytes32 commitment) {
        Namespace storage n = _get(source);
        if (n.isSnapshot) revert InvalidSnapshotSource();
        if (snapshot == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[snapshot].capacityWords != 0) revert NamespaceExists();
        if (n.epoch == type(uint64).max) revert EpochExhausted();
        Namespace storage s = _namespaces[snapshot];
        s.capacityWords = n.capacityWords; s.isSealed = true; s.isSnapshot = true;
        s.epoch = n.epoch; s.source = source; s.writeDigest = n.writeDigest;
        commitment = keccak256(abi.encode(bytes32("ORVIA-BANKED-SNAPSHOT-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, source, snapshot, s.epoch, s.capacityWords, s.writeDigest));
        s.commitment = commitment; ++n.epoch;
        emit SnapshotCreated(source, snapshot, s.epoch, commitment);
    }
    function snapshotInfo(bytes32 snapshot) external view returns (
        bytes32 source, uint64 epoch, uint32 capacityWords, bytes32 writeDigest, bytes32 commitment
    ) {
        Namespace storage s = _get(snapshot);
        if (!s.isSnapshot) revert NotSnapshot();
        return (s.source, s.epoch, s.capacityWords, s.writeDigest, s.commitment);
    }
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacityWords, bool isSealed) {
        Namespace storage n = _get(namespace); return (n.capacityWords, n.isSealed);
    }
    function namespaceCommitment(bytes32 namespace) external view returns (bytes32 writeDigest, uint64 epoch) {
        Namespace storage n = _get(namespace); return (n.writeDigest, n.epoch);
    }
    function bankInfo(uint256 index) external view returns (address page, bytes32 codeHash) {
        if (index >= bankCount) revert OutOfBounds();
        Bank storage bank = _banks[index]; return (bank.page, bank.codeHash);
    }
    /// @notice Compatibility metadata: logical pages share physical bank addresses.
    function shardInfo(bytes32 namespace, uint256 shardIndex) external view returns (address page, bytes32 codeHash) {
        Namespace storage n = _get(namespace);
        if (shardIndex >= (uint256(n.capacityWords) + SHARD_WORDS - 1) / SHARD_WORDS) revert OutOfBounds();
        Bank storage bank = _banks[shardIndex % bankCount]; return (bank.page, bank.codeHash);
    }
    function sealNamespace(bytes32 namespace) external onlyWriter {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        n.isSealed = true; emit NamespaceFrozen(namespace);
    }
    function _assertBank(Bank storage bank) private view {
        if (bank.page.code.length == 0 || bank.page.codehash != bank.codeHash
            || bank.codeHash != bankRuntimeCodeHash) revert BankChanged();
    }
    function _get(bytes32 namespace) private view returns (Namespace storage n) {
        n = _namespaces[namespace]; if (n.capacityWords == 0) revert UnknownNamespace();
    }
    function _range(uint32 capacity, uint256 start, uint256 count) private pure {
        if (start > capacity || count > uint256(capacity) - start) revert OutOfBounds();
    }
}

contracts/core/ConstrainedDynamicsCoordi.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {ConstraintCatalog} from "./ConstraintCatalog.sol";
import {ConstraintSolver} from "./ConstraintSolver.sol";
import {NeighborList} from "./NeighborList.sol";
import {FloatMath} from "../math/FloatMath.sol";

interface IConstrainedDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function periodicInfo(bytes32 id) external view returns (bytes16[3] memory, bytes16, bytes16, bytes16, uint32);
}
interface IConstrainedDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface IConstrainedDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface IConstrainedDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface IConstrainedDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface IConstrainedDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface IConstrainedDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}
interface IConstrainedDynamicsIntegrator {
    function drift(bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextPosition, bytes16[3] memory halfVelocity);
    function kick(bytes16[3] calldata halfVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity);
}

interface IConstrainedGeometry {
    function displacement(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata box)
        external view returns (bytes16[3] memory);
    function validateBox(bytes16[3] calldata box, bytes16 cutoff) external view;
}
interface IConstrainedNonbonded {
    function ljKernel() external view returns (address);
    function coulombKernel() external view returns (address);
    function evaluate(bytes16[3] calldata displacement, bytes16 sigma, bytes16 epsilon,
        bytes16 chargeProduct, bytes16 prefactor, bytes16 switchDistance, bytes16 cutoff, bool exception)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}

/// @notice Bounded NVE SHAKE/RATTLE integration with atomic committed timesteps.
/// @dev Constraint coordinates must be consistently unwrapped with every
/// constrained component strictly within half a box. Unsupported images revert.
contract ConstrainedDynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();
    error ExperimentFailed();
    error InvalidConstraintImage();
    error InvalidSolverIdentity();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
    }
    Modules public modules;
    bytes32[12] public moduleCodeHashes;
    WorkingStatePage public statePage;
    NeighborList public neighborList;
    bytes32 public neighborCodeHash;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;
    ConstraintCatalog public immutable constraintCatalog;
    bytes32 public immutable catalogCodeHash;
    ConstraintSolver public constraintSolver;
    bytes32 public solverCodeHash;
    address public constraintKernel;
    bytes32 public constraintKernelCodeHash;
    struct Parameters {
        bytes16 dt; uint32 steps; bytes16 skin; bytes32 constraintSetId;
        bytes16 positionTolerance; bytes16 velocityTolerance; uint32 maxIterations;
    }

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingExceptions, ValidatingConstraints, PreparingInitial,
        InitialBonds, InitialAngles, InitialTorsions, InitialPairs, Drift,
        CreatePosition, UploadPositionAtoms, UploadPositionConstraints, SolvePosition,
        CheckPositionImages, ApplyPosition, PreparingNext,
        NextBonds, NextAngles, NextTorsions, NextPairs, Kick,
        CreateVelocity, UploadVelocityAtoms, UploadVelocityConstraints, SolveVelocity,
        ApplyVelocity, Completed, Failed
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        bytes16 skin;
        bytes32 constraintSetId;
        bytes32 constraintCommitment;
        bytes32 problemId;
        bytes32 problemCommitment;
        bytes16 positionTolerance;
        bytes16 velocityTolerance;
        uint32 maxIterations;
        uint32 constraintCount;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; }
    struct ParticleParameters { bytes16 sigma; bytes16 epsilon; bytes16 charge; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event ConstraintFailure(uint256 indexed experimentId, bytes32 problemId);
    event StepCommitted(uint256 indexed experimentId, uint256 completedSteps, uint256 activeBuffer);

    constructor(address owner_, Modules memory modules_, address catalog_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        if (catalog_.code.length == 0 || address(ConstraintCatalog(catalog_).dataset()) != modules_.dataset ||
            address(ConstraintCatalog(catalog_).numericalMath()) != modules_.math) revert InvalidConfiguration();
        constraintCatalog = ConstraintCatalog(catalog_); catalogCodeHash = catalog_.codehash;
        modules = modules_;
        address[12] memory addresses = _moduleAddresses(modules_);
        bytes32[12] memory hashes;
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 12; ++i) {
            if (IConstrainedDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (IConstrainedDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            IConstrainedDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        if (IConstrainedNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
            IConstrainedNonbonded(modules_.nonbonded).coulombKernel() != modules_.coulomb) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes, catalog_, catalog_.codehash));
    }

    function bindWorkingPage(address page, address neighbors, address solver_) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this) || neighbors.code.length == 0)
            revert InvalidConfiguration();
        NeighborList list = NeighborList(neighbors);
        if (list.writer() != address(this) || address(list.statePage()) != page ||
            address(list.numericalMath()) != modules.math || address(list.geometry()) != modules.geometry) revert InvalidConfiguration();
        if (solver_.code.length == 0) revert InvalidConfiguration();
        ConstraintSolver solver = ConstraintSolver(solver_);
        if (solver.writer() != address(this) || address(solver.numericalMath()) != modules.math) revert InvalidConfiguration();
        constraintSolver = solver; solverCodeHash = solver_.codehash;
        constraintKernel = address(solver.kernel()); constraintKernelCodeHash = constraintKernel.codehash;
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        neighborList = list; neighborCodeHash = neighbors.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash, neighbors, neighbors.codehash, solver_, solver_.codehash, solver.configurationHash()));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, Parameters calldata parameters)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(parameters.dt); _requirePositive(parameters.skin);
        _requirePositive(parameters.positionTolerance); _requirePositive(parameters.velocityTolerance);
        if (parameters.steps == 0 || parameters.steps > MAX_STEPS || parameters.maxIterations == 0 ||
            parameters.maxIterations > constraintSolver.MAX_ITERATIONS()) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = IConstrainedDynamicsData(modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = IConstrainedDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 ||
            r.pairCount != uint256(r.atomCount) * (r.atomCount - 1) / 2) revert InvalidInput();
        (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount) =
            IConstrainedDynamicsData(modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount) revert InvalidInput();
        _requirePositive(r.switchDistance); _requirePositive(r.cutoff); _requireNonnegative(r.prefactor);
        if (FloatMath(modules.math).compare(r.switchDistance, r.cutoff) >= 0) revert InvalidInput();
        IConstrainedGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = parameters.dt; r.skin = parameters.skin;
        r.targetSteps = parameters.steps;
        _registerConstraints(r, parameters);
        r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINED-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINED-RUN-v1"), block.chainid, address(this),
            experimentId, manifest, datasetId, datasetCommitment, configurationHash, parameters, r.constraintCommitment, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        neighborList.registerList(r.stateNamespace, r.atomCount, r.box, r.cutoff, parameters.skin);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        if (r.status == Status.Failed) revert ExperimentFailed();
        _assertDependencies(r.protocolId);
        if (IConstrainedDynamicsData(modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        if (constraintCatalog.assertSet(r.constraintSetId) != r.constraintCommitment) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed && r.status != Status.Failed) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                (uint256 used, bool ready) = neighborList.advance(r.stateNamespace, workLimit - processed);
                processed += used;
                if (ready) { r.status = Status(uint8(r.status) + 1); r.cursor = 0; }
            } else if (r.status == Status.SolvePosition || r.status == Status.SolveVelocity) {
                processed += _advanceSolver(r, experimentId, workLimit - processed);
            } else {
                _process(r);
                ++processed;
                ++r.cursor;
                if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
            }
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 completedSteps, uint256 targetSteps, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }

    function stateAt(uint256 experimentId, uint256 atom) external view returns (
        bytes16[3] memory position, bytes16[3] memory velocity, bytes16[3] memory force
    ) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(uint256 experimentId) external view returns (
        bytes16 dt, uint32 bondCount, uint32 angleCount, uint32 torsionCount, uint32 pairCount, bytes32 datasetCommitment
    ) {
        Run storage r = _get(experimentId);
        return (r.dt, r.bondCount, r.angleCount, r.torsionCount, r.pairCount, r.datasetCommitment);
    }

    function neighborParameters(uint256 experimentId) external view returns (bytes16 skin, address list) {
        return (_get(experimentId).skin, address(neighborList));
    }

    function periodicParameters(uint256 experimentId) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Run storage r = _get(experimentId);
        return (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount);
    }

    function constraintParameters(uint256 id) external view returns
        (bytes32 setId, bytes32 commitment, bytes16 positionTolerance, bytes16 velocityTolerance, uint32 maxIterations, bytes32 problemId)
    {
        Run storage r = _get(id);
        return (r.constraintSetId, r.constraintCommitment, r.positionTolerance, r.velocityTolerance, r.maxIterations, r.problemId);
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions) _validate(r, _kind(r.status), r.cursor);
        else if (r.status == Status.ValidatingConstraints) _validateInitialConstraint(r);
        else if (r.status >= Status.InitialBonds && r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status == Status.CreatePosition || r.status == Status.CreateVelocity) _createProblem(r);
        else if (r.status == Status.UploadPositionAtoms || r.status == Status.UploadVelocityAtoms) _uploadAtom(r);
        else if (r.status == Status.UploadPositionConstraints || r.status == Status.UploadVelocityConstraints) _uploadConstraint(r);
        else if (r.status == Status.CheckPositionImages) _checkProjectedImage(r);
        else if (r.status == Status.ApplyPosition || r.status == Status.ApplyVelocity) _applySolution(r);
        else if (r.status >= Status.NextBonds && r.status <= Status.NextPairs) _calculate(r, 1-r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (r.status == Status.ApplyVelocity) {
            r.activeBuffer = 1-r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace); r.status = Status.Completed; return;
            }
            r.status = Status.Drift;
        } else {
            if (r.status == Status.UploadPositionConstraints || r.status == Status.UploadVelocityConstraints) {
                constraintSolver.sealProblem(r.problemId);
                r.problemCommitment = constraintSolver.problemInfo(r.problemId).commitment;
            }
            r.status = Status(uint8(r.status)+1);
        }
        r.cursor = 0;
        while (true) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                neighborList.beginEvaluation(r.stateNamespace, r.status == Status.PreparingInitial ? r.activeBuffer : 1-r.activeBuffer);
                return;
            }
            if (_stageCount(r) != 0) return;
            r.status = Status(uint8(r.status)+1);
        }
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (r.status == Status.ValidatingConstraints || r.status == Status.UploadPositionConstraints ||
            r.status == Status.UploadVelocityConstraints || r.status == Status.CheckPositionImages) return r.constraintCount;
        if (r.status == Status.CreatePosition || r.status == Status.CreateVelocity ||
            r.status == Status.SolvePosition || r.status == Status.SolveVelocity) return 1;
        if (r.status == Status.Loading || r.status == Status.Drift || r.status == Status.Kick ||
            r.status == Status.UploadPositionAtoms || r.status == Status.UploadVelocityAtoms ||
            r.status == Status.ApplyPosition || r.status == Status.ApplyVelocity) return r.atomCount;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        (,,, uint32 candidates,,,,) = neighborList.listInfo(r.stateNamespace);
        return candidates;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingExceptions) return uint8(status)-2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status)-8;
        if (status >= Status.NextBonds && status <= Status.NextPairs) return uint8(status)-20;
        revert InvalidInput();
    }

    function _registerConstraints(Run storage r, Parameters calldata p) private {
        r.constraintCommitment = constraintCatalog.assertSet(p.constraintSetId);
        ConstraintCatalog.Info memory info = constraintCatalog.setInfo(p.constraintSetId);
        if (info.datasetId != r.datasetId || info.datasetCommitment != r.datasetCommitment || info.atomCount != r.atomCount) revert InvalidInput();
        r.constraintSetId = p.constraintSetId; r.constraintCount = info.constraintCount;
        r.positionTolerance = p.positionTolerance; r.velocityTolerance = p.velocityTolerance; r.maxIterations = p.maxIterations;
    }
    function _constraint(Run storage r) private view returns (ConstraintCatalog.Constraint memory) {
        return constraintCatalog.constraintAt(r.constraintSetId, r.cursor);
    }
    function _rawDifference(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16[3] memory d) {
        for (uint256 j; j < 3; ++j) d[j] = FloatMath(modules.math).sub(b[j], a[j]);
    }
    function _checkImage(Run storage r, bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16[3] memory d) {
        FloatMath m = FloatMath(modules.math); d = _rawDifference(a,b);
        for (uint256 j; j < 3; ++j) {
            if (m.compare(m.abs(d[j]), m.div(r.box[j],m.fromUInt(2))) >= 0) revert InvalidConstraintImage();
        }
    }
    function _dotConstraint(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16 total) {
        FloatMath m = FloatMath(modules.math);
        for (uint256 j; j < 3; ++j) total = m.add(total,m.mul(a[j],b[j]));
    }
    function _validateInitialConstraint(Run storage r) private view {
        ConstraintCatalog.Constraint memory c = _constraint(r);
        bytes16[3] memory d = _checkImage(r,_readVector(r,0,c.a,0),_readVector(r,0,c.b,0));
        FloatMath m = FloatMath(modules.math); bytes16 target = m.mul(c.distance,c.distance);
        bytes16 squared = _dotConstraint(d,d); _requirePositive(squared); _requirePositive(target);
        if (m.compare(m.div(m.abs(m.sub(squared,target)),target),r.positionTolerance) > 0) revert InvalidInput();
        bytes16[3] memory v = _rawDifference(_readVector(r,0,c.a,3),_readVector(r,0,c.b,3));
        if (m.compare(m.abs(m.div(_dotConstraint(d,v),squared)),r.velocityTolerance) > 0) revert InvalidInput();
    }
    function _isPosition(Run storage r) private view returns (bool) { return r.status < Status.CreateVelocity; }
    function _sourceCommitment(Run storage r, bool position) private view returns (bytes32) {
        return keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-SOURCE-v1"),r.commitment,r.completedSteps,position));
    }
    function _createProblem(Run storage r) private {
        bool position = _isPosition(r);
        r.problemId = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-STEP-v1"),r.stateNamespace,r.completedSteps,position));
        r.problemCommitment = bytes32(0);
        constraintSolver.createProblem(r.problemId,_sourceCommitment(r,position),
            position ? ConstraintSolver.Mode.Position : ConstraintSolver.Mode.Velocity,
            r.atomCount,r.constraintCount,position ? r.positionTolerance : r.velocityTolerance,r.maxIterations);
    }
    function _uploadAtom(Run storage r) private {
        bool position = _isPosition(r); uint256 next = 1-r.activeBuffer;
        ConstraintSolver.AtomInput[] memory inputs = new ConstraintSolver.AtomInput[](1);
        inputs[0] = ConstraintSolver.AtomInput(
            _readVector(r,position ? r.activeBuffer : next,r.cursor,0),
            _readVector(r,next,r.cursor,position ? 0 : 3),_mass(r,r.cursor));
        constraintSolver.appendAtoms(r.problemId,inputs);
    }
    function _uploadConstraint(Run storage r) private {
        ConstraintCatalog.Constraint memory c = _constraint(r); uint256 next = 1-r.activeBuffer;
        _checkImage(r,_readVector(r,r.activeBuffer,c.a,0),_readVector(r,r.activeBuffer,c.b,0));
        _checkImage(r,_readVector(r,next,c.a,0),_readVector(r,next,c.b,0));
        ConstraintSolver.Constraint[] memory entries = new ConstraintSolver.Constraint[](1);
        entries[0] = ConstraintSolver.Constraint(c.a,c.b,_isPosition(r) ? c.distance : bytes16(0));
        constraintSolver.appendConstraints(r.problemId,entries);
    }
    function _assertProblem(Run storage r) private view returns (ConstraintSolver.Info memory info) {
        info = constraintSolver.problemInfo(r.problemId); bool position = _isPosition(r);
        if (info.sourceCommitment != _sourceCommitment(r,position) || info.commitment != r.problemCommitment ||
            info.mode != (position ? ConstraintSolver.Mode.Position : ConstraintSolver.Mode.Velocity) ||
            info.atomCount != r.atomCount || info.constraintCount != r.constraintCount ||
            info.loadedAtoms != r.atomCount || info.loadedConstraints != r.constraintCount ||
            info.tolerance != (position ? r.positionTolerance : r.velocityTolerance) ||
            info.maxIterations != r.maxIterations) revert InvalidSolverIdentity();
    }
    function _advanceSolver(Run storage r, uint256 experimentId, uint256 remaining) private returns (uint256 used) {
        ConstraintSolver.Info memory info = _assertProblem(r);
        if (info.status == ConstraintSolver.Status.Correcting || info.status == ConstraintSolver.Status.Checking) {
            (used,) = constraintSolver.advance(r.problemId,remaining); info = _assertProblem(r);
        }
        if (info.status == ConstraintSolver.Status.Failed) {
            r.status = Status.Failed;
            statePage.sealNamespace(r.stateNamespace);
            emit ConstraintFailure(experimentId,r.problemId);
        } else if (info.status == ConstraintSolver.Status.Converged) {
            r.status = Status(uint8(r.status)+1); r.cursor = 0;
        } else if (info.status != ConstraintSolver.Status.Correcting && info.status != ConstraintSolver.Status.Checking) revert InvalidSolverIdentity();
    }
    function _checkProjectedImage(Run storage r) private view {
        ConstraintCatalog.Constraint memory c = _constraint(r);
        _checkImage(r,constraintSolver.solutionAt(r.problemId,c.a),constraintSolver.solutionAt(r.problemId,c.b));
    }
    function _applySolution(Run storage r) private {
        ConstraintSolver.Info memory info = _assertProblem(r);
        if (info.status != ConstraintSolver.Status.Converged) revert InvalidSolverIdentity();
        bytes16[3] memory solution = constraintSolver.solutionAt(r.problemId,r.cursor);
        bool position = _isPosition(r); uint256 next = 1-r.activeBuffer;
        bytes32[] memory words = new bytes32[](position ? 6 : 3);
        bytes16[3] memory oldPosition;
        if (position) oldPosition = _readVector(r,r.activeBuffer,r.cursor,0);
        for (uint256 j; j < 3; ++j) {
            words[j] = _encode(solution[j]);
            if (position) words[j+3] = _encode(FloatMath(modules.math).div(FloatMath(modules.math).sub(solution[j],oldPosition[j]),r.dt));
        }
        statePage.writeWords(r.stateNamespace,_vectorIndex(r,next,r.cursor,position ? 0 : 3),words);
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        _parameters(r, atom);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            words[d + 3] = _encode(_decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)));
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
        (bytes16[3] memory position, bytes16[3] memory halfVelocity) = IConstrainedDynamicsIntegrator(modules.integrator).drift(
            _readVector(r, r.activeBuffer, r.cursor, 0), _readVector(r, r.activeBuffer, r.cursor, 3),
            _readVector(r, r.activeBuffer, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = IConstrainedDynamicsIntegrator(modules.integrator).kick(
            _readVector(r, next, r.cursor, 3), _readVector(r, next, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) { _requireFinite(velocity[d]); words[d] = _encode(velocity[d]); }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 3), words);
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = IConstrainedDynamicsPairKernel(modules.bond).evaluate(
            zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            IConstrainedDynamicsAngleKernel(modules.angle).evaluate(_bondedDisplacement(r, buffer, a.b, a.a),
                zero, _bondedDisplacement(r, buffer, a.b, a.c), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            IConstrainedDynamicsTorsionKernel(modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, neighborList.pairIndexAt(r.stateNamespace, index));
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = IConstrainedNonbonded(modules.nonbonded).evaluate(
            displacement, p.sigma, p.epsilon, p.chargeProduct,
            r.prefactor, r.switchDistance, r.cutoff, p.kind == 2);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory)
    {
        return IConstrainedGeometry(modules.geometry).displacement(
            _readVector(r, buffer, a, 0), _readVector(r, buffer, b, 0), r.box);
    }

    function _bondedDisplacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory displacement)
    {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(Run storage r, bytes16[3] memory displacement) private view {
        FloatMath m = FloatMath(modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) == 0) revert InvalidInput();
        }
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(modules.math).compare(a.theta0, IConstrainedDynamicsElementary(modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = IConstrainedDynamicsElementary(modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _parameters(Run storage r, uint256 atom) private view returns (ParticleParameters memory p) {
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon);
    }

    function _exception(Run storage r, uint256 index) private view returns (Pair memory p) {
        IConstrainedDynamicsData data = IConstrainedDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readExceptionWord(r.datasetId, offset + 1), r.atomCount);
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(data.readExceptionWord(r.datasetId, offset + 5));
        if (p.kind == 1) {
            if (p.sigma != bytes16(0) || p.epsilon != bytes16(0) || p.chargeProduct != bytes16(0)) revert InvalidInput();
        } else { _requirePositive(p.sigma); _requireNonnegative(p.epsilon); }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
        neighborList.setException(r.stateNamespace, p.a, p.b, uint8(p.kind));
    }

    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][uint256(p.a) * r.atomCount + p.b];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        p.chargeProduct = m.mul(a.charge, b.charge);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(IConstrainedDynamicsData(modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[12] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 12; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash || address(neighborList).codehash != neighborCodeHash)
            revert ModuleCodeChanged();
        if (address(constraintCatalog).codehash != catalogCodeHash || address(constraintSolver).codehash != solverCodeHash ||
            constraintKernel.codehash != constraintKernelCodeHash) revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 12; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(neighborList), neighborCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
        registry.assertModule(protocolId,address(constraintCatalog),catalogCodeHash);
        registry.assertModule(protocolId,address(constraintSolver),solverCodeHash);
        registry.assertModule(protocolId,constraintKernel,constraintKernelCodeHash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[12] memory) {
        return [m.registry, m.dataset, m.math, m.integrator, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary, m.geometry, m.nonbonded];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/ConstraintCatalog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

interface IConstraintDataset {
    function assertDataset(bytes32 id) external view returns (bytes32);
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
}

/// @notice Owner-authored append-only constraint streams bound to a sealed dataset.
contract ConstraintCatalog {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged();
    uint256 public constant MAX_UPLOAD = 8;
    address public immutable owner;
    IConstraintDataset public immutable dataset;
    FloatMath public immutable numericalMath;
    bytes32 public immutable datasetCodeHash;
    bytes32 public immutable mathCodeHash;
    struct Constraint { uint32 a; uint32 b; bytes16 distance; }
    struct Info { bytes32 datasetId; bytes32 datasetCommitment; bytes32 commitment; uint32 atomCount; uint32 constraintCount; uint32 loaded; bool isSealed; }
    struct Set { Info info; bytes32 digest; uint256 lastKey; mapping(uint256 => Constraint) constraints; }
    mapping(bytes32 => Set) private _sets;
    event Created(bytes32 indexed id, bytes32 indexed datasetId);
    event Sealed(bytes32 indexed id, bytes32 commitment);
    constructor(address owner_, address dataset_, address math_) {
        if (owner_ == address(0) || dataset_.code.length == 0 || math_.code.length == 0) revert InvalidInput();
        owner = owner_; dataset = IConstraintDataset(dataset_); numericalMath = FloatMath(math_);
        datasetCodeHash = dataset_.codehash; mathCodeHash = math_.codehash;
    }
    function createSet(bytes32 id, bytes32 datasetId, uint32 count) external {
        _onlyOwner();
        if (id == bytes32(0) || _sets[id].info.atomCount != 0) revert InvalidInput();
        bytes32 commitment = dataset.assertDataset(datasetId);
        (,, uint32 atoms,,,,) = dataset.datasetInfo(datasetId);
        if (atoms < 2 || atoms > 1024 || count == 0 || count > 16384 || uint256(count) > uint256(atoms)*(atoms-1)/2) revert InvalidInput();
        Set storage s = _sets[id];
        s.info = Info(datasetId, commitment, bytes32(0), atoms, count, 0, false);
        s.digest = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-SET-v1"), block.chainid, address(this), id,
            datasetId, commitment, atoms, count, datasetCodeHash, mathCodeHash));
        emit Created(id, datasetId);
    }
    function append(bytes32 id, Constraint[] calldata entries) external {
        _onlyOwner(); Set storage s = _sets[id];
        if (s.info.atomCount == 0 || s.info.isSealed) revert WrongStage();
        if (entries.length == 0 || entries.length > MAX_UPLOAD || entries.length > s.info.constraintCount-s.info.loaded) revert InvalidInput();
        for (uint256 j; j < entries.length; ++j) {
            Constraint memory c = entries[j];
            if (c.a >= c.b || c.b >= s.info.atomCount || !numericalMath.isFinite(c.distance) || numericalMath.compare(c.distance, bytes16(0)) <= 0) revert InvalidInput();
            uint256 key = uint256(c.a)*s.info.atomCount+c.b;
            if (s.info.loaded != 0 && key <= s.lastKey) revert InvalidInput();
            s.lastKey = key; uint256 index = s.info.loaded++;
            s.constraints[index] = c;
            s.digest = keccak256(abi.encode(s.digest, index, c));
        }
    }
    function seal(bytes32 id) external {
        _onlyOwner(); Set storage s = _sets[id];
        if (s.info.atomCount == 0 || s.info.isSealed || s.info.loaded != s.info.constraintCount) revert WrongStage();
        if (dataset.assertDataset(s.info.datasetId) != s.info.datasetCommitment) revert DependencyChanged();
        s.info.isSealed = true;
        s.info.commitment = keccak256(abi.encode(s.digest, s.info.constraintCount));
        emit Sealed(id, s.info.commitment);
    }
    function setInfo(bytes32 id) external view returns (Info memory) { return _sets[id].info; }
    function assertSet(bytes32 id) external view returns (bytes32) {
        _dependencies(); Info storage i = _sets[id].info;
        if (!i.isSealed) revert WrongStage();
        if (dataset.assertDataset(i.datasetId) != i.datasetCommitment) revert DependencyChanged();
        return i.commitment;
    }
    function constraintAt(bytes32 id, uint256 index) external view returns (Constraint memory) {
        if (!_sets[id].info.isSealed || index >= _sets[id].info.constraintCount) revert InvalidInput();
        return _sets[id].constraints[index];
    }
    function _onlyOwner() private view { if (msg.sender != owner) revert Unauthorized(); _dependencies(); }
    function _dependencies() private view {
        if (address(dataset).codehash != datasetCodeHash || address(numericalMath).codehash != mathCodeHash) revert DependencyChanged();
    }
}

contracts/core/ConstraintSolver.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {DistanceConstraintKernel} from "../kernels/DistanceConstraintKernel.sol";

/// @notice Bounded coupled SHAKE or RATTLE projection from immutable inputs.
/// @dev Uses consistently unwrapped whole-molecule coordinates. Periodic image
///      selection, timestep integration and velocity correction after SHAKE are
///      responsibilities of the consuming coordinator, not implemented here.
contract ConstraintSolver {
    error Unauthorized();
    error InvalidDependency();
    error DependencyChanged();
    error InvalidInput();
    error ProblemExists();
    error UnknownProblem();
    error WrongStage();
    error IncompleteInput();
    error OutOfBounds();
    error InvalidWorkLimit();
    error SolutionUnavailable();

    enum Mode { Position, Velocity }
    enum Status { Missing, Uploading, Correcting, Checking, Converged, Failed }
    struct AtomInput { bytes16[3] anchor; bytes16[3] current; bytes16 mass; }
    struct Constraint { uint32 a; uint32 b; bytes16 distance; }
    struct Info {
        bytes32 sourceCommitment;
        bytes32 commitment;
        Mode mode;
        Status status;
        uint32 atomCount;
        uint32 constraintCount;
        uint32 loadedAtoms;
        uint32 loadedConstraints;
        uint32 cursor;
        uint32 iterations;
        uint32 maxIterations;
        bytes16 tolerance;
        bytes16 maximumResidual;
    }
    struct Problem {
        Info info;
        bytes32 inputDigest;
        uint256 lastConstraintKey;
        mapping(uint256 => AtomInput) atoms;
        mapping(uint256 => Constraint) constraints;
    }

    address public immutable writer;
    FloatMath public immutable numericalMath;
    DistanceConstraintKernel public immutable kernel;
    bytes32 public immutable writerCodeHash;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable kernelCodeHash;
    bytes32 public immutable configurationHash;
    uint32 public constant MAX_ATOMS = 65536;
    uint32 public constant MAX_CONSTRAINTS = 262144;
    uint32 public constant MAX_ITERATIONS = 4096;
    uint256 public constant MAX_UPLOAD = 8;
    uint256 public constant MAX_WORK = 8;
    mapping(bytes32 => Problem) private _problems;

    event ProblemCreated(bytes32 indexed id, bytes32 sourceCommitment, Mode mode);
    event ProblemSealed(bytes32 indexed id, bytes32 commitment);
    event Advanced(bytes32 indexed id, uint256 processed, Status status, uint32 cursor, uint32 iterations);
    event Finished(bytes32 indexed id, Status status, uint32 iterations, bytes16 maximumResidual);

    constructor(address writer_, address math_, address kernel_) {
        if (writer_.code.length == 0 || math_.code.length == 0 || kernel_.code.length == 0)
            revert InvalidDependency();
        if (address(DistanceConstraintKernel(kernel_).numericalMath()) != math_) revert InvalidDependency();
        writer = writer_;
        numericalMath = FloatMath(math_);
        kernel = DistanceConstraintKernel(kernel_);
        writerCodeHash = writer_.codehash;
        mathCodeHash = math_.codehash;
        kernelCodeHash = kernel_.codehash;
        configurationHash = keccak256(abi.encode(writer_, math_, kernel_,
            writer_.codehash, math_.codehash, kernel_.codehash));
    }

    function createProblem(bytes32 id, bytes32 sourceCommitment, Mode mode,
        uint32 atomCount, uint32 constraintCount, bytes16 tolerance, uint32 maxIterations) external
    {
        _onlyWriter();
        if (id == bytes32(0) || sourceCommitment == bytes32(0)) revert InvalidInput();
        if (_problems[id].info.status != Status.Missing) revert ProblemExists();
        if (atomCount < 2 || atomCount > MAX_ATOMS || constraintCount == 0 ||
            constraintCount > MAX_CONSTRAINTS || uint256(constraintCount) > uint256(atomCount) * (atomCount - 1) / 2 ||
            maxIterations == 0 || maxIterations > MAX_ITERATIONS) revert InvalidInput();
        _positive(tolerance);
        Problem storage p = _problems[id];
        p.info.sourceCommitment = sourceCommitment;
        p.info.mode = mode;
        p.info.status = Status.Uploading;
        p.info.atomCount = atomCount;
        p.info.constraintCount = constraintCount;
        p.info.tolerance = tolerance;
        p.info.maxIterations = maxIterations;
        p.inputDigest = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-INPUT-v1"),
            block.chainid, address(this), id, sourceCommitment, mode,
            atomCount, constraintCount, tolerance, maxIterations, configurationHash));
        emit ProblemCreated(id, sourceCommitment, mode);
    }

    function appendAtoms(bytes32 id, AtomInput[] calldata atoms) external {
        _onlyWriter();
        Problem storage p = _get(id);
        if (p.info.status != Status.Uploading) revert WrongStage();
        if (atoms.length == 0 || atoms.length > MAX_UPLOAD ||
            atoms.length > uint256(p.info.atomCount) - p.info.loadedAtoms) revert InvalidInput();
        // Atom and constraint streams have one canonical order in the digest.
        if (p.info.loadedConstraints != 0) revert WrongStage();
        for (uint256 j; j < atoms.length; ++j) {
            _positive(atoms[j].mass);
            for (uint256 axis; axis < 3; ++axis) {
                _finite(atoms[j].anchor[axis]); _finite(atoms[j].current[axis]);
            }
            uint256 index = p.info.loadedAtoms++;
            p.atoms[index] = atoms[j];
            p.inputDigest = keccak256(abi.encode(p.inputDigest, bytes32("ATOM"), index, atoms[j]));
        }
    }

    function appendConstraints(bytes32 id, Constraint[] calldata constraints) external {
        _onlyWriter();
        Problem storage p = _get(id);
        if (p.info.status != Status.Uploading) revert WrongStage();
        if (p.info.loadedAtoms != p.info.atomCount) revert IncompleteInput();
        if (constraints.length == 0 || constraints.length > MAX_UPLOAD ||
            constraints.length > uint256(p.info.constraintCount) - p.info.loadedConstraints) revert InvalidInput();
        for (uint256 j; j < constraints.length; ++j) {
            Constraint memory c = constraints[j];
            if (c.a >= c.b || c.b >= p.info.atomCount) revert InvalidInput();
            if (p.info.mode == Mode.Position) _positive(c.distance);
            else if (c.distance != bytes16(0)) revert InvalidInput();
            uint256 key = uint256(c.a) * p.info.atomCount + c.b;
            if (p.info.loadedConstraints != 0 && key <= p.lastConstraintKey) revert InvalidInput();
            p.lastConstraintKey = key;
            uint256 index = p.info.loadedConstraints++;
            p.constraints[index] = c;
            p.inputDigest = keccak256(abi.encode(p.inputDigest, bytes32("CONSTRAINT"), index, c));
        }
    }

    function sealProblem(bytes32 id) external {
        _onlyWriter();
        Problem storage p = _get(id);
        if (p.info.status != Status.Uploading) revert WrongStage();
        if (p.info.loadedAtoms != p.info.atomCount || p.info.loadedConstraints != p.info.constraintCount)
            revert IncompleteInput();
        p.info.commitment = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-PROBLEM-v1"),
            p.inputDigest, p.info.atomCount, p.info.constraintCount));
        p.info.status = Status.Correcting;
        emit ProblemSealed(id, p.info.commitment);
    }

    /// @notice Anyone may execute the next bounded records, but cannot supply results.
    function advance(bytes32 id, uint256 workLimit) external returns (uint256 processed, Status status) {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        _assertDependencies();
        Problem storage p = _get(id);
        if (p.info.status != Status.Correcting && p.info.status != Status.Checking) revert WrongStage();
        while (processed < workLimit &&
               (p.info.status == Status.Correcting || p.info.status == Status.Checking)) {
            if (p.info.status == Status.Correcting) _correct(p);
            else {
                bytes16 residual = _residual(p, p.info.cursor);
                if (numericalMath.compare(residual, p.info.maximumResidual) > 0)
                    p.info.maximumResidual = residual;
            }
            ++processed;
            ++p.info.cursor;
            if (p.info.cursor == p.info.constraintCount) _finishPass(id, p);
        }
        status = p.info.status;
        emit Advanced(id, processed, status, p.info.cursor, p.info.iterations);
    }

    function _finishPass(bytes32 id, Problem storage p) private {
        p.info.cursor = 0;
        if (p.info.status == Status.Correcting) {
            p.info.status = Status.Checking;
            p.info.maximumResidual = bytes16(0);
            return;
        }
        ++p.info.iterations;
        if (numericalMath.compare(p.info.maximumResidual, p.info.tolerance) <= 0)
            p.info.status = Status.Converged;
        else if (p.info.iterations == p.info.maxIterations) p.info.status = Status.Failed;
        else p.info.status = Status.Correcting;
        if (p.info.status == Status.Converged || p.info.status == Status.Failed)
            emit Finished(id, p.info.status, p.info.iterations, p.info.maximumResidual);
    }

    function _correct(Problem storage p) private {
        Constraint memory c = p.constraints[p.info.cursor];
        AtomInput storage a = p.atoms[c.a];
        AtomInput storage b = p.atoms[c.b];
        bytes16[3] memory anchor = _difference(a.anchor, b.anchor);
        bytes16[3] memory current = _difference(a.current, b.current);
        bytes16[3] memory correctionA;
        bytes16[3] memory correctionB;
        bytes16 residual;
        if (p.info.mode == Mode.Position) {
            (correctionA, correctionB, residual) = kernel.positionCorrection(
                DistanceConstraintKernel.PositionInput(anchor, current, a.mass, b.mass, c.distance));
        } else {
            (correctionA, correctionB, residual) = kernel.velocityCorrection(
                DistanceConstraintKernel.VelocityInput(anchor, current, a.mass, b.mass));
        }
        // Keep already acceptable constraints unchanged; final checking still
        // assesses all constraints against the same completed correction pass.
        if (numericalMath.compare(residual, p.info.tolerance) <= 0) return;
        for (uint256 axis; axis < 3; ++axis) {
            a.current[axis] = numericalMath.add(a.current[axis], correctionA[axis]);
            b.current[axis] = numericalMath.add(b.current[axis], correctionB[axis]);
        }
    }

    function _residual(Problem storage p, uint256 index) private view returns (bytes16) {
        Constraint memory c = p.constraints[index];
        bytes16[3] memory current = _difference(p.atoms[c.a].current, p.atoms[c.b].current);
        FloatMath m = numericalMath;
        if (p.info.mode == Mode.Position) {
            bytes16 targetSquared = m.mul(c.distance, c.distance);
            _positive(targetSquared);
            return m.div(m.abs(m.sub(_dot(current, current), targetSquared)), targetSquared);
        }
        bytes16[3] memory anchor = _difference(p.atoms[c.a].anchor, p.atoms[c.b].anchor);
        bytes16 squared = _dot(anchor, anchor);
        _positive(squared);
        return m.abs(m.div(_dot(anchor, current), squared));
    }

    function problemInfo(bytes32 id) external view returns (Info memory) { return _get(id).info; }
    function inputDigest(bytes32 id) external view returns (bytes32) { return _get(id).inputDigest; }
    function atomAt(bytes32 id, uint256 index) external view returns (AtomInput memory) {
        Problem storage p = _get(id);
        if (index >= p.info.loadedAtoms) revert OutOfBounds();
        return p.atoms[index];
    }
    function solutionAt(bytes32 id, uint256 index) external view returns (bytes16[3] memory) {
        Problem storage p = _get(id);
        if (p.info.status != Status.Converged) revert SolutionUnavailable();
        if (index >= p.info.atomCount) revert OutOfBounds();
        return p.atoms[index].current;
    }
    function constraintAt(bytes32 id, uint256 index) external view returns (Constraint memory) {
        Problem storage p = _get(id);
        if (index >= p.info.loadedConstraints) revert OutOfBounds();
        return p.constraints[index];
    }
    function residualAt(bytes32 id, uint256 index) external view returns (bytes16) {
        Problem storage p = _get(id);
        if (p.info.status == Status.Uploading || index >= p.info.constraintCount) revert OutOfBounds();
        return _residual(p, index);
    }
    function _difference(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16[3] memory d) {
        for (uint256 axis; axis < 3; ++axis) d[axis] = numericalMath.sub(b[axis], a[axis]);
    }
    function _dot(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16 result) {
        for (uint256 axis; axis < 3; ++axis) result = numericalMath.add(result, numericalMath.mul(a[axis], b[axis]));
    }
    function _finite(bytes16 x) private view { if (!numericalMath.isFinite(x)) revert InvalidInput(); }
    function _positive(bytes16 x) private view {
        _finite(x); if (numericalMath.compare(x, bytes16(0)) <= 0) revert InvalidInput();
    }
    function _get(bytes32 id) private view returns (Problem storage p) {
        p = _problems[id]; if (p.info.status == Status.Missing) revert UnknownProblem();
    }
    function _onlyWriter() private view { if (msg.sender != writer) revert Unauthorized(); _assertDependencies(); }
    function _assertDependencies() private view {
        if (writer.codehash != writerCodeHash || address(numericalMath).codehash != mathCodeHash ||
            address(kernel).codehash != kernelCodeHash) revert DependencyChanged();
    }
}

contracts/core/DataPage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Bounded, append-only 32-byte input words with irreversible sealing.
/// @dev This is an immutable-input page. Mutable simulation pages require a separate design.
contract DataPage {
    error Unauthorized();
    error InvalidConfiguration();
    error PageSealed();
    error InvalidBatch();
    error CapacityExceeded();
    error DigestMismatch();
    error EmptyPage();
    error InvalidRead();

    uint256 public constant MAX_APPEND_WORDS = 128;
    uint256 public constant MAX_CAPACITY_WORDS = 4096;
    address public immutable owner;
    bytes32 public immutable role;
    uint32 public immutable capacityWords;
    bool public isSealed;
    bytes32 public rollingDigest;
    bytes32[] private _words;

    event WordsAppended(uint256 start, uint256 count, bytes32 rollingDigest);
    event PageFrozen(uint256 wordCount, bytes32 digest);

    constructor(address owner_, bytes32 role_, uint32 capacityWords_) {
        if (owner_ == address(0) || role_ == bytes32(0) || capacityWords_ == 0 || capacityWords_ > MAX_CAPACITY_WORDS) {
            revert InvalidConfiguration();
        }
        owner = owner_;
        role = role_;
        capacityWords = capacityWords_;
        rollingDigest = keccak256(abi.encode(bytes32("ORVIA-DATA-PAGE-v1"), role_, capacityWords_));
    }

    function append(bytes32[] calldata values) external {
        if (msg.sender != owner) revert Unauthorized();
        if (isSealed) revert PageSealed();
        if (values.length == 0 || values.length > MAX_APPEND_WORDS) revert InvalidBatch();
        uint256 start = _words.length;
        if (start + values.length > capacityWords) revert CapacityExceeded();
        bytes32 digest = rollingDigest;
        for (uint256 i; i < values.length; ++i) {
            _words.push(values[i]);
            digest = keccak256(abi.encode(digest, values[i]));
        }
        rollingDigest = digest;
        emit WordsAppended(start, values.length, digest);
    }

    function seal(bytes32 expectedDigest) external {
        if (msg.sender != owner) revert Unauthorized();
        if (isSealed) revert PageSealed();
        if (_words.length == 0) revert EmptyPage();
        if (expectedDigest != rollingDigest) revert DigestMismatch();
        isSealed = true;
        emit PageFrozen(_words.length, expectedDigest);
    }

    function wordCount() external view returns (uint256) { return _words.length; }

    function readWord(uint256 index) external view returns (bytes32) {
        if (index >= _words.length) revert InvalidRead();
        return _words[index];
    }

    function readWords(uint256 start, uint256 count) external view returns (bytes32[] memory words) {
        if (count > MAX_APPEND_WORDS || start > _words.length || count > _words.length - start) revert InvalidRead();
        words = new bytes32[](count);
        for (uint256 i; i < count; ++i) words[i] = _words[start + i];
    }
}

contracts/core/DatasetCatalog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {DataPage} from "./DataPage.sol";

/// @notice Immutable, readable datasets assembled from trusted sealed input pages.
/// @dev Numerical validity is checked by the consuming engine. This contract fixes
///      provenance, schema coverage, canonical word encodings, and page identity.
contract DatasetCatalog {
    error Unauthorized();
    error InvalidOwner();
    error InvalidRole();
    error InvalidDataset();
    error AlreadyRegistered();
    error UnknownDataset();
    error InvalidPageList();
    error DuplicatePage(address page);
    error UntrustedPage(address page);
    error InvalidPage(address page);
    error PageChanged(address page);
    error InvalidCoverage();
    error InvalidRead();
    error NoncanonicalWord();

    bytes32 public constant POSITION_ROLE = keccak256("ORVIA.POSITIONS.v1");
    bytes32 public constant BOND_ROLE = keccak256("ORVIA.BONDS.v1");
    bytes32 public constant DATASET_DOMAIN = keccak256("ORVIA.DATASET.v1");
    uint256 public constant MAX_PAGES_PER_STREAM = 16;
    uint32 public constant MAX_ATOMS = 4096;
    uint32 public constant MAX_BONDS = 16384;
    address public immutable owner;

    struct PageRecord {
        address page;
        bytes32 codeHash;
        bytes32 digest;
        uint32 wordCount;
    }

    struct Dataset {
        bytes32 commitment;
        uint32 atomCount;
        uint32 bondCount;
        bool exists;
        PageRecord[] positions;
        PageRecord[] bonds;
    }

    mapping(address => bool) public isCatalogPage;
    mapping(bytes32 => Dataset) private _datasets;

    event PageCreated(address indexed page, bytes32 indexed role, uint32 capacityWords);
    event DatasetRegistered(bytes32 indexed datasetId, bytes32 commitment, uint32 atomCount, uint32 bondCount);

    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidOwner();
        owner = owner_;
    }

    /// @notice Create a page that the catalog owner can populate and seal directly.
    function createPage(bytes32 role, uint32 capacityWords) external returns (address page) {
        if (msg.sender != owner) revert Unauthorized();
        if (role != POSITION_ROLE && role != BOND_ROLE) revert InvalidRole();
        page = address(new DataPage(owner, role, capacityWords));
        isCatalogPage[page] = true;
        emit PageCreated(page, role, capacityWords);
    }

    function registerDataset(
        bytes32 id,
        address[] calldata positionPages,
        address[] calldata bondPages,
        uint32 atomCount,
        uint32 bondCount
    ) external returns (bytes32 commitment) {
        if (msg.sender != owner) revert Unauthorized();
        if (id == bytes32(0) || atomCount < 2 || atomCount > MAX_ATOMS || bondCount == 0 || bondCount > MAX_BONDS) {
            revert InvalidDataset();
        }
        if (_datasets[id].exists) revert AlreadyRegistered();
        _checkPageLists(positionPages, bondPages);

        Dataset storage dataset = _datasets[id];
        (bytes32 positionCommitment, uint256 positionWords) = _freezePages(positionPages, POSITION_ROLE, dataset.positions);
        (bytes32 bondCommitment, uint256 bondWords) = _freezePages(bondPages, BOND_ROLE, dataset.bonds);
        if (positionWords != uint256(atomCount) * 3 || bondWords != uint256(bondCount) * 4) revert InvalidCoverage();

        commitment = keccak256(abi.encode(
            DATASET_DOMAIN, block.chainid, address(this), id, atomCount, bondCount, positionCommitment, bondCommitment
        ));
        dataset.commitment = commitment;
        dataset.atomCount = atomCount;
        dataset.bondCount = bondCount;
        dataset.exists = true;
        emit DatasetRegistered(id, commitment, atomCount, bondCount);
    }

    function datasetInfo(bytes32 id) external view returns (bytes32 commitment, uint32 atomCount, uint32 bondCount) {
        Dataset storage dataset = _get(id);
        return (dataset.commitment, dataset.atomCount, dataset.bondCount);
    }

    /// @notice Check all frozen pages before accepting or advancing a dataset run.
    function assertDataset(bytes32 id) external view returns (bytes32 commitment) {
        Dataset storage dataset = _get(id);
        for (uint256 i; i < dataset.positions.length; ++i) _assertPage(dataset.positions[i]);
        for (uint256 i; i < dataset.bonds.length; ++i) _assertPage(dataset.bonds[i]);
        return dataset.commitment;
    }

    /// @notice Position index is flat x0,y0,z0,x1,y1,z1,...; payload is low 128 bits.
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32 word) {
        Dataset storage dataset = _get(id);
        if (index >= uint256(dataset.atomCount) * 3) revert InvalidRead();
        word = _read(dataset.positions, index);
        if (uint256(word) >> 128 != 0) revert NoncanonicalWord();
    }

    /// @notice Bond index is flat a0,b0,k0,r0_0,a1,b1,k1,r0_1,... across pages.
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32 word) {
        Dataset storage dataset = _get(id);
        if (index >= uint256(dataset.bondCount) * 4) revert InvalidRead();
        word = _read(dataset.bonds, index);
        uint256 payloadBits = index % 4 < 2 ? 32 : 128;
        if (uint256(word) >> payloadBits != 0) revert NoncanonicalWord();
    }

    function pageCount(bytes32 id, bool bondStream) external view returns (uint256) {
        Dataset storage dataset = _get(id);
        return bondStream ? dataset.bonds.length : dataset.positions.length;
    }

    /// @notice Read frozen metadata; bondStream=false selects the position stream.
    function pageInfo(bytes32 id, bool bondStream, uint256 index)
        external view returns (address page, bytes32 codeHash, bytes32 digest, uint32 wordCount)
    {
        Dataset storage dataset = _get(id);
        PageRecord[] storage pages = bondStream ? dataset.bonds : dataset.positions;
        if (index >= pages.length) revert InvalidRead();
        PageRecord storage record = pages[index];
        return (record.page, record.codeHash, record.digest, record.wordCount);
    }

    function _checkPageLists(address[] calldata positions, address[] calldata bonds) private pure {
        if (positions.length == 0 || positions.length > MAX_PAGES_PER_STREAM || bonds.length == 0 || bonds.length > MAX_PAGES_PER_STREAM) {
            revert InvalidPageList();
        }
        for (uint256 i; i < positions.length; ++i) {
            for (uint256 j; j < i; ++j) {
                if (positions[i] == positions[j]) revert DuplicatePage(positions[i]);
            }
        }
        for (uint256 i; i < bonds.length; ++i) {
            for (uint256 j; j < i; ++j) {
                if (bonds[i] == bonds[j]) revert DuplicatePage(bonds[i]);
            }
            for (uint256 j; j < positions.length; ++j) {
                if (bonds[i] == positions[j]) revert DuplicatePage(bonds[i]);
            }
        }
    }

    function _freezePages(address[] calldata pages, bytes32 role, PageRecord[] storage records)
        private returns (bytes32 streamCommitment, uint256 totalWords)
    {
        streamCommitment = keccak256(abi.encode(role, pages.length));
        for (uint256 i; i < pages.length; ++i) {
            address page = pages[i];
            if (!isCatalogPage[page]) revert UntrustedPage(page);
            DataPage inputPage = DataPage(page);
            if (page.code.length == 0 || inputPage.role() != role || !inputPage.isSealed()) revert InvalidPage(page);
            uint256 words = inputPage.wordCount();
            if (words == 0 || words > inputPage.capacityWords()) revert InvalidPage(page);
            PageRecord memory record = PageRecord(page, page.codehash, inputPage.rollingDigest(), uint32(words));
            records.push(record);
            totalWords += words;
            streamCommitment = keccak256(abi.encode(
                streamCommitment, i, record.page, record.codeHash, record.wordCount, record.digest
            ));
        }
    }

    function _assertPage(PageRecord storage record) private view {
        address page = record.page;
        if (page.code.length == 0 || page.codehash != record.codeHash) revert PageChanged(page);
        DataPage inputPage = DataPage(page);
        if (!inputPage.isSealed() || inputPage.rollingDigest() != record.digest || inputPage.wordCount() != record.wordCount) {
            revert PageChanged(page);
        }
    }

    function _read(PageRecord[] storage pages, uint256 index) private view returns (bytes32) {
        for (uint256 i; i < pages.length; ++i) {
            PageRecord storage record = pages[i];
            if (index < record.wordCount) {
                _assertPage(record);
                return DataPage(record.page).readWord(index);
            }
            index -= record.wordCount;
        }
        revert InvalidRead();
    }

    function _get(bytes32 id) private view returns (Dataset storage dataset) {
        dataset = _datasets[id];
        if (!dataset.exists) revert UnknownDataset();
    }
}

contracts/core/DynamicsCoordinator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {FloatMath} from "../math/FloatMath.sol";

interface IDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readPairWord(bytes32 id, uint256 index) external view returns (bytes32);
}
interface IDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface IDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface IDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface IDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface IDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface IDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}
interface IDynamicsIntegrator {
    function drift(bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextPosition, bytes16[3] memory halfVelocity);
    function kick(bytes16[3] calldata halfVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity);
}

/// @notice Resumable, double-buffered velocity-Verlet component for declared finite systems.
/// @dev Computes bonded and listed direct-pair forces on-chain. No thermostat,
///      constraints, periodic boundary, long-range solver or free-energy estimator.
contract DynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
    }
    Modules public modules;
    bytes32[10] public moduleCodeHashes;
    WorkingStatePage public statePage;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingPairs, InitialBonds, InitialAngles, InitialTorsions, InitialPairs,
        Drift, NextBonds, NextAngles, NextTorsions, NextPairs, Kick, Completed
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; bytes16 prefactor; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event StepCommitted(uint256 indexed experimentId, uint256 completedSteps, uint256 activeBuffer);

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = modules_;
        address[10] memory addresses = _moduleAddresses(modules_);
        bytes32[10] memory hashes;
        for (uint256 i; i < 10; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 10; ++i) {
            if (IDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (IDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            IDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function bindWorkingPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this)) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, bytes16 dt, uint32 steps)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(dt);
        if (steps == 0 || steps > MAX_STEPS) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = IDynamicsData(modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = IDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 || r.pairCount > 4096) revert InvalidInput();
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = dt;
        r.targetSteps = steps;
        r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-DYNAMICS-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-DYNAMICS-RUN-v1"), block.chainid, address(this),
            experimentId, manifest, datasetId, datasetCommitment, configurationHash, dt, steps, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (IDynamicsData(modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            _process(r);
            ++processed;
            ++r.cursor;
            if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 completedSteps, uint256 targetSteps, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }

    function stateAt(uint256 experimentId, uint256 atom) external view returns (
        bytes16[3] memory position, bytes16[3] memory velocity, bytes16[3] memory force
    ) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(uint256 experimentId) external view returns (
        bytes16 dt, uint32 bondCount, uint32 angleCount, uint32 torsionCount, uint32 pairCount, bytes32 datasetCommitment
    ) {
        Run storage r = _get(experimentId);
        return (r.dt, r.bondCount, r.angleCount, r.torsionCount, r.pairCount, r.datasetCommitment);
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingPairs) _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status <= Status.NextPairs) _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (r.status == Status.Kick) {
            r.activeBuffer = 1 - r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace);
                r.status = Status.Completed;
                return;
            }
            r.status = Status.Drift;
        } else r.status = Status(uint8(r.status) + 1);
        r.cursor = 0;
        // Empty optional interaction streams consume no artificial work units.
        while (_stageCount(r) == 0) r.status = Status(uint8(r.status) + 1);
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.Loading || r.status == Status.Drift || r.status == Status.Kick) return r.atomCount;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        return r.pairCount;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingPairs) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status) - 6;
        if (status >= Status.NextBonds && status <= Status.NextPairs) return uint8(status) - 11;
        revert InvalidInput();
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        IDynamicsData data = IDynamicsData(modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            words[d + 3] = _encode(_decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)));
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
        (bytes16[3] memory position, bytes16[3] memory halfVelocity) = IDynamicsIntegrator(modules.integrator).drift(
            _readVector(r, r.activeBuffer, r.cursor, 0), _readVector(r, r.activeBuffer, r.cursor, 3),
            _readVector(r, r.activeBuffer, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = IDynamicsIntegrator(modules.integrator).kick(
            _readVector(r, next, r.cursor, 3), _readVector(r, next, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) { _requireFinite(velocity[d]); words[d] = _encode(velocity[d]); }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 3), words);
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private view {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _pair(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        (bytes16 energy, bytes16[3] memory force) = IDynamicsPairKernel(modules.bond).evaluate(
            _readVector(r, buffer, b.a, 0), _readVector(r, buffer, b.b, 0), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            IDynamicsAngleKernel(modules.angle).evaluate(_readVector(r, buffer, a.a, 0),
                _readVector(r, buffer, a.b, 0), _readVector(r, buffer, a.c, 0), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[0] = _readVector(r, buffer, t.a, 0);
        positions[1] = _readVector(r, buffer, t.b, 0);
        positions[2] = _readVector(r, buffer, t.c, 0);
        positions[3] = _readVector(r, buffer, t.d, 0);
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            IDynamicsTorsionKernel(modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, index);
        bytes16[3] memory a = _readVector(r, buffer, p.a, 0);
        bytes16[3] memory b = _readVector(r, buffer, p.b, 0);
        (bytes16 ljEnergy, bytes16[3] memory ljForce) = IDynamicsPairKernel(modules.lj).evaluate(a, b, p.sigma, p.epsilon);
        (bytes16 cEnergy, bytes16[3] memory cForce) = IDynamicsPairKernel(modules.coulomb).evaluate(a, b, p.chargeProduct, p.prefactor);
        FloatMath m = FloatMath(modules.math);
        _addEnergy(r, buffer, m.add(ljEnergy, cEnergy));
        for (uint256 d; d < 3; ++d) ljForce[d] = m.add(ljForce[d], cForce[d]);
        _addForce(r, buffer, p.a, ljForce, false);
        _addForce(r, buffer, p.b, ljForce, true);
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        IDynamicsData data = IDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        IDynamicsData data = IDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(modules.math).compare(a.theta0, IDynamicsElementary(modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        IDynamicsData data = IDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = IDynamicsElementary(modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        IDynamicsData data = IDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readPairWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readPairWord(r.datasetId, offset + 1), r.atomCount);
        if (p.a == p.b) revert InvalidInput();
        p.sigma = _decode(data.readPairWord(r.datasetId, offset + 2));
        p.epsilon = _decode(data.readPairWord(r.datasetId, offset + 3));
        p.chargeProduct = _decode(data.readPairWord(r.datasetId, offset + 4));
        p.prefactor = _decode(data.readPairWord(r.datasetId, offset + 5));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon); _requireNonnegative(p.prefactor);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(IDynamicsData(modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[10] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 10; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash) revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 10; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[10] memory) {
        return [m.registry, m.dataset, m.math, m.integrator, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/DynamicsDataset.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {DataPage} from "./DataPage.sol";
import {DatasetCatalog} from "./DatasetCatalog.sol";

/// @notice Frozen paged mass, velocity and interaction inputs for dynamics fixtures.
/// @dev The base catalog owns initial positions/bonds. Numerical validity is the
///      consuming coordinator's responsibility; registration fixes schema/identity.
contract DynamicsDataset {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidRole();
    error InvalidDataset();
    error AlreadyRegistered();
    error UnknownDataset();
    error InvalidPageList();
    error DuplicatePage(address page);
    error UntrustedPage(address page);
    error InvalidPage(address page);
    error PageChanged(address page);
    error BaseCatalogChanged();
    error BaseDatasetChanged();
    error InvalidCoverage();
    error InvalidRead();
    error NoncanonicalWord();

    bytes32 public constant PARTICLE_ROLE = keccak256("ORVIA.PARTICLES.v1");
    bytes32 public constant ANGLE_ROLE = keccak256("ORVIA.ANGLES.v1");
    bytes32 public constant TORSION_ROLE = keccak256("ORVIA.TORSIONS.v1");
    bytes32 public constant PAIR_ROLE = keccak256("ORVIA.PAIRS.v1");
    bytes32 public constant DATASET_DOMAIN = keccak256("ORVIA.DYNAMICS.DATASET.v1");
    uint256 public constant MAX_PAGES_PER_STREAM = 16;
    uint32 public constant MAX_INTERACTIONS = 4096;
    address public immutable owner;
    DatasetCatalog public immutable baseCatalog;
    bytes32 public immutable baseCatalogCodeHash;

    struct PageRecord { address page; bytes32 codeHash; bytes32 digest; uint32 wordCount; }
    struct Registration {
        bytes32 baseDatasetId;
        address[] particlePages;
        address[] anglePages;
        address[] torsionPages;
        address[] pairPages;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
    }
    struct Dataset {
        bytes32 commitment;
        bytes32 baseDatasetId;
        bytes32 baseCommitment;
        uint32 bondCount;
        // particles/atoms, angles, torsions, pairs in that order
        uint32[4] counts;
        bytes32[4] streamCommitments;
        bool exists;
        PageRecord[][4] streams;
        mapping(address => bool) usedPages;
    }
    mapping(address => bool) public isCatalogPage;
    mapping(bytes32 => Dataset) private _datasets;

    event PageCreated(address indexed page, bytes32 indexed role, uint32 capacityWords);
    event DatasetRegistered(bytes32 indexed datasetId, bytes32 indexed baseDatasetId, bytes32 commitment);

    constructor(address owner_, address baseCatalog_) {
        if (owner_ == address(0) || baseCatalog_.code.length == 0) revert InvalidConfiguration();
        owner = owner_;
        baseCatalog = DatasetCatalog(baseCatalog_);
        baseCatalogCodeHash = baseCatalog_.codehash;
    }

    function createPage(bytes32 role, uint32 capacityWords) external returns (address page) {
        if (msg.sender != owner) revert Unauthorized();
        if (role != PARTICLE_ROLE && role != ANGLE_ROLE && role != TORSION_ROLE && role != PAIR_ROLE) revert InvalidRole();
        page = address(new DataPage(owner, role, capacityWords));
        isCatalogPage[page] = true;
        emit PageCreated(page, role, capacityWords);
    }

    function registerDataset(bytes32 id, Registration calldata input) external returns (bytes32 commitment) {
        if (msg.sender != owner) revert Unauthorized();
        _begin(id, input.baseDatasetId, input.angleCount, input.torsionCount, input.pairCount);
        _freezeStream(id, 0, input.particlePages);
        _freezeStream(id, 1, input.anglePages);
        _freezeStream(id, 2, input.torsionPages);
        _freezeStream(id, 3, input.pairPages);
        commitment = _finish(id);
    }

    function datasetInfo(bytes32 id) external view returns (
        bytes32 commitment, bytes32 baseDatasetId, uint32 atomCount, uint32 bondCount,
        uint32 angleCount, uint32 torsionCount, uint32 pairCount
    ) {
        Dataset storage d = _get(id);
        return (d.commitment, d.baseDatasetId, d.counts[0], d.bondCount, d.counts[1], d.counts[2], d.counts[3]);
    }

    function assertDataset(bytes32 id) external view returns (bytes32 commitment) {
        Dataset storage d = _get(id);
        _assertBase(d);
        for (uint256 s; s < 4; ++s) {
            for (uint256 i; i < d.streams[s].length; ++i) _assertPage(d.streams[s][i]);
        }
        return d.commitment;
    }

    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id);
        _checkBaseCode();
        return baseCatalog.readPositionWord(d.baseDatasetId, index);
    }
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id);
        _checkBaseCode();
        return baseCatalog.readBondWord(d.baseDatasetId, index);
    }
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 0, index); }
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 1, index); }
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 2, index); }
    function readPairWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 3, index); }

    function pageCount(bytes32 id, uint8 stream) external view returns (uint256) {
        if (stream > 3) revert InvalidRead();
        return _get(id).streams[stream].length;
    }
    function pageInfo(bytes32 id, uint8 stream, uint256 index)
        external view returns (address page, bytes32 codeHash, bytes32 digest, uint32 wordCount)
    {
        if (stream > 3) revert InvalidRead();
        PageRecord[] storage pages = _get(id).streams[stream];
        if (index >= pages.length) revert InvalidRead();
        PageRecord storage p = pages[index];
        return (p.page, p.codeHash, p.digest, p.wordCount);
    }

    function _begin(bytes32 id, bytes32 baseId, uint32 angles, uint32 torsions, uint32 pairs) private {
        if (id == bytes32(0) || angles > MAX_INTERACTIONS || torsions > MAX_INTERACTIONS || pairs > MAX_INTERACTIONS) {
            revert InvalidDataset();
        }
        if (_datasets[id].exists) revert AlreadyRegistered();
        _checkBaseCode();
        bytes32 frozenBase = baseCatalog.assertDataset(baseId);
        (bytes32 reportedBase, uint32 atoms, uint32 bonds) = baseCatalog.datasetInfo(baseId);
        if (atoms < 2 || atoms > 4096 || bonds == 0 || reportedBase != frozenBase) revert InvalidDataset();
        Dataset storage d = _datasets[id];
        d.baseDatasetId = baseId;
        d.baseCommitment = frozenBase;
        d.bondCount = bonds;
        d.counts = [atoms, angles, torsions, pairs];
    }

    function _freezeStream(bytes32 id, uint8 stream, address[] calldata pages) private {
        Dataset storage d = _datasets[id];
        uint256 count = d.counts[stream];
        if (pages.length > MAX_PAGES_PER_STREAM || (count == 0 ? pages.length != 0 : pages.length == 0)) revert InvalidPageList();
        bytes32 role = _role(stream);
        bytes32 digest = keccak256(abi.encode(role, pages.length));
        uint256 words;
        for (uint256 i; i < pages.length; ++i) {
            address page = pages[i];
            if (d.usedPages[page]) revert DuplicatePage(page);
            if (!isCatalogPage[page]) revert UntrustedPage(page);
            DataPage inputPage = DataPage(page);
            if (page.code.length == 0 || inputPage.role() != role || !inputPage.isSealed()) revert InvalidPage(page);
            uint256 size = inputPage.wordCount();
            if (size == 0 || size > inputPage.capacityWords()) revert InvalidPage(page);
            d.usedPages[page] = true;
            PageRecord memory p = PageRecord(page, page.codehash, inputPage.rollingDigest(), uint32(size));
            d.streams[stream].push(p);
            words += size;
            digest = keccak256(abi.encode(digest, i, p.page, p.codeHash, p.wordCount, p.digest));
        }
        if (words != count * _width(stream)) revert InvalidCoverage();
        d.streamCommitments[stream] = digest;
    }

    function _finish(bytes32 id) private returns (bytes32 commitment) {
        Dataset storage d = _datasets[id];
        bytes32 baseHeader = keccak256(abi.encode(
            address(baseCatalog), baseCatalogCodeHash, d.baseDatasetId, d.baseCommitment, d.counts[0], d.bondCount
        ));
        commitment = keccak256(abi.encode(DATASET_DOMAIN, block.chainid, address(this), id,
            baseHeader, d.counts, d.streamCommitments));
        d.commitment = commitment;
        d.exists = true;
        emit DatasetRegistered(id, d.baseDatasetId, commitment);
    }

    function _read(Dataset storage d, uint8 stream, uint256 index) private view returns (bytes32 word) {
        uint256 width = _width(stream);
        if (index >= uint256(d.counts[stream]) * width) revert InvalidRead();
        uint256 globalOffset = index % width;
        PageRecord[] storage pages = d.streams[stream];
        for (uint256 i; i < pages.length; ++i) {
            PageRecord storage p = pages[i];
            if (index < p.wordCount) {
                _assertPage(p);
                word = DataPage(p.page).readWord(index);
                uint256 indexFields = stream == 0 ? 0 : stream == 1 ? 3 : stream == 2 ? 5 : 2;
                if (uint256(word) >> (globalOffset < indexFields ? 32 : 128) != 0) revert NoncanonicalWord();
                return word;
            }
            index -= p.wordCount;
        }
        revert InvalidRead();
    }
    function _assertPage(PageRecord storage p) private view {
        if (p.page.code.length == 0 || p.page.codehash != p.codeHash) revert PageChanged(p.page);
        DataPage page = DataPage(p.page);
        if (!page.isSealed() || page.rollingDigest() != p.digest || page.wordCount() != p.wordCount) revert PageChanged(p.page);
    }
    function _checkBaseCode() private view {
        if (address(baseCatalog).codehash != baseCatalogCodeHash) revert BaseCatalogChanged();
    }
    function _assertBase(Dataset storage d) private view {
        _checkBaseCode();
        if (baseCatalog.assertDataset(d.baseDatasetId) != d.baseCommitment) revert BaseDatasetChanged();
    }
    function _role(uint8 stream) private pure returns (bytes32) {
        if (stream == 0) return PARTICLE_ROLE;
        if (stream == 1) return ANGLE_ROLE;
        if (stream == 2) return TORSION_ROLE;
        return PAIR_ROLE;
    }
    function _width(uint8 stream) private pure returns (uint256) {
        if (stream == 0) return 4;
        if (stream == 1) return 5;
        if (stream == 2) return 7;
        return 6;
    }
    function _get(bytes32 id) private view returns (Dataset storage d) {
        d = _datasets[id];
        if (!d.exists) revert UnknownDataset();
    }
}

contracts/core/EwaldDynamicsCoordinator..content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {FloatMath} from "../math/FloatMath.sol";

import {
    IPeriodicDynamicsData,
    IPeriodicDynamicsMathIdentity,
    IPeriodicDynamicsAngularIdentity,
    IPeriodicDynamicsElementary,
    IPeriodicDynamicsPairKernel,
    IPeriodicDynamicsAngleKernel,
    IPeriodicDynamicsTorsionKernel,
    IPeriodicDynamicsIntegrator,
    IPeriodicGeometry,
    IPeriodicNonbonded
} from "./PeriodicDynamicsCoordinator.sol";
import {EwaldForceEvaluator} from "./EwaldForceEvaluator.sol";
import {EwaldReciprocalKernel} from "../kernels/EwaldReciprocalKernel.sol";

/// @notice Bounded double-buffered NVE integration with explicit on-chain Ewald electrostatics.
/// @dev Every force pass creates and seals an immutable coordinate snapshot, evaluates
///      real/reciprocal/self/background/exception electrostatics, then merges results.
///      Regular and exception short-range kernels receive zero charge product.
///      This correctness baseline is expensive and does not implement PME.
contract EwaldDynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();
    error StateNotInitialized();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
    }
    Modules public modules;
    bytes32[12] public moduleCodeHashes;
    WorkingStatePage public statePage;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;
    EwaldForceEvaluator public ewaldEvaluator;
    WorkingStatePage public snapshotPage;
    WorkingStatePage public ewaldOutputPage;
    bytes32 public ewaldCodeHash;
    bytes32 public snapshotPageCodeHash;
    bytes32 public ewaldOutputPageCodeHash;

    enum Status {
        Missing,
        Loading,
        ValidatingBonds,
        ValidatingAngles,
        ValidatingTorsions,
        ValidatingExceptions,
        InitialBonds,
        InitialAngles,
        InitialTorsions,
        InitialPairs,
        InitialSnapshot,
        InitialRegister,
        InitialEwald,
        InitialMerge,
        Drift,
        NextBonds,
        NextAngles,
        NextTorsions,
        NextPairs,
        NextSnapshot,
        NextRegister,
        NextEwald,
        NextMerge,
        Kick,
        Completed
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        bytes16 alpha;
        uint32 maxMode;
        uint256 ewaldRunId;
        bytes32 snapshotNamespace;
        bool initialized;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond {
        uint32 a;
        uint32 b;
        bytes16 k;
        bytes16 r0;
    }
    struct Angle {
        uint32 a;
        uint32 b;
        uint32 c;
        bytes16 k;
        bytes16 theta0;
    }
    struct Torsion {
        uint32 a;
        uint32 b;
        uint32 c;
        uint32 d;
        uint32 periodicity;
        bytes16 k;
        bytes16 phase;
    }
    struct Pair {
        uint32 a;
        uint32 b;
        uint32 kind;
        bytes16 sigma;
        bytes16 epsilon;
        bytes16 chargeProduct;
    }
    struct ParticleParameters {
        bytes16 sigma;
        bytes16 epsilon;
        bytes16 charge;
    }
    struct FourEvaluation {
        bytes16 energy;
        bytes16[3][4] force;
    }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(
        uint256 indexed experimentId,
        bytes32 indexed datasetId,
        bytes32 commitment
    );
    event ExperimentAdvanced(
        uint256 indexed experimentId,
        uint256 processed,
        Status status,
        uint256 cursor
    );
    event EwaldBound(
        address indexed evaluator,
        address snapshotPage,
        address outputPage,
        bytes32 configurationHash
    );
    event StepCommitted(
        uint256 indexed experimentId,
        uint256 completedSteps,
        uint256 activeBuffer
    );

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = modules_;
        address[12] memory addresses = _moduleAddresses(modules_);
        bytes32[12] memory hashes;
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 12; ++i) {
            if (
                IPeriodicDynamicsMathIdentity(addresses[i]).numericalMath() !=
                modules_.math
            ) revert InvalidConfiguration();
        }
        if (
            IPeriodicDynamicsAngularIdentity(modules_.angle).elementaryMath() !=
                modules_.elementary ||
            IPeriodicDynamicsAngularIdentity(modules_.torsion)
                .elementaryMath() !=
                modules_.elementary
        ) revert InvalidConfiguration();
        if (
            IPeriodicNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
            IPeriodicNonbonded(modules_.nonbonded).coulombKernel() !=
                modules_.coulomb
        ) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function bindWorkingPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (
            page.code.length == 0 ||
            WorkingStatePage(page).writer() != address(this)
        ) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        configurationHash = keccak256(
            abi.encode(coreConfigurationHash, page, page.codehash)
        );
        emit WorkingPageBound(page, configurationHash);
    }

    /// @dev Deploy the coordinator first, then deploy an evaluator owned by it.
    ///      This binding creates both dedicated pages before protocol registration.
    function bindEwald(address evaluator) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) == address(0)) revert NotConfigured();
        if (address(ewaldEvaluator) != address(0)) revert AlreadyConfigured();
        if (evaluator.code.length == 0) revert InvalidConfiguration();
        EwaldForceEvaluator candidate = EwaldForceEvaluator(evaluator);
        if (candidate.owner() != address(this)) revert InvalidConfiguration();
        EwaldForceEvaluator.Modules memory em = candidate.moduleConfiguration();
        if (
            em.registry != modules.registry ||
            em.dataset != modules.dataset ||
            em.math != modules.math ||
            em.elementary != modules.elementary ||
            em.geometry != modules.geometry
        ) revert InvalidConfiguration();
        ewaldEvaluator = candidate;
        ewaldCodeHash = evaluator.codehash;
        ewaldOutputPage = new WorkingStatePage(evaluator);
        candidate.bindOutputPage(address(ewaldOutputPage));
        snapshotPage = WorkingStatePage(
            candidate.createSnapshotPage(address(this))
        );
        ewaldOutputPageCodeHash = address(ewaldOutputPage).codehash;
        snapshotPageCodeHash = address(snapshotPage).codehash;
        configurationHash = keccak256(
            abi.encode(
                coreConfigurationHash,
                address(statePage),
                statePageCodeHash,
                evaluator,
                ewaldCodeHash,
                candidate.configurationHash(),
                address(snapshotPage),
                snapshotPageCodeHash,
                address(ewaldOutputPage),
                ewaldOutputPageCodeHash
            )
        );
        emit EwaldBound(
            evaluator,
            address(snapshotPage),
            address(ewaldOutputPage),
            configurationHash
        );
    }

    function registerExperiment(
        bytes32 protocolId,
        bytes32 datasetId,
        bytes16 dt,
        uint32 steps,
        bytes16 alpha,
        uint32 maxMode
    ) external returns (uint256 experimentId) {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(dt);
        _requirePositive(alpha);
        ewaldEvaluator.modeCount(maxMode);
        if (steps == 0 || steps > MAX_STEPS) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = IPeriodicDynamicsData(modules.dataset)
            .assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (
            ,
            ,
            r.atomCount,
            r.bondCount,
            r.angleCount,
            r.torsionCount,
            r.pairCount
        ) = IPeriodicDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (
            r.atomCount < 2 ||
            r.atomCount > MAX_ATOMS ||
            r.bondCount == 0 ||
            r.bondCount > 16384 ||
            r.angleCount > 4096 ||
            r.torsionCount > 4096 ||
            r.pairCount != (uint256(r.atomCount) * (r.atomCount - 1)) / 2
        ) revert InvalidInput();
        (
            r.box,
            r.switchDistance,
            r.cutoff,
            r.prefactor,
            r.exceptionCount
        ) = IPeriodicDynamicsData(modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount)
            revert InvalidInput();
        _requirePositive(r.switchDistance);
        _requirePositive(r.cutoff);
        _requireNonnegative(r.prefactor);
        if (FloatMath(modules.math).compare(r.switchDistance, r.cutoff) >= 0)
            revert InvalidInput();
        IPeriodicGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = dt;
        r.alpha = alpha;
        r.maxMode = maxMode;
        _validateEwaldDomain(r);
        r.targetSteps = steps;
        r.status = Status.Loading;
        r.stateNamespace = keccak256(
            abi.encode(
                bytes32("ORVIA-EWALD-MD-STATE-v1"),
                block.chainid,
                address(this),
                experimentId
            )
        );
        r.commitment = _runCommitment(r, experimentId, manifest);
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(
        uint256 experimentId,
        uint256 workLimit
    ) external returns (uint256 processed, bool completed) {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (
            IPeriodicDynamicsData(modules.dataset).assertDataset(r.datasetId) !=
            r.datasetCommitment
        ) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            if (
                r.status == Status.InitialEwald || r.status == Status.NextEwald
            ) {
                _advanceEwald(r);
            } else {
                _process(r);
                ++r.cursor;
                if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
            }
            ++processed;
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(
        uint256 experimentId
    )
        external
        view
        returns (
            bytes32 protocolId,
            bytes32 datasetId,
            bytes32 commitment,
            bytes32 stateNamespace,
            uint256 cursor,
            uint256 completedSteps,
            uint256 targetSteps,
            uint256 atomCount,
            uint256 activeBuffer,
            Status status,
            bytes16 potentialEnergy
        )
    {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = r.initialized
            ? _decode(
                statePage.readWord(
                    r.stateNamespace,
                    _energyIndex(r, r.activeBuffer)
                )
            )
            : bytes16(0);
    }

    function stateAt(
        uint256 experimentId,
        uint256 atom
    )
        external
        view
        returns (
            bytes16[3] memory position,
            bytes16[3] memory velocity,
            bytes16[3] memory force
        )
    {
        Run storage r = _get(experimentId);
        if (!r.initialized) revert StateNotInitialized();
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(
        uint256 experimentId
    )
        external
        view
        returns (
            bytes16 dt,
            uint32 bondCount,
            uint32 angleCount,
            uint32 torsionCount,
            uint32 pairCount,
            bytes32 datasetCommitment
        )
    {
        Run storage r = _get(experimentId);
        return (
            r.dt,
            r.bondCount,
            r.angleCount,
            r.torsionCount,
            r.pairCount,
            r.datasetCommitment
        );
    }

    function periodicParameters(
        uint256 experimentId
    )
        external
        view
        returns (
            bytes16[3] memory box,
            bytes16 switchDistance,
            bytes16 cutoff,
            bytes16 prefactor,
            uint32 exceptionCount
        )
    {
        Run storage r = _get(experimentId);
        return (
            r.box,
            r.switchDistance,
            r.cutoff,
            r.prefactor,
            r.exceptionCount
        );
    }

    function ewaldParameters(
        uint256 experimentId
    )
        external
        view
        returns (
            bytes16 alpha,
            uint32 maxMode,
            uint256 evaluatorRunId,
            bytes32 snapshotNamespace,
            bool initialized
        )
    {
        Run storage r = _get(experimentId);
        return (
            r.alpha,
            r.maxMode,
            r.ewaldRunId,
            r.snapshotNamespace,
            r.initialized
        );
    }

    function _validateEwaldDomain(Run storage r) private view {
        FloatMath m = FloatMath(modules.math);
        if (m.compare(m.mul(r.alpha, r.cutoff), m.fromUInt(16)) > 0)
            revert InvalidInput();
        EwaldForceEvaluator.Modules memory em = ewaldEvaluator
            .moduleConfiguration();
        int32 extent = int32(r.maxMode);
        EwaldReciprocalKernel(em.reciprocal).waveVector(
            [extent, extent, extent],
            r.box,
            r.alpha,
            r.prefactor
        );
    }

    function _runCommitment(
        Run storage r,
        uint256 experimentId,
        bytes32 manifest
    ) private view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    bytes32("ORVIA-EWALD-MD-RUN-v1"),
                    block.chainid,
                    address(this),
                    experimentId,
                    manifest,
                    r.datasetId,
                    r.datasetCommitment,
                    configurationHash,
                    r.dt,
                    r.targetSteps,
                    r.alpha,
                    r.maxMode,
                    r.stateNamespace
                )
            );
    }

    function _copySnapshot(Run storage r) private {
        if (r.cursor == 0) {
            r.snapshotNamespace = keccak256(
                abi.encode(
                    bytes32("ORVIA-EWALD-MD-SNAP-v1"),
                    block.chainid,
                    address(this),
                    r.stateNamespace,
                    r.completedSteps,
                    r.status == Status.InitialSnapshot
                )
            );
            snapshotPage.createNamespace(r.snapshotNamespace, r.atomCount * 3);
        }
        uint256 buffer = r.status == Status.InitialSnapshot
            ? r.activeBuffer
            : 1 - r.activeBuffer;
        bytes32[] memory words = statePage.readWords(
            r.stateNamespace,
            _vectorIndex(r, buffer, r.cursor, 0),
            3
        );
        snapshotPage.writeWords(r.snapshotNamespace, r.cursor * 3, words);
    }

    function _registerEwald(Run storage r) private {
        EwaldForceEvaluator.Registration memory input = EwaldForceEvaluator
            .Registration({
                datasetId: r.datasetId,
                sourcePage: address(snapshotPage),
                sourceNamespace: r.snapshotNamespace,
                positionOffset: 0,
                positionStride: 3,
                alpha: r.alpha,
                maxMode: r.maxMode
            });
        r.ewaldRunId = ewaldEvaluator.registerRun(r.protocolId, input);
    }

    function _advanceEwald(Run storage r) private {
        (EwaldForceEvaluator.Status status, , , , , , ) = ewaldEvaluator
            .runInfo(r.ewaldRunId);
        bool complete = status == EwaldForceEvaluator.Status.Completed;
        if (!complete) (, complete) = ewaldEvaluator.advance(r.ewaldRunId, 1);
        if (complete) {
            r.status = Status(uint8(r.status) + 1);
            r.cursor = 0;
        }
    }

    function _mergeEwald(Run storage r) private {
        uint256 buffer = r.status == Status.InitialMerge
            ? r.activeBuffer
            : 1 - r.activeBuffer;
        if (r.cursor == 0) {
            bytes16[6] memory values = ewaldEvaluator.energies(r.ewaldRunId);
            _addEnergy(r, buffer, values[0]);
        }
        _addForce(
            r,
            buffer,
            r.cursor,
            ewaldEvaluator.forceAt(r.ewaldRunId, r.cursor),
            false
        );
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions)
            _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs)
            _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status >= Status.NextBonds && r.status <= Status.NextPairs)
            _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else if (
            r.status == Status.InitialSnapshot ||
            r.status == Status.NextSnapshot
        ) _copySnapshot(r);
        else if (
            r.status == Status.InitialRegister ||
            r.status == Status.NextRegister
        ) _registerEwald(r);
        else if (
            r.status == Status.InitialMerge || r.status == Status.NextMerge
        ) _mergeEwald(r);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (
            r.status == Status.InitialSnapshot ||
            r.status == Status.NextSnapshot
        ) snapshotPage.sealNamespace(r.snapshotNamespace);
        if (r.status == Status.InitialMerge) r.initialized = true;
        if (r.status == Status.Kick) {
            r.activeBuffer = 1 - r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace);
                r.status = Status.Completed;
                return;
            }
            r.status = Status.Drift;
        } else r.status = Status(uint8(r.status) + 1);
        r.cursor = 0;
        // Empty optional interaction streams consume no artificial work units.
        while (_stageCount(r) == 0) r.status = Status(uint8(r.status) + 1);
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (
            r.status == Status.Loading ||
            r.status == Status.Drift ||
            r.status == Status.Kick ||
            r.status == Status.InitialSnapshot ||
            r.status == Status.NextSnapshot ||
            r.status == Status.InitialMerge ||
            r.status == Status.NextMerge
        ) return r.atomCount;
        if (
            r.status == Status.InitialRegister ||
            r.status == Status.NextRegister ||
            r.status == Status.InitialEwald ||
            r.status == Status.NextEwald
        ) return 1;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        return r.pairCount;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (
            status >= Status.ValidatingBonds &&
            status <= Status.ValidatingExceptions
        ) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs)
            return uint8(status) - 6;
        if (status >= Status.NextBonds && status <= Status.NextPairs)
            return uint8(status) - uint8(Status.NextBonds);
        revert InvalidInput();
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        _parameters(r, atom);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(
                _decode(data.readPositionWord(r.datasetId, atom * 3 + d))
            );
            words[d + 3] = _encode(
                _decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1))
            );
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0)
            statePage.writeWord(
                r.stateNamespace,
                _energyIndex(r, next),
                bytes32(0)
            );
        (
            bytes16[3] memory position,
            bytes16[3] memory halfVelocity
        ) = IPeriodicDynamicsIntegrator(modules.integrator).drift(
                _readVector(r, r.activeBuffer, r.cursor, 0),
                _readVector(r, r.activeBuffer, r.cursor, 3),
                _readVector(r, r.activeBuffer, r.cursor, 6),
                _mass(r, r.cursor),
                r.dt
            );
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(
            r.stateNamespace,
            _vectorIndex(r, next, r.cursor, 0),
            words
        );
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = IPeriodicDynamicsIntegrator(
            modules.integrator
        ).kick(
                _readVector(r, next, r.cursor, 3),
                _readVector(r, next, r.cursor, 6),
                _mass(r, r.cursor),
                r.dt
            );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(velocity[d]);
            words[d] = _encode(velocity[d]);
        }
        statePage.writeWords(
            r.stateNamespace,
            _vectorIndex(r, next, r.cursor, 3),
            words
        );
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(
        Run storage r,
        uint256 buffer,
        uint256 kind,
        uint256 index
    ) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(
        Run storage r,
        uint256 buffer,
        uint256 index
    ) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = IPeriodicDynamicsPairKernel(
            modules.bond
        ).evaluate(zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(
        Run storage r,
        uint256 buffer,
        uint256 index
    ) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (
            bytes16 energy,
            bytes16[3] memory fa,
            bytes16[3] memory fb,
            bytes16[3] memory fc
        ) = IPeriodicDynamicsAngleKernel(modules.angle).evaluate(
                _bondedDisplacement(r, buffer, a.b, a.a),
                zero,
                _bondedDisplacement(r, buffer, a.b, a.c),
                a.k,
                a.theta0
            );
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(
        Run storage r,
        uint256 buffer,
        uint256 index
    ) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(
        Run storage r,
        uint256 buffer,
        Torsion memory t
    ) private view returns (FourEvaluation memory result) {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (
            result.energy,
            result.force[0],
            result.force[1],
            result.force[2],
            result.force[3]
        ) = IPeriodicDynamicsTorsionKernel(modules.torsion).evaluate(
            positions[0],
            positions[1],
            positions[2],
            positions[3],
            t.periodicity,
            t.k,
            t.phase
        );
    }
    function _calculatePair(
        Run storage r,
        uint256 buffer,
        uint256 index
    ) private {
        Pair memory p = _pair(r, index);
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = IPeriodicNonbonded(
            modules.nonbonded
        ).evaluate(
                displacement,
                p.sigma,
                p.epsilon,
                bytes16(0),
                r.prefactor,
                r.switchDistance,
                r.cutoff,
                p.kind == 2
            );
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(
        Run storage r,
        uint256 buffer,
        uint256 a,
        uint256 b
    ) private view returns (bytes16[3] memory) {
        return
            IPeriodicGeometry(modules.geometry).displacement(
                _readVector(r, buffer, a, 0),
                _readVector(r, buffer, b, 0),
                r.box
            );
    }

    function _bondedDisplacement(
        Run storage r,
        uint256 buffer,
        uint256 a,
        uint256 b
    ) private view returns (bytes16[3] memory displacement) {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(
        Run storage r,
        bytes16[3] memory displacement
    ) private view {
        FloatMath m = FloatMath(modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (
                m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) ==
                0
            ) revert InvalidInput();
        }
    }

    function _bond(
        Run storage r,
        uint256 index
    ) private view returns (Bond memory b) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k);
        _requireNonnegative(b.r0);
    }
    function _angle(
        Run storage r,
        uint256 index
    ) private view returns (Angle memory a) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k);
        _requireNonnegative(a.theta0);
        if (
            FloatMath(modules.math).compare(
                a.theta0,
                IPeriodicDynamicsElementary(modules.elementary).PI()
            ) > 0
        ) revert InvalidInput();
    }
    function _torsion(
        Run storage r,
        uint256 index
    ) private view returns (Torsion memory t) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (
            t.a == t.b ||
            t.a == t.c ||
            t.a == t.d ||
            t.b == t.c ||
            t.b == t.d ||
            t.c == t.d
        ) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = IPeriodicDynamicsElementary(modules.elementary)
            .TWO_PI();
        if (
            m.compare(t.phase, m.neg(twoPi)) < 0 ||
            m.compare(t.phase, twoPi) > 0
        ) revert InvalidInput();
    }
    function _parameters(
        Run storage r,
        uint256 atom
    ) private view returns (ParticleParameters memory p) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma);
        _requireNonnegative(p.epsilon);
    }

    function _exception(
        Run storage r,
        uint256 index
    ) private view returns (Pair memory p) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(
            data.readExceptionWord(r.datasetId, offset + 1),
            r.atomCount
        );
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(
            data.readExceptionWord(r.datasetId, offset + 5)
        );
        if (p.kind == 1) {
            if (
                p.sigma != bytes16(0) ||
                p.epsilon != bytes16(0) ||
                p.chargeProduct != bytes16(0)
            ) revert InvalidInput();
        } else {
            _requirePositive(p.sigma);
            _requireNonnegative(p.epsilon);
        }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
    }

    function _pair(
        Run storage r,
        uint256 index
    ) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][
            uint256(p.a) * r.atomCount + p.b
        ];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        // Electrostatics are evaluated only by EwaldForceEvaluator.
        p.chargeProduct = bytes16(0);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(
        uint256 index,
        uint256 count
    ) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if ((mid * (2 * count - mid - 1)) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - (low * (2 * count - low - 1)) / 2);
    }

    function _mass(
        Run storage r,
        uint256 atom
    ) private view returns (bytes16 mass) {
        mass = _decode(
            IPeriodicDynamicsData(modules.dataset).readParticleWord(
                r.datasetId,
                atom * 4
            )
        );
        _requirePositive(mass);
    }
    function _readVector(
        Run storage r,
        uint256 buffer,
        uint256 atom,
        uint256 field
    ) private view returns (bytes16[3] memory result) {
        bytes32[] memory words = statePage.readWords(
            r.stateNamespace,
            _vectorIndex(r, buffer, atom, field),
            3
        );
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(
        Run storage r,
        uint256 buffer,
        uint256 atom,
        bytes16[3] memory force,
        bool subtract
    ) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(
            r.stateNamespace,
            offset,
            3
        );
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract
                ? m.sub(previous, force[d])
                : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(
            _decode(statePage.readWord(r.stateNamespace, offset)),
            energy
        );
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(
        Run storage r,
        uint256 buffer,
        uint256 atom,
        uint256 field
    ) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(
        Run storage r,
        uint256 buffer
    ) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(
        bytes32 protocolId
    ) private view returns (bytes32 manifest) {
        if (
            address(statePage) == address(0) ||
            address(ewaldEvaluator) == address(0)
        ) revert NotConfigured();
        address[12] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 12; ++i)
            if (addresses[i].codehash != moduleCodeHashes[i])
                revert ModuleCodeChanged();
        if (
            address(statePage).codehash != statePageCodeHash ||
            address(ewaldEvaluator).codehash != ewaldCodeHash ||
            address(snapshotPage).codehash != snapshotPageCodeHash ||
            address(ewaldOutputPage).codehash != ewaldOutputPageCodeHash
        ) revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 12; ++i)
            registry.assertModule(
                protocolId,
                addresses[i],
                moduleCodeHashes[i]
            );
        registry.assertModule(
            protocolId,
            address(statePage),
            statePageCodeHash
        );
        registry.assertModule(
            protocolId,
            address(this),
            address(this).codehash
        );
        registry.assertModule(
            protocolId,
            address(ewaldEvaluator),
            ewaldCodeHash
        );
        registry.assertModule(
            protocolId,
            address(snapshotPage),
            snapshotPageCodeHash
        );
        registry.assertModule(
            protocolId,
            address(ewaldOutputPage),
            ewaldOutputPageCodeHash
        );
    }
    function _moduleAddresses(
        Modules memory m
    ) private pure returns (address[12] memory) {
        return
            [
                m.registry,
                m.dataset,
                m.math,
                m.integrator,
                m.bond,
                m.angle,
                m.torsion,
                m.lj,
                m.coulomb,
                m.elementary,
                m.geometry,
                m.nonbonded
            ];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) {
        return bytes32(uint256(uint128(value)));
    }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff)
            revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if (
            (bits >> 127) != 0 &&
            (bits & 0x7fffffffffffffffffffffffffffffff) != 0
        ) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0)
            revert InvalidInput();
    }
}

contracts/core/EwaldForceEvaluator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {ElementaryMath} from "../math/ElementaryMath.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {EwaldRealSpaceKernel} from "../kernels/EwaldRealSpaceKernel.sol";
import {EwaldReciprocalKernel} from "../kernels/EwaldReciprocalKernel.sol";
import {EwaldCorrections} from "../kernels/EwaldCorrections.sol";
import {IEwaldScalarMath} from "../kernels/EwaldKernelBase.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {PeriodicDataset} from "./PeriodicDataset.sol";
import {ExperimentRegistry} from "./ExperimentRegistry.sol";

/// @notice Complete bounded Ewald electrostatic evaluation of a sealed on-chain snapshot.
/// @dev Finite real cutoff and integer reciprocal extent are explicit approximations.
///      No coordinate, charge, structure-factor or force result is supplied off-chain.
contract EwaldForceEvaluator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error InvalidInput();
    error NotConfigured();
    error UnknownRun();
    error InvalidWork();
    error DependencyChanged();
    error DatasetChanged();
    error SnapshotNotFrozen();
    error NotCompleted();
    error AlreadyCompleted();
    uint32 public constant MAX_ATOMS = 1024;
    uint32 public constant MAX_MODE = 32;
    uint32 public constant MAX_WORK = 8;
    bytes32 public constant IMPLEMENTATION_ID =
        keccak256("ORVIA.EwaldForceEvaluator.v0.5.SealedSnapshot");
    enum Status {
        Missing,
        Loading,
        ValidatingExceptions,
        RealPairs,
        Exceptions,
        ModeSetup,
        StructureFactor,
        ModeForces,
        Background,
        Completed
    }
    struct Modules {
        address registry;
        address dataset;
        address math;
        address scalar;
        address elementary;
        address geometry;
        address realSpace;
        address reciprocal;
        address corrections;
    }
    struct Registration {
        bytes32 datasetId;
        address sourcePage;
        bytes32 sourceNamespace;
        uint32 positionOffset;
        uint32 positionStride;
        bytes16 alpha;
        uint32 maxMode;
    }
    struct Run {
        Registration input;
        Status status;
        uint32 cursor;
        uint32 atomCount;
        uint32 pairCount;
        uint32 exceptionCount;
        uint32 modeIndex;
        uint32 modeCount;
        uint32 lastExceptionKey;
        bytes32 namespace;
        bytes32 commitment;
        bytes32 datasetCommitment;
        bytes32 protocolId;
        bytes32 sourceCodeHash;
        address sourceWriter;
        bytes32 sourceWriterCodeHash;
        bytes16[3] box;
        bytes16 cutoff;
        bytes16 prefactor;
        bytes16 totalCharge;
        int32[3] mode;
        bytes16[3] wave;
        bytes16 coefficient;
        bytes16 totalCosine;
        bytes16 totalSine;
    }
    struct PairException {
        uint32 a;
        uint32 b;
        uint32 kind;
        bytes16 desired;
    }
    address public immutable owner;
    Modules public modules;
    bytes32[9] public moduleCodeHashes;
    bytes32 public immutable coreConfigurationHash;
    WorkingStatePage public outputPage;
    bytes32 public outputPageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextRunId = 1;
    mapping(uint256 => Run) private runs;
    mapping(address => bool) public isSnapshotPage;
    mapping(uint256 => mapping(uint256 => uint256)) private exceptionIndices;
    event SnapshotPageCreated(address indexed page, address indexed writer);
    event RunRegistered(
        uint256 indexed runId,
        bytes32 commitment,
        bytes32 outputNamespace
    );
    event Advanced(
        uint256 indexed runId,
        uint256 work,
        Status status,
        uint32 cursor,
        uint32 modeIndex
    );

    constructor(address owner_, Modules memory m) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = m;
        address[9] memory addresses = _addresses(m);
        for (uint256 i; i < 9; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            moduleCodeHashes[i] = addresses[i].codehash;
        }
        if (
            IEwaldScalarMath(m.scalar).numericalMath() != m.math ||
            address(ElementaryMath(m.elementary).numericalMath()) != m.math ||
            address(OrthorhombicGeometry(m.geometry).numericalMath()) != m.math
        ) revert InvalidConfiguration();
        if (
            address(EwaldRealSpaceKernel(m.realSpace).numericalMath()) !=
                m.math ||
            address(EwaldRealSpaceKernel(m.realSpace).scalarMath()) != m.scalar
        ) revert InvalidConfiguration();
        if (
            address(EwaldReciprocalKernel(m.reciprocal).numericalMath()) !=
                m.math ||
            address(EwaldReciprocalKernel(m.reciprocal).scalarMath()) !=
                m.scalar ||
            address(EwaldReciprocalKernel(m.reciprocal).elementaryMath()) !=
                m.elementary
        ) revert InvalidConfiguration();
        if (
            address(EwaldCorrections(m.corrections).numericalMath()) !=
                m.math ||
            address(EwaldCorrections(m.corrections).scalarMath()) != m.scalar
        ) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(m, moduleCodeHashes));
    }
    function bindOutputPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(outputPage) != address(0)) revert AlreadyConfigured();
        if (
            page.code.length == 0 ||
            WorkingStatePage(page).writer() != address(this)
        ) revert InvalidConfiguration();
        outputPage = WorkingStatePage(page);
        outputPageCodeHash = page.codehash;
        configurationHash = keccak256(
            abi.encode(coreConfigurationHash, page, outputPageCodeHash)
        );
    }
    function createSnapshotPage(
        address writer
    ) external returns (address page) {
        if (msg.sender != owner) revert Unauthorized();
        page = address(new WorkingStatePage(writer));
        isSnapshotPage[page] = true;
        emit SnapshotPageCreated(page, writer);
    }
    function registerRun(
        bytes32 protocolId,
        Registration calldata input
    ) external returns (uint256 id) {
        if (msg.sender != owner) revert Unauthorized();
        _positive(input.alpha);
        if (
            input.maxMode == 0 ||
            input.maxMode > MAX_MODE ||
            !isSnapshotPage[input.sourcePage] ||
            input.positionStride < 3
        ) revert InvalidInput();
        bytes32 manifest = _dependencies(protocolId);
        id = nextRunId++;
        Run storage r = runs[id];
        r.input = input;
        r.protocolId = protocolId;
        PeriodicDataset data = PeriodicDataset(modules.dataset);
        r.datasetCommitment = data.assertDataset(input.datasetId);
        (, , r.atomCount, , , , r.pairCount) = data.datasetInfo(
            input.datasetId
        );
        if (
            r.atomCount < 2 ||
            r.atomCount > MAX_ATOMS ||
            r.pairCount != (uint256(r.atomCount) * (r.atomCount - 1)) / 2
        ) revert InvalidInput();
        (r.box, , r.cutoff, r.prefactor, r.exceptionCount) = data.periodicInfo(
            input.datasetId
        );
        OrthorhombicGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount)
            revert InvalidInput();
        int32 extent = int32(input.maxMode);
        EwaldReciprocalKernel(modules.reciprocal).waveVector(
            [extent, extent, extent],
            r.box,
            input.alpha,
            r.prefactor
        );
        FloatMath m = FloatMath(modules.math);
        if (m.compare(m.mul(input.alpha, r.cutoff), m.fromUInt(16)) > 0)
            revert InvalidInput();
        (uint32 capacity, bool isSealed) = WorkingStatePage(input.sourcePage)
            .namespaceInfo(input.sourceNamespace);
        if (!isSealed) revert SnapshotNotFrozen();
        if (
            uint256(input.positionOffset) +
                uint256(r.atomCount - 1) * input.positionStride +
                3 >
            capacity
        ) revert InvalidInput();
        r.sourceCodeHash = input.sourcePage.codehash;
        r.sourceWriter = WorkingStatePage(input.sourcePage).writer();
        r.sourceWriterCodeHash = r.sourceWriter.codehash;
        r.modeCount = modeCount(input.maxMode);
        r.status = Status.Loading;
        r.namespace = keccak256(
            abi.encode(
                bytes32("ORVIA-EWALD-STATE-v1"),
                block.chainid,
                address(this),
                id
            )
        );
        bytes32 snapshot = keccak256(
            abi.encode(
                input,
                r.sourceCodeHash,
                r.sourceWriter,
                r.sourceWriterCodeHash
            )
        );
        r.commitment = keccak256(
            abi.encode(
                bytes32("ORVIA-EWALD-RUN-v1"),
                block.chainid,
                address(this),
                id,
                manifest,
                r.datasetCommitment,
                configurationHash,
                snapshot
            )
        );
        outputPage.createNamespace(r.namespace, r.atomCount * 3 + 6);
        emit RunRegistered(id, r.commitment, r.namespace);
    }
    function advance(
        uint256 id,
        uint256 workLimit
    ) external returns (uint256 processed, bool completed) {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWork();
        Run storage r = _get(id);
        if (r.status == Status.Completed) revert AlreadyCompleted();
        _dependencies(r.protocolId);
        _snapshot(r);
        if (
            PeriodicDataset(modules.dataset).assertDataset(r.input.datasetId) !=
            r.datasetCommitment
        ) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            _one(id, r);
            ++processed;
        }
        completed = r.status == Status.Completed;
        emit Advanced(id, processed, r.status, r.cursor, r.modeIndex);
    }
    function runInfo(
        uint256 id
    )
        external
        view
        returns (
            Status status,
            uint32 cursor,
            uint32 modeIndex,
            uint32 atomCount,
            uint32 modes,
            bytes32 stateNamespace,
            bytes32 commitment
        )
    {
        Run storage r = _get(id);
        return (
            r.status,
            r.cursor,
            r.modeIndex,
            r.atomCount,
            r.modeCount,
            r.namespace,
            r.commitment
        );
    }
    function moduleConfiguration() external view returns (Modules memory) {
        return modules;
    }
    function parameters(
        uint256 id
    ) external view returns (Registration memory) {
        return _get(id).input;
    }
    function forceAt(
        uint256 id,
        uint256 atom
    ) external view returns (bytes16[3] memory force) {
        Run storage r = _get(id);
        if (r.status != Status.Completed) revert NotCompleted();
        if (atom >= r.atomCount) revert InvalidInput();
        for (uint256 d; d < 3; ++d)
            force[d] = _decode(outputPage.readWord(r.namespace, atom * 3 + d));
    }
    /// @return values [total, real, reciprocal, self, background, exceptions].
    function energies(
        uint256 id
    ) external view returns (bytes16[6] memory values) {
        Run storage r = _get(id);
        if (r.status != Status.Completed) revert NotCompleted();
        for (uint256 i; i < 6; ++i)
            values[i] = _decode(
                outputPage.readWord(r.namespace, uint256(r.atomCount) * 3 + i)
            );
    }
    function modeCount(uint32 extent) public pure returns (uint32) {
        if (extent == 0 || extent > MAX_MODE) revert InvalidInput();
        uint32 width = extent * 2 + 1;
        return extent * (1 + width + width * width);
    }
    function modeAt(
        uint32 index,
        uint32 extent
    ) public pure returns (int32[3] memory mode) {
        if (index >= modeCount(extent)) revert InvalidInput();
        uint32 width = extent * 2 + 1;
        if (index < extent) {
            mode[2] = int32(index + 1);
            return mode;
        }
        index -= extent;
        if (index < extent * width) {
            mode[1] = int32(index / width + 1);
            mode[2] = int32(index % width) - int32(extent);
            return mode;
        }
        index -= extent * width;
        mode[0] = int32(index / (width * width) + 1);
        mode[1] = int32((index / width) % width) - int32(extent);
        mode[2] = int32(index % width) - int32(extent);
    }
    function _one(uint256 id, Run storage r) private {
        if (r.status == Status.Loading) {
            _position(r, r.cursor);
            bytes16 q = _charge(r, r.cursor);
            FloatMath m = FloatMath(modules.math);
            r.totalCharge = m.add(r.totalCharge, q);
            _energy(
                r,
                2,
                EwaldCorrections(modules.corrections).selfEnergy(
                    q,
                    r.input.alpha,
                    r.prefactor
                )
            );
            if (++r.cursor == r.atomCount) {
                r.cursor = 0;
                r.status = r.exceptionCount == 0
                    ? Status.RealPairs
                    : Status.ValidatingExceptions;
            }
        } else if (r.status == Status.ValidatingExceptions) {
            PairException memory p = _exception(r, r.cursor);
            uint32 key = p.a * r.atomCount + p.b;
            if (r.cursor != 0 && key <= r.lastExceptionKey)
                revert InvalidInput();
            r.lastExceptionKey = key;
            exceptionIndices[id][key] = r.cursor + 1;
            if (++r.cursor == r.exceptionCount) {
                r.cursor = 0;
                r.status = Status.RealPairs;
            }
        } else if (r.status == Status.RealPairs) {
            (uint32 a, uint32 b) = _pairIndices(r.cursor, r.atomCount);
            if (exceptionIndices[id][uint256(a) * r.atomCount + b] == 0)
                _realPair(r, a, b);
            if (++r.cursor == r.pairCount) {
                r.cursor = 0;
                r.status = r.exceptionCount == 0
                    ? Status.ModeSetup
                    : Status.Exceptions;
            }
        } else if (r.status == Status.Exceptions) {
            _exceptionPair(r, _exception(r, r.cursor));
            if (++r.cursor == r.exceptionCount) {
                r.cursor = 0;
                r.status = Status.ModeSetup;
            }
        } else if (r.status == Status.ModeSetup) {
            r.mode = modeAt(r.modeIndex, r.input.maxMode);
            (r.wave, r.coefficient) = EwaldReciprocalKernel(modules.reciprocal)
                .waveVector(r.mode, r.box, r.input.alpha, r.prefactor);
            r.totalCosine = bytes16(0);
            r.totalSine = bytes16(0);
            r.cursor = 0;
            r.status = Status.StructureFactor;
        } else if (r.status == Status.StructureFactor) {
            (bytes16 c, bytes16 s) = _term(r, r.cursor);
            FloatMath m = FloatMath(modules.math);
            r.totalCosine = m.add(r.totalCosine, c);
            r.totalSine = m.add(r.totalSine, s);
            if (++r.cursor == r.atomCount) {
                _energy(
                    r,
                    1,
                    EwaldReciprocalKernel(modules.reciprocal).modeEnergy(
                        r.coefficient,
                        r.totalCosine,
                        r.totalSine
                    )
                );
                r.cursor = 0;
                r.status = Status.ModeForces;
            }
        } else if (r.status == Status.ModeForces) {
            (bytes16 c, bytes16 s) = _term(r, r.cursor);
            bytes16[3] memory force = EwaldReciprocalKernel(modules.reciprocal)
                .forceContribution(
                    r.wave,
                    r.coefficient,
                    c,
                    s,
                    r.totalCosine,
                    r.totalSine
                );
            _force(r, r.cursor, force, false);
            if (++r.cursor == r.atomCount) {
                r.cursor = 0;
                ++r.modeIndex;
                r.status = r.modeIndex == r.modeCount
                    ? Status.Background
                    : Status.ModeSetup;
            }
        } else if (r.status == Status.Background) {
            _energy(
                r,
                3,
                EwaldCorrections(modules.corrections).backgroundEnergy(
                    r.totalCharge,
                    r.box,
                    r.input.alpha,
                    r.prefactor
                )
            );
            outputPage.sealNamespace(r.namespace);
            r.status = Status.Completed;
        } else revert InvalidInput();
    }
    function _realPair(Run storage r, uint32 a, uint32 b) private {
        bytes16 product = FloatMath(modules.math).mul(
            _charge(r, a),
            _charge(r, b)
        );
        (bytes16 energy, bytes16[3] memory force) = EwaldRealSpaceKernel(
            modules.realSpace
        ).evaluate(
                _displacement(r, a, b),
                product,
                r.prefactor,
                r.input.alpha,
                r.cutoff
            );
        _energy(r, 0, energy);
        _force(r, a, force, false);
        _force(r, b, force, true);
    }
    function _exceptionPair(Run storage r, PairException memory p) private {
        bytes16[3] memory d = _displacement(r, p.a, p.b);
        FloatMath m = FloatMath(modules.math);
        for (uint256 axis; axis < 3; ++axis)
            if (
                m.compare(m.abs(d[axis]), m.div(r.box[axis], m.fromUInt(2))) ==
                0
            ) revert InvalidInput();
        bytes16 product = m.mul(_charge(r, p.a), _charge(r, p.b));
        (bytes16 energy, bytes16[3] memory force) = EwaldCorrections(
            modules.corrections
        ).exception(d, product, p.desired, r.prefactor, r.input.alpha);
        _energy(r, 4, energy);
        _force(r, p.a, force, false);
        _force(r, p.b, force, true);
    }
    function _term(
        Run storage r,
        uint256 atom
    ) private view returns (bytes16, bytes16) {
        return
            EwaldReciprocalKernel(modules.reciprocal).structureFactorTerm(
                _position(r, atom),
                _charge(r, atom),
                r.mode,
                r.box
            );
    }
    function _position(
        Run storage r,
        uint256 atom
    ) private view returns (bytes16[3] memory p) {
        uint256 offset = uint256(r.input.positionOffset) +
            atom * r.input.positionStride;
        for (uint256 axis; axis < 3; ++axis)
            p[axis] = _decode(
                WorkingStatePage(r.input.sourcePage).readWord(
                    r.input.sourceNamespace,
                    offset + axis
                )
            );
    }
    function _displacement(
        Run storage r,
        uint256 a,
        uint256 b
    ) private view returns (bytes16[3] memory) {
        return
            OrthorhombicGeometry(modules.geometry).displacement(
                _position(r, a),
                _position(r, b),
                r.box
            );
    }
    function _charge(
        Run storage r,
        uint256 atom
    ) private view returns (bytes16) {
        return
            _decode(
                PeriodicDataset(modules.dataset).readNonbondedWord(
                    r.input.datasetId,
                    atom * 3 + 2
                )
            );
    }
    function _exception(
        Run storage r,
        uint256 index
    ) private view returns (PairException memory p) {
        PeriodicDataset data = PeriodicDataset(modules.dataset);
        uint256 start = index * 6;
        uint256 a = uint256(data.readExceptionWord(r.input.datasetId, start));
        uint256 b = uint256(
            data.readExceptionWord(r.input.datasetId, start + 1)
        );
        uint256 kind = uint256(
            data.readExceptionWord(r.input.datasetId, start + 2)
        );
        if (a >= b || b >= r.atomCount || kind < 1 || kind > 2)
            revert InvalidInput();
        p.a = uint32(a);
        p.b = uint32(b);
        p.kind = uint32(kind);
        bytes16 sigma = _decode(
            data.readExceptionWord(r.input.datasetId, start + 3)
        );
        bytes16 epsilon = _decode(
            data.readExceptionWord(r.input.datasetId, start + 4)
        );
        p.desired = _decode(
            data.readExceptionWord(r.input.datasetId, start + 5)
        );
        if (kind == 1) {
            if (
                sigma != bytes16(0) ||
                epsilon != bytes16(0) ||
                p.desired != bytes16(0)
            ) revert InvalidInput();
        } else {
            _positive(sigma);
            if (FloatMath(modules.math).compare(epsilon, bytes16(0)) < 0)
                revert InvalidInput();
        }
    }
    function _force(
        Run storage r,
        uint256 atom,
        bytes16[3] memory force,
        bool negative
    ) private {
        FloatMath m = FloatMath(modules.math);
        bytes32[] memory words = new bytes32[](3);
        for (uint256 axis; axis < 3; ++axis) {
            bytes16 old = _decode(
                outputPage.readWord(r.namespace, atom * 3 + axis)
            );
            words[axis] = _encode(
                negative ? m.sub(old, force[axis]) : m.add(old, force[axis])
            );
        }
        outputPage.writeWords(r.namespace, atom * 3, words);
    }
    function _energy(Run storage r, uint256 component, bytes16 value) private {
        uint256 start = uint256(r.atomCount) * 3;
        FloatMath m = FloatMath(modules.math);
        outputPage.writeWord(
            r.namespace,
            start,
            _encode(
                m.add(_decode(outputPage.readWord(r.namespace, start)), value)
            )
        );
        outputPage.writeWord(
            r.namespace,
            start + 1 + component,
            _encode(
                m.add(
                    _decode(
                        outputPage.readWord(r.namespace, start + 1 + component)
                    ),
                    value
                )
            )
        );
    }
    function _snapshot(Run storage r) private view {
        if (
            r.input.sourcePage.codehash != r.sourceCodeHash ||
            r.sourceWriter.codehash != r.sourceWriterCodeHash
        ) revert DependencyChanged();
        (, bool isSealed) = WorkingStatePage(r.input.sourcePage).namespaceInfo(
            r.input.sourceNamespace
        );
        if (!isSealed) revert SnapshotNotFrozen();
    }
    function _dependencies(bytes32 protocolId) private view returns (bytes32) {
        if (address(outputPage) == address(0)) revert NotConfigured();
        address[9] memory addresses = _addresses(modules);
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        bytes32 manifest = registry.assertProtocol(protocolId);
        for (uint256 i; i < 9; ++i) {
            if (addresses[i].codehash != moduleCodeHashes[i])
                revert DependencyChanged();
            if (i != 0)
                registry.assertModule(
                    protocolId,
                    addresses[i],
                    moduleCodeHashes[i]
                );
        }
        if (address(outputPage).codehash != outputPageCodeHash)
            revert DependencyChanged();
        registry.assertModule(
            protocolId,
            address(outputPage),
            outputPageCodeHash
        );
        registry.assertModule(
            protocolId,
            address(this),
            address(this).codehash
        );
        return manifest;
    }
    function _addresses(
        Modules memory m
    ) private pure returns (address[9] memory) {
        return
            [
                m.registry,
                m.dataset,
                m.math,
                m.scalar,
                m.elementary,
                m.geometry,
                m.realSpace,
                m.reciprocal,
                m.corrections
            ];
    }
    function _pairIndices(
        uint256 index,
        uint256 count
    ) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if ((mid * (2 * count - mid - 1)) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - (low * (2 * count - low - 1)) / 2);
    }
    function _get(uint256 id) private view returns (Run storage r) {
        r = runs[id];
        if (r.status == Status.Missing) revert UnknownRun();
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert InvalidInput();
    }
    function _encode(bytes16 value) private pure returns (bytes32) {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert InvalidInput();
        return bytes32(uint256(uint128(value)));
    }
    function _positive(bytes16 value) private view {
        if (
            !FloatMath(modules.math).isFinite(value) ||
            FloatMath(modules.math).compare(value, bytes16(0)) <= 0
        ) revert InvalidInput();
    }
}

