// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Append-only protocol/version commitments for ORVIA component validation.
/// @dev A registered protocol cannot be edited, deleted, or reassigned.
contract ExperimentRegistry {
    error Unauthorized();
    error InvalidOwner();
    error InvalidProtocol();
    error AlreadyRegistered();
    error UnknownProtocol();
    error InvalidModule();
    error DuplicateModule();
    error ModuleCodeChanged(address module);
    error ModuleNotRegistered(address module);

    uint256 public constant MAX_MODULES = 64;
    address public immutable owner;

    struct Protocol {
        bytes32 specificationHash;
        bytes32 manifestHash;
        address[] modules;
        bytes32[] codeHashes;
        bool exists;
    }

    mapping(bytes32 => Protocol) private _protocols;

    event ProtocolRegistered(bytes32 indexed protocolId, bytes32 specificationHash, bytes32 manifestHash);

    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidOwner();
        owner = owner_;
    }

    function registerProtocol(
        bytes32 protocolId,
        bytes32 specificationHash,
        address[] calldata modules
    ) external returns (bytes32 manifestHash) {
        if (msg.sender != owner) revert Unauthorized();
        if (protocolId == bytes32(0) || specificationHash == bytes32(0)) revert InvalidProtocol();
        if (_protocols[protocolId].exists) revert AlreadyRegistered();
        if (modules.length == 0 || modules.length > MAX_MODULES) revert InvalidModule();

        bytes32[] memory hashes = new bytes32[](modules.length);
        for (uint256 i; i < modules.length; ++i) {
            if (modules[i].code.length == 0) revert InvalidModule();
            for (uint256 j; j < i; ++j) {
                if (modules[j] == modules[i]) revert DuplicateModule();
            }
            hashes[i] = modules[i].codehash;
        }
        manifestHash = keccak256(abi.encode(protocolId, specificationHash, modules, hashes));
        Protocol storage p = _protocols[protocolId];
        p.specificationHash = specificationHash;
        p.manifestHash = manifestHash;
        p.modules = modules;
        p.codeHashes = hashes;
        p.exists = true;
        emit ProtocolRegistered(protocolId, specificationHash, manifestHash);
    }

    function getProtocol(bytes32 protocolId)
        external view returns (bytes32 specificationHash, bytes32 manifestHash, uint256 moduleCount)
    {
        Protocol storage p = _get(protocolId);
        return (p.specificationHash, p.manifestHash, p.modules.length);
    }

    function moduleAt(bytes32 protocolId, uint256 index) external view returns (address module, bytes32 codeHash) {
        Protocol storage p = _get(protocolId);
        return (p.modules[index], p.codeHashes[index]);
    }

    function assertProtocol(bytes32 protocolId) external view returns (bytes32 manifestHash) {
        Protocol storage p = _get(protocolId);
        for (uint256 i; i < p.modules.length; ++i) {
            if (p.modules[i].code.length == 0 || p.modules[i].codehash != p.codeHashes[i]) {
                revert ModuleCodeChanged(p.modules[i]);
            }
        }
        return p.manifestHash;
    }

    function assertModule(bytes32 protocolId, address module, bytes32 expectedHash) external view {
        Protocol storage p = _get(protocolId);
        for (uint256 i; i < p.modules.length; ++i) {
            if (p.modules[i] == module) {
                if (p.codeHashes[i] != expectedHash || module.codehash != expectedHash || module.code.length == 0) {
                    revert ModuleCodeChanged(module);
                }
                return;
            }
        }
        revert ModuleNotRegistered(module);
    }

    function _get(bytes32 protocolId) private view returns (Protocol storage p) {
        p = _protocols[protocolId];
        if (!p.exists) revert UnknownProtocol();
    }
}

contracts/core/LangevinDynamicsCoordinat.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {NeighborList} from "./NeighborList.sol";
import {FloatMath} from "../math/FloatMath.sol";

interface ILangevinDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function periodicInfo(bytes32 id) external view returns (bytes16[3] memory, bytes16, bytes16, bytes16, uint32);
}
interface ILangevinDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface ILangevinDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface ILangevinDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface ILangevinDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface ILangevinDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface ILangevinDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}
interface ILangevinDynamicsIntegrator {
    function scalarMath() external view returns (address);
    function coefficients(bytes16 mass, bytes16 dt, bytes16 friction, bytes16 kT) external view returns (bytes16,bytes16);
    function begin(bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force,
        bytes16 mass, bytes16 dt, bytes16 friction, bytes16 kT, bytes16[3] calldata normal)
        external view returns (bytes16[3] memory nextPosition, bytes16[3] memory thermalVelocity);
    function finish(bytes16[3] calldata thermalVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity);
}
interface ILangevinRandom {
    function scalarMath() external view returns (address);
    function elementaryMath() external view returns (address);
    function normalPair(bytes32 seed, bytes32 streamId, uint32 replica, uint64 step, uint64 draw)
        external view returns (bytes16,bytes16);
}

interface ILangevinGeometry {
    function displacement(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata box)
        external view returns (bytes16[3] memory);
    function validateBox(bytes16[3] calldata box, bytes16 cutoff) external view;
}
interface ILangevinNonbonded {
    function ljKernel() external view returns (address);
    function coulombKernel() external view returns (address);
    function evaluate(bytes16[3] calldata displacement, bytes16 sigma, bytes16 epsilon,
        bytes16 chargeProduct, bytes16 prefactor, bytes16 switchDistance, bytes16 cutoff, bool exception)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}

/// @notice Bounded BAOAB Langevin dynamics with deterministic streams and neighbor lists.
/// @dev Resumable Verlet lists preserve the periodic cutoff Hamiltonian and
///      lexicographic accumulation order, including all direct exceptions.
///      Thermostat inputs and streams are immutable; no constraints or Ewald/PME.
contract LangevinDynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
        address scalar;
        address random;
    }
    Modules private _modules;
    bytes32[14] public moduleCodeHashes;
    WorkingStatePage public statePage;
    NeighborList public neighborList;
    bytes32 public neighborCodeHash;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingExceptions, PreparingInitial, InitialBonds, InitialAngles, InitialTorsions, InitialPairs,
        Drift, PreparingNext, NextBonds, NextAngles, NextTorsions, NextPairs, Kick, Completed
    }
    struct Parameters {
        bytes16 dt;
        uint32 steps;
        bytes16 skin;
        bytes16 friction;
        bytes16 kT;
        bytes32 seed;
        bytes32 streamId;
        uint32 replica;
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        bytes16 skin;
        bytes16 friction;
        bytes16 kT;
        bytes32 seed;
        bytes32 streamId;
        uint32 replica;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; }
    struct ParticleParameters { bytes16 sigma; bytes16 epsilon; bytes16 charge; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event StepCommitted(uint256 indexed experimentId, uint256 completedSteps, uint256 activeBuffer);

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        _modules = modules_;
        address[14] memory addresses = _moduleAddresses(modules_);
        bytes32[14] memory hashes;
        for (uint256 i; i < 14; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 14; ++i) {
            if (ILangevinDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (ILangevinDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            ILangevinDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        if (ILangevinNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
            ILangevinNonbonded(modules_.nonbonded).coulombKernel() != modules_.coulomb) revert InvalidConfiguration();
        if (ILangevinDynamicsIntegrator(modules_.integrator).scalarMath() != modules_.scalar ||
            ILangevinRandom(modules_.random).scalarMath() != modules_.scalar ||
            ILangevinRandom(modules_.random).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function modules() external view returns (Modules memory) { return _modules; }

    function bindWorkingPage(address page, address neighbors) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this) || neighbors.code.length == 0)
            revert InvalidConfiguration();
        NeighborList list = NeighborList(neighbors);
        if (list.writer() != address(this) || address(list.statePage()) != page ||
            address(list.numericalMath()) != _modules.math || address(list.geometry()) != _modules.geometry) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        neighborList = list; neighborCodeHash = neighbors.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash, neighbors, neighbors.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, Parameters calldata parameters)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(parameters.dt); _requirePositive(parameters.skin);
        _requireNonnegative(parameters.friction); _requirePositive(parameters.kT);
        if (parameters.streamId == bytes32(0)) revert InvalidInput();
        ILangevinDynamicsIntegrator(_modules.integrator).coefficients(
            bytes16(0x3fff0000000000000000000000000000), parameters.dt, parameters.friction, parameters.kT);
        if (parameters.steps == 0 || parameters.steps > MAX_STEPS) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = ILangevinDynamicsData(_modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = ILangevinDynamicsData(_modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 ||
            r.pairCount != uint256(r.atomCount) * (r.atomCount - 1) / 2) revert InvalidInput();
        (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount) =
            ILangevinDynamicsData(_modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount) revert InvalidInput();
        _requirePositive(r.switchDistance); _requirePositive(r.cutoff); _requireNonnegative(r.prefactor);
        if (FloatMath(_modules.math).compare(r.switchDistance, r.cutoff) >= 0) revert InvalidInput();
        ILangevinGeometry(_modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = parameters.dt; r.skin = parameters.skin;
        r.friction = parameters.friction; r.kT = parameters.kT;
        r.seed = parameters.seed; r.streamId = parameters.streamId; r.replica = parameters.replica;
        r.targetSteps = parameters.steps;
        r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-LANGEVIN-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-LANGEVIN-RUN-v1"), block.chainid, address(this),
            experimentId, manifest, datasetId, datasetCommitment, configurationHash, parameters, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        neighborList.registerList(r.stateNamespace, r.atomCount, r.box, r.cutoff, parameters.skin);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (ILangevinDynamicsData(_modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                (uint256 used, bool ready) = neighborList.advance(r.stateNamespace, workLimit - processed);
                processed += used;
                if (ready) { r.status = Status(uint8(r.status) + 1); r.cursor = 0; }
            } else {
                _process(r);
                ++processed;
                ++r.cursor;
                if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
            }
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 completedSteps, uint256 targetSteps, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }

    function stateAt(uint256 experimentId, uint256 atom) external view returns (
        bytes16[3] memory position, bytes16[3] memory velocity, bytes16[3] memory force
    ) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(uint256 experimentId) external view returns (
        bytes16 dt, uint32 bondCount, uint32 angleCount, uint32 torsionCount, uint32 pairCount, bytes32 datasetCommitment
    ) {
        Run storage r = _get(experimentId);
        return (r.dt, r.bondCount, r.angleCount, r.torsionCount, r.pairCount, r.datasetCommitment);
    }

    function neighborParameters(uint256 experimentId) external view returns (bytes16 skin, address list) {
        return (_get(experimentId).skin, address(neighborList));
    }

    function periodicParameters(uint256 experimentId) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Run storage r = _get(experimentId);
        return (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount);
    }

    function stochasticParameters(uint256 experimentId) external view returns (
        bytes16 friction, bytes16 kT, bytes32 seed, bytes32 streamId, uint32 replica
    ) {
        Run storage r = _get(experimentId);
        return (r.friction, r.kT, r.seed, r.streamId, r.replica);
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions) _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status <= Status.NextPairs) _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (r.status == Status.Kick) {
            r.activeBuffer = 1 - r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace);
                r.status = Status.Completed;
                return;
            }
            r.status = Status.Drift;
        } else r.status = Status(uint8(r.status) + 1);
        r.cursor = 0;
        // Preparation snapshots remain fixed until the complete list is ready.
        while (true) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                neighborList.beginEvaluation(r.stateNamespace,
                    r.status == Status.PreparingInitial ? r.activeBuffer : 1 - r.activeBuffer);
                return;
            }
            if (_stageCount(r) != 0) return;
            r.status = Status(uint8(r.status) + 1);
        }
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (r.status == Status.Loading || r.status == Status.Drift || r.status == Status.Kick) return r.atomCount;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        (,,, uint32 candidates,,,,) = neighborList.listInfo(r.stateNamespace);
        return candidates;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingExceptions) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status) - 7;
        if (status >= Status.NextBonds && status <= Status.NextPairs) return uint8(status) - 13;
        revert InvalidInput();
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        _parameters(r, atom);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            words[d + 3] = _encode(_decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)));
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
        (bytes16[3] memory position, bytes16[3] memory halfVelocity) = _thermostatDrift(r);
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }

    function _thermostatDrift(Run storage r) private view returns (bytes16[3] memory, bytes16[3] memory) {
        bytes16[3] memory normal;
        if ((uint128(r.friction) & 0x7fffffffffffffffffffffffffffffff) != 0) {
            uint64 draw = uint64(r.cursor) * 2;
            (normal[0], normal[1]) = ILangevinRandom(_modules.random).normalPair(
                r.seed, r.streamId, r.replica, uint64(r.completedSteps), draw);
            (normal[2],) = ILangevinRandom(_modules.random).normalPair(
                r.seed, r.streamId, r.replica, uint64(r.completedSteps), draw + 1);
        }
        return ILangevinDynamicsIntegrator(_modules.integrator).begin(
            _readVector(r, r.activeBuffer, r.cursor, 0), _readVector(r, r.activeBuffer, r.cursor, 3),
            _readVector(r, r.activeBuffer, r.cursor, 6), _mass(r, r.cursor), r.dt, r.friction, r.kT, normal);
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = ILangevinDynamicsIntegrator(_modules.integrator).finish(
            _readVector(r, next, r.cursor, 3), _readVector(r, next, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) { _requireFinite(velocity[d]); words[d] = _encode(velocity[d]); }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 3), words);
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = ILangevinDynamicsPairKernel(_modules.bond).evaluate(
            zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            ILangevinDynamicsAngleKernel(_modules.angle).evaluate(_bondedDisplacement(r, buffer, a.b, a.a),
                zero, _bondedDisplacement(r, buffer, a.b, a.c), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(_modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            ILangevinDynamicsTorsionKernel(_modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, neighborList.pairIndexAt(r.stateNamespace, index));
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = ILangevinNonbonded(_modules.nonbonded).evaluate(
            displacement, p.sigma, p.epsilon, p.chargeProduct,
            r.prefactor, r.switchDistance, r.cutoff, p.kind == 2);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory)
    {
        return ILangevinGeometry(_modules.geometry).displacement(
            _readVector(r, buffer, a, 0), _readVector(r, buffer, b, 0), r.box);
    }

    function _bondedDisplacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory displacement)
    {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(Run storage r, bytes16[3] memory displacement) private view {
        FloatMath m = FloatMath(_modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) == 0) revert InvalidInput();
        }
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(_modules.math).compare(a.theta0, ILangevinDynamicsElementary(_modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(_modules.math);
        bytes16 twoPi = ILangevinDynamicsElementary(_modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _parameters(Run storage r, uint256 atom) private view returns (ParticleParameters memory p) {
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon);
    }

    function _exception(Run storage r, uint256 index) private view returns (Pair memory p) {
        ILangevinDynamicsData data = ILangevinDynamicsData(_modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readExceptionWord(r.datasetId, offset + 1), r.atomCount);
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(data.readExceptionWord(r.datasetId, offset + 5));
        if (p.kind == 1) {
            if (p.sigma != bytes16(0) || p.epsilon != bytes16(0) || p.chargeProduct != bytes16(0)) revert InvalidInput();
        } else { _requirePositive(p.sigma); _requireNonnegative(p.epsilon); }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
        neighborList.setException(r.stateNamespace, p.a, p.b, uint8(p.kind));
    }

    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][uint256(p.a) * r.atomCount + p.b];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(_modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        p.chargeProduct = m.mul(a.charge, b.charge);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(ILangevinDynamicsData(_modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(_modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(_modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[14] memory addresses = _moduleAddresses(_modules);
        for (uint256 i; i < 14; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash || address(neighborList).codehash != neighborCodeHash)
            revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(_modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 14; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(neighborList), neighborCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[14] memory) {
        return [m.registry, m.dataset, m.math, m.integrator, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary, m.geometry, m.nonbonded, m.scalar, m.random];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/MolecularSimulationPipeli.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";
import {AlchemicalHamiltonianEvaluator,IProductionWordState} from "./AlchemicalHamiltonianEvaluator.sol";
import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {LangevinBAOABKernel} from "../kernels/LangevinBAOABKernel.sol";
import {CounterRandom} from "../kernels/CounterRandom.sol";
import {ReducedPotentialCollector} from "../analysis/ReducedPotentialCollector.sol";
import {TimeSeriesDiagnostics} from "../analysis/TimeSeriesDiagnostics.sol";
import {MBARFreeEnergyEstimator} from "../analysis/MBARFreeEnergyEstimator.sol";

/// @notice Authenticated NVT dynamics -> frozen cross-state energies -> analysis.
/// @dev One supported unconstrained, fixed-box hybrid Hamiltonian is used for
///      both sampled forces and every cross-state energy. No EOA supplies a
///      force/energy/sample, and partial positions never become committed state.
///      Full molecular preparation, ensemble validation and campaign feasibility
///      remain scientific requirements; this contract cannot certify them.
contract MolecularSimulationPipeline {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged(); error NotConfigured();
    enum Stage { Missing, Loading, InitialEvaluation, InitialForces, Ready, Drift, StepEvaluation, StepForces, CrossStart, CrossEvaluation, Record, Complete, HandedOff, Copying }
    enum AnalysisStage { Collecting, FlushRaw, Chronology, Selecting, Selected, Analyzing }
    struct Modules { address registry; address topology; address math; address integrator; address random; }
    struct Policy {
        bytes32 protocol; bytes32 topology; bytes32 leg; bytes32 seed; bytes32 stream;
        uint32 replica; bytes16 dt; bytes16 friction; bytes16 kT;
        uint64 equilibrationSteps; uint64 stride; uint32 samplesPerState;
        uint16 maxLag; uint32 minimumChronologySamples;
        bytes16 mbarTolerance; bytes16 overlapThreshold; bytes16 minimumESS; bytes16 normalizationTolerance;
        uint32 maxMbarIterations;
    }
    struct Campaign {
        Policy policy; bytes32 commitment; bytes32 topologyCommitment; uint8 states; uint8 completedWindows;
        AnalysisStage analysisStage; uint32 flushCursor; uint8 selectionState; uint32 selectionOrdinal;
        uint32 selectedExpected; uint32 selectedCount; uint256 analysisId;
        uint32[16] thinning; uint256[16] activeRuns; uint32[16] windowSamples;
    }
    struct Run {
        bytes32 campaign; uint8 state; Stage stage; uint32 cursor; uint64 step; uint256 parent;
        bytes32 commitment; bytes32 workingNamespace; bytes32 committedSnapshot; bytes32 sourceSnapshot;
        uint64 snapshotSerial; uint256 evaluation; uint256 sampledEvaluation; bytes32 sampledEvaluationCommitment; uint8 crossState; bytes16 energy;
        bytes16[16] sampleEnergies; bytes32 evaluationDigest; uint256[] evaluationHistory;
    }
    struct Sample {
        bytes32 snapshot; bytes32 snapshotCommitment; bytes32 runCommitment; bytes32 evaluationDigest;
        uint64 step; uint256 run; bytes16[16] energies;
    }
    address public immutable owner;
    Modules public modules; bytes32[5] public moduleHashes; bytes32 public immutable coreConfigurationHash;
    IProductionWordState public statePage; AlchemicalHamiltonianEvaluator public hamiltonian;
    ReducedPotentialCollector public collector; TimeSeriesDiagnostics public chronology; MBARFreeEnergyEstimator public estimator;
    bytes32[5] public boundHashes;
    uint256 public nextRun = 1; uint256 public constant MAX_WORK = 8;
    mapping(bytes32 => Campaign) private campaigns;
    mapping(uint256 => Run) private runs;
    mapping(bytes32 => mapping(uint32 => Sample)) private samples;
    event CampaignCreated(bytes32 indexed id, bytes32 commitment);
    event WindowStarted(bytes32 indexed campaign,uint8 state,uint256 run,bytes32 commitment);
    event CheckpointCommitted(uint256 indexed run,uint64 step,bytes32 snapshot,bytes32 snapshotCommitment);
    event WindowContinued(uint256 indexed parent,uint256 indexed child,bytes32 checkpoint);
    event MolecularSampleRecorded(bytes32 indexed campaign,uint32 sample,uint8 state,uint64 step,bytes32 snapshot,bytes32 evaluationDigest);

    constructor(address owner_,Modules memory m) {
        if(owner_==address(0))revert InvalidInput();owner=owner_;modules=m;address[5] memory addresses=_addresses(m);
        for(uint256 i;i<5;++i){if(addresses[i].code.length==0)revert InvalidInput();moduleHashes[i]=addresses[i].codehash;}
        if(address(AlchemicalTopologyCatalog(m.topology).numericalMath())!=m.math
            ||address(LangevinBAOABKernel(m.integrator).numericalMath())!=m.math
            ||address(CounterRandom(m.random).numericalMath())!=m.math
            ||address(LangevinBAOABKernel(m.integrator).scalarMath())!=address(CounterRandom(m.random).scalarMath()))revert InvalidInput();
        coreConfigurationHash=keccak256(abi.encode(m,moduleHashes));
    }
    function bind(address page,address evaluator,address evaluatorOutput,address collector_,address chronology_,address estimator_)external{
        if(msg.sender!=owner)revert Unauthorized();if(address(statePage)!=address(0))revert WrongStage();
        address[5] memory addresses=[page,evaluator,collector_,chronology_,estimator_];for(uint256 i;i<5;++i)if(addresses[i].code.length==0)revert InvalidInput();
        if(IProductionWordState(page).writer()!=address(this)||AlchemicalHamiltonianEvaluator(evaluator).owner()!=address(this)
            ||ReducedPotentialCollector(collector_).writer()!=address(this)||TimeSeriesDiagnostics(chronology_).writer()!=address(this)
            ||address(ReducedPotentialCollector(collector_).numericalMath())!=modules.math
            ||address(TimeSeriesDiagnostics(chronology_).numericalMath())!=modules.math
            ||address(MBARFreeEnergyEstimator(estimator_).collector())!=collector_)revert InvalidInput();
        AlchemicalHamiltonianEvaluator.Modules memory hm=AlchemicalHamiltonianEvaluator(evaluator).moduleConfiguration();
        if(hm.topology!=modules.topology||hm.math!=modules.math)revert InvalidInput();
        AlchemicalHamiltonianEvaluator(evaluator).bindOutputPage(evaluatorOutput);
        statePage=IProductionWordState(page);hamiltonian=AlchemicalHamiltonianEvaluator(evaluator);
        collector=ReducedPotentialCollector(collector_);chronology=TimeSeriesDiagnostics(chronology_);estimator=MBARFreeEnergyEstimator(estimator_);
        for(uint256 i;i<5;++i)boundHashes[i]=addresses[i].codehash;
    }
    function createCampaign(bytes32 id,Policy calldata policy)external{
        if(msg.sender!=owner)revert Unauthorized();bytes32 manifest=_dependencies(policy.protocol);
        if(id==bytes32(0)||campaigns[id].commitment!=bytes32(0)||policy.leg==bytes32(0)||policy.seed==bytes32(0)||policy.stream==bytes32(0)
            ||policy.replica>0x00ffffff||policy.samplesPerState<4||policy.minimumChronologySamples<4||policy.minimumChronologySamples>policy.samplesPerState
            ||policy.maxLag==0||policy.maxLag%2!=1||policy.maxLag>255||policy.maxLag>=policy.samplesPerState||policy.stride==0||policy.maxMbarIterations==0||policy.maxMbarIterations>10000)revert InvalidInput();
        _positive(policy.dt);_positive(policy.kT);_nonnegative(policy.friction);
        LangevinBAOABKernel(modules.integrator).coefficients(FloatMath(modules.math).fromUInt(1),policy.dt,policy.friction,policy.kT);
        uint8 states=AlchemicalTopologyCatalog(modules.topology).stateCount(policy.topology);
        if(uint256(states)*policy.samplesPerState>collector.MAX_SAMPLES()
            ||uint256(policy.equilibrationSteps)+uint256(policy.stride)*policy.samplesPerState>type(uint64).max)revert InvalidInput();
        Campaign storage c=campaigns[id];c.policy=policy;c.states=states;c.topologyCommitment=AlchemicalTopologyCatalog(modules.topology).assertTopology(policy.topology);
        c.commitment=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-CAMPAIGN-v1"),block.chainid,address(this),id,manifest,coreConfigurationHash,boundHashes,policy,c.topologyCommitment));
        collector.createSeries(_rawSeries(id),_collectionPolicy(c,uint32(states)*policy.samplesPerState));
        emit CampaignCreated(id,c.commitment);
    }
    function startWindow(bytes32 campaign,uint8 state)external returns(uint256 id){
        Campaign storage c=_campaign(campaign);_dependencies(c.policy.protocol);
        if(c.analysisStage!=AnalysisStage.Collecting||state>=c.states||c.activeRuns[state]!=0)revert InvalidInput();
        id=_newRun(campaign,state,0);c.activeRuns[state]=id;
        TimeSeriesDiagnostics.Configuration memory tc;
        tc.protocolHash=c.policy.protocol;tc.runHash=c.commitment;tc.replicaHash=keccak256(abi.encode(c.policy.seed,c.policy.stream,c.policy.replica,state));
        tc.observableHash=keccak256("ORVIA.Molecular.SampledPotentialEnergy.v1");tc.state=state;tc.expectedSamples=c.policy.samplesPerState;
        tc.firstStep=c.policy.equilibrationSteps+c.policy.stride;tc.stride=c.policy.stride;tc.maxLag=c.policy.maxLag;tc.minimumSamples=c.policy.minimumChronologySamples;
        chronology.createSeries(_chronologySeries(campaign,state),tc);
    }
    function continueWindow(uint256 parent)external returns(uint256 child){
        if(msg.sender!=owner)revert Unauthorized();Run storage previous=_run(parent);Campaign storage c=_campaign(previous.campaign);_dependencies(c.policy.protocol);
        if(previous.stage!=Stage.Ready||c.activeRuns[previous.state]!=parent)revert WrongStage();
        child=_newRun(previous.campaign,previous.state,parent);Run storage r=runs[child];
        r.step=previous.step;r.sourceSnapshot=previous.committedSnapshot;r.committedSnapshot=previous.committedSnapshot;r.energy=previous.energy;
        r.stage=Stage.Copying;previous.stage=Stage.HandedOff;c.activeRuns[previous.state]=child;
        emit WindowContinued(parent,child,previous.committedSnapshot);
    }
    function advance(uint256 id,uint256 work)external returns(uint256 processed,bool complete){
        if(work==0||work>MAX_WORK)revert InvalidInput();Run storage r=_run(id);Campaign storage c=_campaign(r.campaign);_dependencies(c.policy.protocol);
        if(r.stage==Stage.Complete||r.stage==Stage.HandedOff||c.activeRuns[r.state]!=id)revert WrongStage();
        AlchemicalTopologyCatalog.Definition memory d=AlchemicalTopologyCatalog(modules.topology).definition(c.policy.topology);
        while(processed<work&&r.stage!=Stage.Complete){
            if(r.stage==Stage.InitialEvaluation||r.stage==Stage.StepEvaluation||r.stage==Stage.CrossEvaluation){
                (uint256 used,bool finished)=hamiltonian.advance(r.evaluation,work-processed);processed+=used;
                if(finished)_evaluationFinished(r);
            }else{_one(id,r,c,d);++processed;}
        }
        complete=r.stage==Stage.Complete;
    }
    function _one(uint256 id,Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        if(r.stage==Stage.Loading){
            bytes32[] memory words=new bytes32[](9);uint64 atom=r.cursor;
            for(uint64 k;k<3;++k){words[k]=AlchemicalTopologyCatalog(modules.topology).word(d.positions,atom*3+k);words[k+3]=AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,atom*4+k+1);}
            statePage.writeWords(r.workingNamespace,uint256(atom)*9,words);
            if(++r.cursor==d.atoms){r.cursor=0;bytes32 snapshot=_snapshot(r,id,1);_beginEvaluation(r,snapshot,r.state);r.stage=Stage.InitialEvaluation;}
        }else if(r.stage==Stage.Copying){
            bytes32[] memory words=new bytes32[](9);for(uint256 k;k<9;++k)words[k]=statePage.readWord(r.sourceSnapshot,uint256(r.cursor)*9+k);
            statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9,words);
            if(++r.cursor==d.atoms){statePage.writeWord(r.workingNamespace,uint256(d.atoms)*9,_encode(r.energy));r.cursor=0;r.committedSnapshot=_snapshot(r,id,4);r.stage=Stage.Ready;}
        }else if(r.stage==Stage.InitialForces||r.stage==Stage.StepForces){
            _importForce(r,c,d);
            if(++r.cursor==d.atoms){
                r.cursor=0;statePage.writeWord(r.workingNamespace,uint256(d.atoms)*9,_encode(r.energy));
                if(r.stage==Stage.StepForces)++r.step;
                r.committedSnapshot=_snapshot(r,id,2);(,,,,bytes32 sc)=statePage.snapshotInfo(r.committedSnapshot);emit CheckpointCommitted(id,r.step,r.committedSnapshot,sc);
                if(r.step>c.policy.equilibrationSteps&&(r.step-c.policy.equilibrationSteps)%c.policy.stride==0){r.crossState=0;r.evaluationDigest=bytes32(0);r.stage=Stage.CrossStart;}
                else r.stage=Stage.Ready;
            }
        }else if(r.stage==Stage.Ready){r.cursor=0;r.stage=Stage.Drift;
        }else if(r.stage==Stage.Drift){
            _drift(r,c,d);
            if(++r.cursor==d.atoms){r.cursor=0;bytes32 snapshot=_snapshot(r,id,3);_beginEvaluation(r,snapshot,r.state);r.stage=Stage.StepEvaluation;}
        }else if(r.stage==Stage.CrossStart){
            if(r.crossState==c.states)r.stage=Stage.Record;
            else if(r.crossState==r.state){r.sampleEnergies[r.crossState]=r.energy;r.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.state,r.sampledEvaluation,r.sampledEvaluationCommitment));++r.crossState;}
            else{_beginEvaluation(r,r.committedSnapshot,r.crossState);r.stage=Stage.CrossEvaluation;}
        }else if(r.stage==Stage.Record){_record(id,r,c);
        }else revert WrongStage();
    }
    function _newRun(bytes32 campaign,uint8 state,uint256 parent)private returns(uint256 id){
        Campaign storage c=campaigns[campaign];AlchemicalTopologyCatalog.Definition memory d=AlchemicalTopologyCatalog(modules.topology).definition(c.policy.topology);
        id=nextRun++;Run storage r=runs[id];r.campaign=campaign;r.state=state;r.parent=parent;r.stage=Stage.Loading;
        r.workingNamespace=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-WORK-v1"),block.chainid,address(this),id));
        bytes32 lineage=parent==0?bytes32(0):keccak256(abi.encode(runs[parent].commitment,runs[parent].committedSnapshot,runs[parent].step));
        r.commitment=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-RUN-v1"),block.chainid,address(this),id,c.commitment,state,parent,lineage,r.workingNamespace));
        statePage.createNamespace(r.workingNamespace,d.atoms*9+1);emit WindowStarted(campaign,state,id,r.commitment);
    }
    function _drift(Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        bytes16[3] memory normal;
        if(c.policy.friction!=bytes16(0)){
            uint64 draw=uint64(r.cursor)*2;uint32 replica=(c.policy.replica<<8)|r.state;
            (normal[0],normal[1])=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw);
            (normal[2],)=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw+1);
        }
        bytes16 mass=_decode(AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,uint64(r.cursor)*4));
        (bytes16[3] memory position,bytes16[3] memory velocity)=LangevinBAOABKernel(modules.integrator).begin(
            _vector(r.committedSnapshot,r.cursor,0),_vector(r.committedSnapshot,r.cursor,3),_vector(r.committedSnapshot,r.cursor,6),mass,c.policy.dt,c.policy.friction,c.policy.kT,normal);
        bytes32[] memory words=new bytes32[](9);for(uint256 k;k<3;++k){words[k]=_encode(position[k]);words[k+3]=_encode(velocity[k]);}
        statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9,words);
    }
    function _importForce(Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        bytes16[3] memory force=hamiltonian.forceAt(r.evaluation,r.cursor);bytes32[] memory words=new bytes32[](6);
        bytes16[3] memory velocity=_vector(r.workingNamespace,r.cursor,3);
        if(r.stage==Stage.StepForces)velocity=LangevinBAOABKernel(modules.integrator).finish(velocity,force,
            _decode(AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,uint64(r.cursor)*4)),c.policy.dt);
        for(uint256 k;k<3;++k){words[k]=_encode(velocity[k]);words[k+3]=_encode(force[k]);}
        statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9+3,words);
    }
    function _beginEvaluation(Run storage r,bytes32 snapshot,uint8 state)private{
        Policy storage p=campaigns[r.campaign].policy;
        r.evaluation=hamiltonian.registerEvaluation(p.protocol,p.topology,state,address(statePage),snapshot,0,9);
        r.evaluationHistory.push(r.evaluation);
    }
    function _evaluationFinished(Run storage r)private{
        (,bytes32 commitment,bytes16 energy)=hamiltonian.result(r.evaluation);
        if(r.stage==Stage.CrossEvaluation){r.sampleEnergies[r.crossState]=energy;r.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.crossState,r.evaluation,commitment));++r.crossState;r.stage=Stage.CrossStart;}
        else{r.energy=energy;r.sampledEvaluation=r.evaluation;r.sampledEvaluationCommitment=commitment;r.cursor=0;r.stage=r.stage==Stage.InitialEvaluation?Stage.InitialForces:Stage.StepForces;}
    }
    function _record(uint256 id,Run storage r,Campaign storage c)private{
        uint32 ordinal=c.windowSamples[r.state];if(ordinal>=c.policy.samplesPerState||r.step!=c.policy.equilibrationSteps+uint64(ordinal+1)*c.policy.stride)revert InvalidInput();
        uint32 index=uint32(r.state)*c.policy.samplesPerState+ordinal;Sample storage sample=samples[r.campaign][index];
        if(sample.snapshot!=bytes32(0))revert WrongStage();(,,,,bytes32 sc)=statePage.snapshotInfo(r.committedSnapshot);
        sample.snapshot=r.committedSnapshot;sample.snapshotCommitment=sc;sample.runCommitment=r.commitment;sample.run=id;sample.step=r.step;sample.energies=r.sampleEnergies;
        sample.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.state,r.energy,sc));
        bytes16[] memory observable=new bytes16[](1);observable[0]=r.energy;chronology.append(_chronologySeries(r.campaign,r.state),r.step,observable);
        ++c.windowSamples[r.state];emit MolecularSampleRecorded(r.campaign,index,r.state,r.step,r.committedSnapshot,sample.evaluationDigest);
        if(c.windowSamples[r.state]==c.policy.samplesPerState){
            chronology.seal(_chronologySeries(r.campaign,r.state));r.stage=Stage.Complete;++c.completedWindows;
            if(c.completedWindows==c.states)c.analysisStage=AnalysisStage.FlushRaw;
        }else r.stage=Stage.Ready;
    }
    /// @notice Materialize a canonical state-major matrix, independent of window interleaving.
    function flushRaw(bytes32 id,uint256 work)external returns(uint256 processed,bool complete){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.FlushRaw||work==0||work>MAX_WORK)revert WrongStage();
        uint32 count=uint32(c.states)*c.policy.samplesPerState;
        while(processed<work&&c.flushCursor<count){uint32 index=c.flushCursor;uint8 state=uint8(index/c.policy.samplesPerState);_append(id,_rawSeries(id),index,state);++c.flushCursor;++processed;}
        complete=c.flushCursor==count;if(complete){collector.seal(_rawSeries(id));c.analysisStage=AnalysisStage.Chronology;}
    }
    /// @notice Frozen rule: choose every ceil(g)th chronological sample per state.
    /// @dev Correlation estimates are finite-sample model diagnostics, not a proof
    ///      that every slow molecular observable has equilibrated or decorrelated.
    function beginSelection(bytes32 id)external{
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Chronology)revert WrongStage();
        uint32 total;FloatMath m=FloatMath(modules.math);
        for(uint8 k;k<c.states;++k){
            ( ,bool valid)=chronology.assertCompleted(_chronologySeries(id,k));if(!valid)revert WrongStage();
            TimeSeriesDiagnostics.Summary memory s=chronology.summary(_chronologySeries(id,k));
            if(m.compare(s.effectiveSamples,c.policy.minimumESS)<0)revert WrongStage();
            uint32 thin=_ceil(s.g,c.policy.samplesPerState);uint32 retained=(c.policy.samplesPerState-1)/thin+1;
            if(m.compare(m.fromUInt(retained),c.policy.minimumESS)<0)revert WrongStage();c.thinning[k]=thin;total+=retained;
        }
        c.selectedExpected=total;collector.createSeries(_selectedSeries(id),_collectionPolicy(c,total));c.analysisStage=AnalysisStage.Selecting;
    }
    function advanceSelection(bytes32 id,uint256 work)external returns(uint256 processed,bool complete){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Selecting||work==0||work>MAX_WORK)revert WrongStage();
        while(processed<work&&c.selectionState<c.states){
            uint32 ordinal=c.selectionOrdinal*c.thinning[c.selectionState];
            _append(id,_selectedSeries(id),uint32(c.selectionState)*c.policy.samplesPerState+ordinal,c.selectionState);++c.selectedCount;++c.selectionOrdinal;++processed;
            if(uint256(c.selectionOrdinal)*c.thinning[c.selectionState]>=c.policy.samplesPerState){++c.selectionState;c.selectionOrdinal=0;}
        }
        complete=c.selectionState==c.states;if(complete){if(c.selectedCount!=c.selectedExpected)revert InvalidInput();collector.seal(_selectedSeries(id));c.analysisStage=AnalysisStage.Selected;}
    }
    function startAnalysis(bytes32 id)external returns(uint256 analysisId){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Selected)revert WrongStage();
        analysisId=estimator.createAnalysis(_selectedSeries(id),c.policy.mbarTolerance,c.policy.maxMbarIterations);c.analysisId=analysisId;c.analysisStage=AnalysisStage.Analyzing;
    }
    function _append(bytes32 id,bytes32 series,uint32 index,uint8 state)private{
        Campaign storage c=campaigns[id];Sample storage sample=samples[id][index];if(sample.snapshot==bytes32(0))revert WrongStage();
        (,,,,bytes32 sc)=statePage.snapshotInfo(sample.snapshot);if(sc!=sample.snapshotCommitment)revert DependencyChanged();
        bytes16[] memory energies=new bytes16[](c.states);for(uint256 k;k<c.states;++k)energies[k]=sample.energies[k];
        collector.appendSample(series,state,sample.step,energies);
    }
    function _collectionPolicy(Campaign storage c,uint32 expected)private view returns(ReducedPotentialCollector.Configuration memory p){
        p.protocolHash=c.policy.protocol;p.runHash=c.commitment;p.leg=c.policy.leg;p.repeatSeed=c.policy.seed;p.stateCount=c.states;p.expectedSamples=expected;p.kT=c.policy.kT;
        p.stride=c.policy.stride;p.equilibrationEnd=c.policy.equilibrationSteps;p.mbarTolerance=c.policy.mbarTolerance;p.overlapThreshold=c.policy.overlapThreshold;p.minimumESS=c.policy.minimumESS;p.normalizationTolerance=c.policy.normalizationTolerance;
    }
    function _snapshot(Run storage r,uint256 id,uint8 kind)private returns(bytes32 snapshot){
        snapshot=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-SNAPSHOT-v1"),block.chainid,address(this),id,++r.snapshotSerial,kind,r.step));statePage.snapshotNamespace(r.workingNamespace,snapshot);
    }
    function _vector(bytes32 ns,uint32 atom,uint32 offset)private view returns(bytes16[3] memory vector){for(uint256 k;k<3;++k)vector[k]=_decode(statePage.readWord(ns,uint256(atom)*9+offset+k));}
    function _ceil(bytes16 g,uint32 maximum)private view returns(uint32){FloatMath m=FloatMath(modules.math);if(m.compare(g,m.fromUInt(maximum))>0)revert InvalidInput();uint32 low=1;uint32 high=maximum;while(low<high){uint32 mid=low+(high-low)/2;if(m.compare(m.fromUInt(mid),g)<0)low=mid+1;else high=mid;}return low;}
    function campaignInfo(bytes32 id)external view returns(bytes32 commitment,AnalysisStage stage,uint8 states,uint8 completed,uint256 analysisId,uint32 selectedExpected){Campaign storage c=_campaign(id);return(c.commitment,c.analysisStage,c.states,c.completedWindows,c.analysisId,c.selectedExpected);}
    function runInfo(uint256 id)external view returns(bytes32 campaign,uint8 state,Stage stage,uint64 step,uint32 cursor,uint256 parent,bytes32 commitment,bytes32 checkpoint){Run storage r=_run(id);return(r.campaign,r.state,r.stage,r.step,r.cursor,r.parent,r.commitment,r.committedSnapshot);}
    function stateAt(uint256 id,uint32 atom)external view returns(bytes16[3] memory position,bytes16[3] memory velocity,bytes16[3] memory force){Run storage r=_run(id);if(r.committedSnapshot==bytes32(0)||atom>=AlchemicalTopologyCatalog(modules.topology).definition(campaigns[r.campaign].policy.topology).atoms)revert WrongStage();return(_vector(r.committedSnapshot,atom,0),_vector(r.committedSnapshot,atom,3),_vector(r.committedSnapshot,atom,6));}
    function sampleInfo(bytes32 id,uint32 index)external view returns(bytes32 snapshot,bytes32 snapshotCommitment,bytes32 runCommitment,bytes32 evaluationDigest,uint64 step,uint256 run){Sample storage s=samples[id][index];if(s.snapshot==bytes32(0))revert InvalidInput();return(s.snapshot,s.snapshotCommitment,s.runCommitment,s.evaluationDigest,s.step,s.run);}
    function sampleEnergy(bytes32 id,uint32 sample,uint8 state)external view returns(bytes16){if(state>=_campaign(id).states||samples[id][sample].snapshot==bytes32(0))revert InvalidInput();return samples[id][sample].energies[state];}
    function evaluationHistory(uint256 id,uint256 index)external view returns(uint256){return _run(id).evaluationHistory[index];}
    function chronologySeries(bytes32 id,uint8 state)external pure returns(bytes32){return _chronologySeries(id,state);}
    function rawSeries(bytes32 id)external pure returns(bytes32){return _rawSeries(id);}
    function selectedSeries(bytes32 id)external pure returns(bytes32){return _selectedSeries(id);}
    function _rawSeries(bytes32 id)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-RAW-v1"),id));}
    function _selectedSeries(bytes32 id)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-SELECTED-v1"),id));}
    function _chronologySeries(bytes32 id,uint8 state)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-TIME-v1"),id,state));}
    function _dependencies(bytes32 protocol)private view returns(bytes32 manifest){
        if(address(statePage)==address(0))revert NotConfigured();ExperimentRegistry registry=ExperimentRegistry(modules.registry);manifest=registry.assertProtocol(protocol);address[5] memory a=_addresses(modules);
        for(uint256 i;i<5;++i){if(a[i].codehash!=moduleHashes[i])revert DependencyChanged();if(i!=0)registry.assertModule(protocol,a[i],moduleHashes[i]);}
        address[5] memory b=[address(statePage),address(hamiltonian),address(collector),address(chronology),address(estimator)];
        for(uint256 i;i<5;++i){if(b[i].codehash!=boundHashes[i])revert DependencyChanged();registry.assertModule(protocol,b[i],boundHashes[i]);}
        registry.assertModule(protocol,address(this),address(this).codehash);
    }
    function _addresses(Modules memory m)private pure returns(address[5] memory){return[m.registry,m.topology,m.math,m.integrator,m.random];}
    function _campaign(bytes32 id)private view returns(Campaign storage c){c=campaigns[id];if(c.commitment==bytes32(0))revert InvalidInput();}
    function _run(uint256 id)private view returns(Run storage r){r=runs[id];if(r.stage==Stage.Missing)revert InvalidInput();}
    function _positive(bytes16 x)private view{if(!FloatMath(modules.math).isFinite(x)||FloatMath(modules.math).compare(x,bytes16(0))<=0)revert InvalidInput();}
    function _nonnegative(bytes16 x)private view{if(!FloatMath(modules.math).isFinite(x)||FloatMath(modules.math).compare(x,bytes16(0))<0)revert InvalidInput();}
    function _decode(bytes32 word)private pure returns(bytes16 value){if(uint256(word)>>128!=0)revert InvalidInput();value=bytes16(uint128(uint256(word)));if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();}
    function _encode(bytes16 value)private pure returns(bytes32){if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();return bytes32(uint256(uint128(value)));}
}

contracts/core/NeighborDynamicsCoordinat.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {NeighborList} from "./NeighborList.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {InlineNonbondedKernel} from "../kernels/InlineNonbondedKernel.sol";

interface INeighborDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function periodicInfo(bytes32 id) external view returns (bytes16[3] memory, bytes16, bytes16, bytes16, uint32);
}
interface INeighborDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface INeighborDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface INeighborDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface INeighborDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface INeighborDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface INeighborDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}
interface INeighborDynamicsIntegrator {
    function drift(bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextPosition, bytes16[3] memory halfVelocity);
    function kick(bytes16[3] calldata halfVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity);
}

interface INeighborGeometry {
    function displacement(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata box)
        external view returns (bytes16[3] memory);
    function validateBox(bytes16[3] calldata box, bytes16 cutoff) external view;
}
interface INeighborNonbonded {
    function KERNEL_ID() external view returns (bytes32);
    function ljKernel() external view returns (address);
    function coulombKernel() external view returns (address);
    function evaluate(bytes16[3] calldata displacement, bytes16 sigma, bytes16 epsilon,
        bytes16 chargeProduct, bytes16 prefactor, bytes16 switchDistance, bytes16 cutoff, bool exception)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}

/// @notice Bounded, double-buffered velocity Verlet with orthorhombic minimum images.
/// @dev Resumable Verlet lists preserve the periodic cutoff Hamiltonian and
///      lexicographic accumulation order, including all direct exceptions.
///      No Ewald/PME, thermostat or free-energy estimator is supplied here.
contract NeighborDynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;
    /// @notice Explicit admission policy; included implicitly in the code-bound module configuration.
    bytes32 public immutable nonbondedPolicy;
    bytes32 public constant EXTERNAL_NONBONDED_POLICY = keccak256("ORVIA.Neighbor.Nonbonded.External.v1");
    bytes32 public constant INLINE_NONBONDED_POLICY = keccak256("ORVIA.Neighbor.Nonbonded.PinnedInline.v1");

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
    }
    Modules public modules;
    bytes32[12] public moduleCodeHashes;
    WorkingStatePage public statePage;
    NeighborList public neighborList;
    bytes32 public neighborCodeHash;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingExceptions, PreparingInitial, InitialBonds, InitialAngles, InitialTorsions, InitialPairs,
        Drift, PreparingNext, NextBonds, NextAngles, NextTorsions, NextPairs, Kick, Completed
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        bytes16 skin;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; }
    struct ParticleParameters { bytes16 sigma; bytes16 epsilon; bytes16 charge; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event StepCommitted(uint256 indexed experimentId, uint256 completedSteps, uint256 activeBuffer);

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = modules_;
        address[12] memory addresses = _moduleAddresses(modules_);
        bytes32[12] memory hashes;
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 11; ++i) {
            if (INeighborDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (INeighborDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            INeighborDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        if (modules_.nonbonded.codehash == keccak256(type(InlineNonbondedKernel).runtimeCode)) {
            // Inline arithmetic has no external math/LJ/Coulomb dependency getters.
            // Admit the exact compiled runtime, not a self-reported implementation ID.
            // The remaining force/geometry/integration path must use the identical
            // pinned FloatMath implementation retained inside that runtime.
            if (modules_.math.codehash != keccak256(type(FloatMath).runtimeCode) ||
                FloatMath(modules_.math).IMPLEMENTATION_ID() !=
                InlineNonbondedKernel(modules_.nonbonded).ARITHMETIC_IMPLEMENTATION_ID()) revert InvalidConfiguration();
            nonbondedPolicy = INLINE_NONBONDED_POLICY;
        } else {
            if (INeighborNonbonded(modules_.nonbonded).KERNEL_ID() !=
                    keccak256("ORVIA.SwitchedNonbondedKernel.v0.4.ConductingRF") ||
                INeighborDynamicsMathIdentity(modules_.nonbonded).numericalMath() != modules_.math ||
                INeighborNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
                INeighborNonbonded(modules_.nonbonded).coulombKernel() != modules_.coulomb) revert InvalidConfiguration();
            nonbondedPolicy = EXTERNAL_NONBONDED_POLICY;
        }
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function bindWorkingPage(address page, address neighbors) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this) || neighbors.code.length == 0)
            revert InvalidConfiguration();
        NeighborList list = NeighborList(neighbors);
        if (list.writer() != address(this) || address(list.statePage()) != page ||
            address(list.numericalMath()) != modules.math || address(list.geometry()) != modules.geometry) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        neighborList = list; neighborCodeHash = neighbors.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash, neighbors, neighbors.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, bytes16 dt, uint32 steps, bytes16 skin)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(dt); _requirePositive(skin);
        if (steps == 0 || steps > MAX_STEPS) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = INeighborDynamicsData(modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = INeighborDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 ||
            r.pairCount != uint256(r.atomCount) * (r.atomCount - 1) / 2) revert InvalidInput();
        (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount) =
            INeighborDynamicsData(modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount) revert InvalidInput();
        _requirePositive(r.switchDistance); _requirePositive(r.cutoff); _requireNonnegative(r.prefactor);
        if (FloatMath(modules.math).compare(r.switchDistance, r.cutoff) >= 0) revert InvalidInput();
        INeighborGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = dt; r.skin = skin;
        r.targetSteps = steps;
        r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-NEIGHBOR-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-NEIGHBOR-RUN-v1"), block.chainid, address(this),
            experimentId, manifest, datasetId, datasetCommitment, configurationHash, dt, steps, skin, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        neighborList.registerList(r.stateNamespace, r.atomCount, r.box, r.cutoff, skin);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (INeighborDynamicsData(modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                (uint256 used, bool ready) = neighborList.advance(r.stateNamespace, workLimit - processed);
                processed += used;
                if (ready) { r.status = Status(uint8(r.status) + 1); r.cursor = 0; }
            } else {
                _process(r);
                ++processed;
                ++r.cursor;
                if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
            }
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 completedSteps, uint256 targetSteps, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }

    function stateAt(uint256 experimentId, uint256 atom) external view returns (
        bytes16[3] memory position, bytes16[3] memory velocity, bytes16[3] memory force
    ) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(uint256 experimentId) external view returns (
        bytes16 dt, uint32 bondCount, uint32 angleCount, uint32 torsionCount, uint32 pairCount, bytes32 datasetCommitment
    ) {
        Run storage r = _get(experimentId);
        return (r.dt, r.bondCount, r.angleCount, r.torsionCount, r.pairCount, r.datasetCommitment);
    }

    function neighborParameters(uint256 experimentId) external view returns (bytes16 skin, address list) {
        return (_get(experimentId).skin, address(neighborList));
    }

    function periodicParameters(uint256 experimentId) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Run storage r = _get(experimentId);
        return (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount);
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions) _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status <= Status.NextPairs) _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (r.status == Status.Kick) {
            r.activeBuffer = 1 - r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace);
                r.status = Status.Completed;
                return;
            }
            r.status = Status.Drift;
        } else r.status = Status(uint8(r.status) + 1);
        r.cursor = 0;
        // Preparation snapshots remain fixed until the complete list is ready.
        while (true) {
            if (r.status == Status.PreparingInitial || r.status == Status.PreparingNext) {
                neighborList.beginEvaluation(r.stateNamespace,
                    r.status == Status.PreparingInitial ? r.activeBuffer : 1 - r.activeBuffer);
                return;
            }
            if (_stageCount(r) != 0) return;
            r.status = Status(uint8(r.status) + 1);
        }
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (r.status == Status.Loading || r.status == Status.Drift || r.status == Status.Kick) return r.atomCount;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        (,,, uint32 candidates,,,,) = neighborList.listInfo(r.stateNamespace);
        return candidates;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingExceptions) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status) - 7;
        if (status >= Status.NextBonds && status <= Status.NextPairs) return uint8(status) - 13;
        revert InvalidInput();
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        _parameters(r, atom);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            words[d + 3] = _encode(_decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)));
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
        (bytes16[3] memory position, bytes16[3] memory halfVelocity) = INeighborDynamicsIntegrator(modules.integrator).drift(
            _readVector(r, r.activeBuffer, r.cursor, 0), _readVector(r, r.activeBuffer, r.cursor, 3),
            _readVector(r, r.activeBuffer, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = INeighborDynamicsIntegrator(modules.integrator).kick(
            _readVector(r, next, r.cursor, 3), _readVector(r, next, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) { _requireFinite(velocity[d]); words[d] = _encode(velocity[d]); }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 3), words);
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = INeighborDynamicsPairKernel(modules.bond).evaluate(
            zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            INeighborDynamicsAngleKernel(modules.angle).evaluate(_bondedDisplacement(r, buffer, a.b, a.a),
                zero, _bondedDisplacement(r, buffer, a.b, a.c), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            INeighborDynamicsTorsionKernel(modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, neighborList.pairIndexAt(r.stateNamespace, index));
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = INeighborNonbonded(modules.nonbonded).evaluate(
            displacement, p.sigma, p.epsilon, p.chargeProduct,
            r.prefactor, r.switchDistance, r.cutoff, p.kind == 2);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory)
    {
        return INeighborGeometry(modules.geometry).displacement(
            _readVector(r, buffer, a, 0), _readVector(r, buffer, b, 0), r.box);
    }

    function _bondedDisplacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory displacement)
    {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(Run storage r, bytes16[3] memory displacement) private view {
        FloatMath m = FloatMath(modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) == 0) revert InvalidInput();
        }
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(modules.math).compare(a.theta0, INeighborDynamicsElementary(modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = INeighborDynamicsElementary(modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _parameters(Run storage r, uint256 atom) private view returns (ParticleParameters memory p) {
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon);
    }

    function _exception(Run storage r, uint256 index) private view returns (Pair memory p) {
        INeighborDynamicsData data = INeighborDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readExceptionWord(r.datasetId, offset + 1), r.atomCount);
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(data.readExceptionWord(r.datasetId, offset + 5));
        if (p.kind == 1) {
            if (p.sigma != bytes16(0) || p.epsilon != bytes16(0) || p.chargeProduct != bytes16(0)) revert InvalidInput();
        } else { _requirePositive(p.sigma); _requireNonnegative(p.epsilon); }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
        neighborList.setException(r.stateNamespace, p.a, p.b, uint8(p.kind));
    }

    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][uint256(p.a) * r.atomCount + p.b];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        p.chargeProduct = m.mul(a.charge, b.charge);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(INeighborDynamicsData(modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[12] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 12; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash || address(neighborList).codehash != neighborCodeHash)
            revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 12; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(neighborList), neighborCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[12] memory) {
        return [m.registry, m.dataset, m.math, m.integrator, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary, m.geometry, m.nonbonded];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/NeighborList.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";

/// @notice Writer-bound, resumable Verlet candidate lists from on-chain positions.
/// @dev The writer must freeze the selected position buffer while preparing or
///      using a list. Included direct exceptions retain global pair ordering.
contract NeighborList {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidInput();
    error UnknownList();
    error InvalidStage();
    error InvalidWork();
    error ChangedDependency();
    error OutOfBounds();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    bytes16 private constant REUSE_FRACTION = 0x3ffdfc00000000000000000000000000; // 127/256 < 1/2
    address public immutable writer;
    FloatMath public immutable numericalMath;
    OrthorhombicGeometry public immutable geometry;
    WorkingStatePage public immutable statePage;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable geometryCodeHash;
    bytes32 public immutable pageCodeHash;

    enum Stage { Missing, Registered, Checking, Copying, Building, Ready }
    struct List {
        uint32 atomCount;
        uint32 cursor;
        uint32 candidateCount;
        uint32 generation;
        uint32 reuseCount;
        uint8 buffer;
        bool rebuild;
        Stage stage;
        bytes16[3] box;
        bytes16 cutoff;
        bytes16 skin;
        bytes16 listRadius;
        bytes16 radiusSquared;
        bytes16 thresholdSquared;
        mapping(uint256 => bytes16[3]) referencePosition;
        mapping(uint256 => uint32) candidates;
        mapping(uint256 => uint8) exceptionKind;
    }
    mapping(bytes32 => List) private _lists;

    event ListRegistered(bytes32 indexed namespace, uint32 atoms, bytes16 cutoff, bytes16 skin);
    event Prepared(bytes32 indexed namespace, uint32 generation, uint32 candidates, bool rebuilt);

    modifier onlyWriter() { if (msg.sender != writer) revert Unauthorized(); _; }

    constructor(address writer_, address math_, address geometry_, address page_) {
        if (writer_.code.length == 0 || math_.code.length == 0 || geometry_.code.length == 0 || page_.code.length == 0)
            revert InvalidConfiguration();
        if (WorkingStatePage(page_).writer() != writer_ || address(OrthorhombicGeometry(geometry_).numericalMath()) != math_)
            revert InvalidConfiguration();
        writer = writer_;
        numericalMath = FloatMath(math_);
        geometry = OrthorhombicGeometry(geometry_);
        statePage = WorkingStatePage(page_);
        mathCodeHash = math_.codehash;
        geometryCodeHash = geometry_.codehash;
        pageCodeHash = page_.codehash;
    }

    function registerList(bytes32 namespace, uint32 atoms, bytes16[3] calldata box, bytes16 cutoff, bytes16 skin)
        external onlyWriter
    {
        _assertDependencies();
        if (namespace == bytes32(0) || atoms < 2 || atoms > MAX_ATOMS || _lists[namespace].stage != Stage.Missing)
            revert InvalidInput();
        FloatMath m = numericalMath;
        if (m.compare(skin, bytes16(0)) <= 0 || m.compare(cutoff, bytes16(0)) <= 0) revert InvalidInput();
        bytes16 radius = m.add(cutoff, skin);
        if (m.compare(radius, cutoff) <= 0) revert InvalidInput();
        geometry.validateBox(box, radius);
        (uint32 capacity, bool frozen) = statePage.namespaceInfo(namespace);
        if (capacity < uint256(atoms) * 18 + 2 || frozen) revert InvalidInput();
        List storage l = _lists[namespace];
        l.atomCount = atoms; l.box = box; l.cutoff = cutoff; l.skin = skin; l.listRadius = radius;
        l.radiusSquared = m.mul(radius, radius);
        // Use the representable shell width, which can be smaller than the
        // requested skin after addition at very different magnitudes.
        bytes16 effectiveSkin = m.sub(radius, cutoff);
        if (m.compare(effectiveSkin, skin) > 0) effectiveSkin = skin;
        // Bound the skin against the box, not only the list radius: periodic
        // image reduction has an absolute error scale set by the box length.
        // This conservative floor also excludes extreme box/list anisotropy.
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(effectiveSkin, m.div(box[axis], m.fromUInt(1 << 32))) < 0) revert InvalidInput();
        }
        bytes16 threshold = m.mul(effectiveSkin, REUSE_FRACTION);
        l.thresholdSquared = m.mul(threshold, threshold);
        if (m.isZero(l.thresholdSquared) || m.isZero(l.radiusSquared)) revert InvalidInput();
        l.stage = Stage.Registered;
        emit ListRegistered(namespace, atoms, cutoff, skin);
    }

    /// @notice Exclusions and direct exceptions are frozen before first preparation.
    function setException(bytes32 namespace, uint32 a, uint32 b, uint8 kind) external onlyWriter {
        List storage l = _get(namespace);
        if (l.stage != Stage.Registered || a >= b || b >= l.atomCount || kind == 0 || kind > 2) revert InvalidInput();
        uint256 key = uint256(a) * l.atomCount + b;
        if (l.exceptionKind[key] != 0) revert InvalidInput();
        l.exceptionKind[key] = kind;
    }

    function beginEvaluation(bytes32 namespace, uint8 buffer) external onlyWriter {
        _assertDependencies();
        List storage l = _get(namespace);
        if ((l.stage != Stage.Registered && l.stage != Stage.Ready) || buffer > 1) revert InvalidStage();
        l.buffer = buffer; l.cursor = 0; l.rebuild = false;
        if (l.generation == 0) { l.stage = Stage.Copying; l.candidateCount = 0; }
        else l.stage = Stage.Checking;
    }

    /// @notice One unit checks/copies one atom or screens one unordered pair.
    function advance(bytes32 namespace, uint256 work) external onlyWriter returns (uint256 processed, bool ready) {
        _assertDependencies();
        if (work == 0 || work > MAX_WORK) revert InvalidWork();
        List storage l = _get(namespace);
        if (l.stage < Stage.Checking || l.stage > Stage.Building) revert InvalidStage();
        while (processed < work && l.stage != Stage.Ready) {
            if (l.stage == Stage.Checking) _check(namespace, l);
            else if (l.stage == Stage.Copying) l.referencePosition[l.cursor] = _position(namespace, l, l.cursor);
            else _screen(l);
            ++processed; ++l.cursor;
            uint256 count = l.stage == Stage.Building ? uint256(l.atomCount) * (l.atomCount - 1) / 2 : l.atomCount;
            if (l.cursor == count) {
                l.cursor = 0;
                if (l.stage == Stage.Checking) {
                    if (l.rebuild) { l.stage = Stage.Copying; l.candidateCount = 0; }
                    else { l.stage = Stage.Ready; ++l.reuseCount; emit Prepared(namespace, l.generation, l.candidateCount, false); }
                } else if (l.stage == Stage.Copying) l.stage = Stage.Building;
                else { l.stage = Stage.Ready; ++l.generation; emit Prepared(namespace, l.generation, l.candidateCount, true); }
            }
        }
        ready = l.stage == Stage.Ready;
    }

    function listInfo(bytes32 namespace) external view returns (
        Stage stage, uint32 cursor, uint32 atomCount, uint32 candidateCount, uint32 generation,
        uint32 reuseCount, uint8 buffer, bool rebuild
    ) {
        List storage l = _get(namespace);
        return (l.stage, l.cursor, l.atomCount, l.candidateCount, l.generation, l.reuseCount, l.buffer, l.rebuild);
    }

    function parameters(bytes32 namespace) external view returns (bytes16[3] memory box, bytes16 cutoff, bytes16 skin, bytes16 radius, bytes16 thresholdSquared) {
        List storage l = _get(namespace);
        return (l.box, l.cutoff, l.skin, l.listRadius, l.thresholdSquared);
    }

    function pairIndexAt(bytes32 namespace, uint256 index) external view returns (uint32) {
        List storage l = _get(namespace);
        if (l.stage != Stage.Ready) revert InvalidStage();
        if (index >= l.candidateCount) revert OutOfBounds();
        return l.candidates[index];
    }

    function referenceAt(bytes32 namespace, uint256 atom) external view returns (bytes16[3] memory) {
        List storage l = _get(namespace);
        if (l.stage != Stage.Ready) revert InvalidStage();
        if (atom >= l.atomCount) revert OutOfBounds();
        return l.referencePosition[atom];
    }

    function _check(bytes32 namespace, List storage l) private {
        bytes16[3] memory current = _position(namespace, l, l.cursor);
        bytes16[3] storage previous = l.referencePosition[l.cursor];
        FloatMath m = numericalMath;
        bytes16 distanceSquared;
        // Unwrapped displacement is conservative even if an atom crosses many cells.
        for (uint256 axis; axis < 3; ++axis) {
            bytes16 delta = m.sub(current[axis], previous[axis]);
            distanceSquared = m.add(distanceSquared, m.mul(delta, delta));
        }
        if (m.compare(distanceSquared, l.thresholdSquared) >= 0) l.rebuild = true;
    }

    function _screen(List storage l) private {
        (uint32 a, uint32 b) = _pairIndices(l.cursor, l.atomCount);
        uint8 kind = l.exceptionKind[uint256(a) * l.atomCount + b];
        if (kind == 1) return;
        bool include = kind == 2;
        if (!include) {
            bytes16[3] memory displacement = geometry.displacement(l.referencePosition[a], l.referencePosition[b], l.box);
            bytes16 distanceSquared;
            for (uint256 axis; axis < 3; ++axis)
                distanceSquared = numericalMath.add(distanceSquared, numericalMath.mul(displacement[axis], displacement[axis]));
            // Boundary pairs are included; the reuse margin avoids a fragile equality criterion.
            include = numericalMath.compare(distanceSquared, l.radiusSquared) <= 0;
        }
        if (include) l.candidates[l.candidateCount++] = l.cursor;
    }

    function _position(bytes32 namespace, List storage l, uint256 atom) private view returns (bytes16[3] memory p) {
        bytes32[] memory words = statePage.readWords(namespace, uint256(l.buffer) * 9 * l.atomCount + atom * 9, 3);
        for (uint256 axis; axis < 3; ++axis) {
            if (uint256(words[axis]) >> 128 != 0) revert InvalidInput();
            p[axis] = bytes16(uint128(uint256(words[axis])));
            if (!numericalMath.isFinite(p[axis])) revert InvalidInput();
        }
    }

    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low; uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid; else high = mid;
        }
        a = uint32(low); b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }
    function _get(bytes32 namespace) private view returns (List storage l) {
        l = _lists[namespace]; if (l.stage == Stage.Missing) revert UnknownList();
    }
    function _assertDependencies() private view {
        if (address(numericalMath).codehash != mathCodeHash || address(geometry).codehash != geometryCodeHash ||
            address(statePage).codehash != pageCodeHash) revert ChangedDependency();
    }
}

contracts/core/PagedBondCoordinator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {DatasetCatalog} from "./DatasetCatalog.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {IOrviaFloatMath, IOrviaBondKernel} from "./ResumableBondEngine.sol";

/// @notice Paged, resumable harmonic-force validation component.
/// @dev All operands and outputs are on-chain. This is not a dynamics integrator.
contract PagedBondCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 16;
    address public immutable owner;
    IOrviaFloatMath public immutable numericalMath;
    IOrviaBondKernel public immutable bondKernel;
    ExperimentRegistry public immutable registry;
    DatasetCatalog public immutable catalog;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable kernelCodeHash;
    bytes32 public immutable registryCodeHash;
    bytes32 public immutable catalogCodeHash;
    bytes32 public immutable coreConfigurationHash;
    WorkingStatePage public statePage;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status { Missing, ValidatingAtoms, ValidatingBonds, Running, Completed }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        uint32 cursor;
        uint32 atomCount;
        uint32 bondCount;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    mapping(uint256 => Run) private _runs;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);

    constructor(address owner_, address math_, address kernel_, address registry_, address catalog_) {
        if (owner_ == address(0) || math_.code.length == 0 || kernel_.code.length == 0 ||
            registry_.code.length == 0 || catalog_.code.length == 0) revert InvalidConfiguration();
        if (IOrviaBondKernel(kernel_).numericalMath() != math_) revert InvalidConfiguration();
        owner = owner_;
        numericalMath = IOrviaFloatMath(math_);
        bondKernel = IOrviaBondKernel(kernel_);
        registry = ExperimentRegistry(registry_);
        catalog = DatasetCatalog(catalog_);
        mathCodeHash = math_.codehash;
        kernelCodeHash = kernel_.codehash;
        registryCodeHash = registry_.codehash;
        catalogCodeHash = catalog_.codehash;
        coreConfigurationHash = keccak256(abi.encode(
            math_, math_.codehash, kernel_, kernel_.codehash,
            registry_, registry_.codehash, catalog_, catalog_.codehash
        ));
    }

    /// @notice Resolve the writer/page deployment dependency exactly once.
    function bindWorkingPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this)) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    /// @notice Bind a frozen dataset. Numerical validation is a resumable stage.
    function registerExperiment(bytes32 protocolId, bytes32 datasetId) external returns (uint256 experimentId) {
        if (msg.sender != owner) revert Unauthorized();
        bytes32 protocolManifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = catalog.assertDataset(datasetId);
        (, uint32 atomCount, uint32 bondCount) = catalog.datasetInfo(datasetId);
        // Defense in depth for the schema this component actually supports.
        if (atomCount < 2 || atomCount > 4096 || bondCount == 0 || bondCount > 16384) revert InvalidInput();
        experimentId = nextExperimentId++;
        Run storage run = _runs[experimentId];
        run.protocolId = protocolId;
        run.datasetId = datasetId;
        run.datasetCommitment = datasetCommitment;
        run.atomCount = atomCount;
        run.bondCount = bondCount;
        run.status = Status.ValidatingAtoms;
        run.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-PAGED-STATE-v1"), block.chainid, address(this), experimentId));
        run.commitment = keccak256(abi.encode(
            bytes32("ORVIA-PAGED-BOND-v1"), block.chainid, address(this), experimentId,
            protocolManifest, datasetId, datasetCommitment, configurationHash, run.stateNamespace
        ));
        statePage.createNamespace(run.stateNamespace, atomCount * 3 + 1);
        emit ExperimentRegistered(experimentId, datasetId, run.commitment);
    }

    /// @notice Validate or calculate up to workLimit records, in a fixed order.
    /// @dev A revert rolls back both coordinator and working-page changes.
    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage run = _get(experimentId);
        if (run.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(run.protocolId);
        if (catalog.assertDataset(run.datasetId) != run.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && run.status != Status.Completed) {
            if (run.status == Status.ValidatingAtoms) {
                _readPosition(run.datasetId, run.cursor); // validates every finite coordinate
                if (++run.cursor == run.atomCount) { run.cursor = 0; run.status = Status.ValidatingBonds; }
            } else if (run.status == Status.ValidatingBonds) {
                _readBond(run, run.cursor); // validates indices and parameters before any forces
                if (++run.cursor == run.bondCount) { run.cursor = 0; run.status = Status.Running; }
            } else {
                _accumulate(run, run.cursor);
                if (++run.cursor == run.bondCount) {
                    statePage.sealNamespace(run.stateNamespace);
                    run.status = Status.Completed;
                }
            }
            ++processed;
        }
        completed = run.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, run.status, run.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 atomCount, uint256 bondCount, Status status, bytes16 totalEnergy
    ) {
        Run storage r = _get(experimentId);
        return (r.protocolId, r.datasetId, r.commitment, r.stateNamespace, r.cursor,
            r.atomCount, r.bondCount, r.status, _decodeFloat(statePage.readWord(r.stateNamespace, uint256(r.atomCount) * 3)));
    }

    function forceAt(uint256 experimentId, uint256 atom) external view returns (bytes16[3] memory value) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        for (uint256 d; d < 3; ++d) value[d] = _decodeFloat(statePage.readWord(r.stateNamespace, 3 * atom + d));
    }

    function positionAt(uint256 experimentId, uint256 atom) external view returns (bytes16[3] memory) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        return _readPosition(r.datasetId, atom);
    }

    function _accumulate(Run storage r, uint256 index) private {
        Bond memory b = _readBond(r, index);
        (bytes16 energy, bytes16[3] memory force) = bondKernel.evaluate(
            _readPosition(r.datasetId, b.a), _readPosition(r.datasetId, b.b), b.k, b.r0
        );
        _requireFinite(energy);
        uint256 energyIndex = uint256(r.atomCount) * 3;
        _addToWord(r.stateNamespace, energyIndex, energy, false);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            _addToWord(r.stateNamespace, uint256(b.a) * 3 + d, force[d], false);
            _addToWord(r.stateNamespace, uint256(b.b) * 3 + d, force[d], true);
        }
    }

    function _addToWord(bytes32 ns, uint256 index, bytes16 value, bool subtract) private {
        bytes16 previous = _decodeFloat(statePage.readWord(ns, index));
        bytes16 next = subtract ? numericalMath.sub(previous, value) : numericalMath.add(previous, value);
        _requireFinite(next);
        statePage.writeWord(ns, index, bytes32(uint256(uint128(next))));
    }

    function _readPosition(bytes32 datasetId, uint256 atom) private view returns (bytes16[3] memory p) {
        for (uint256 d; d < 3; ++d) p[d] = _decodeFloat(catalog.readPositionWord(datasetId, atom * 3 + d));
    }

    function _readBond(Run storage r, uint256 index) private view returns (Bond memory b) {
        uint256 start = index * 4;
        uint256 a = uint256(catalog.readBondWord(r.datasetId, start));
        uint256 other = uint256(catalog.readBondWord(r.datasetId, start + 1));
        if (a >= r.atomCount || other >= r.atomCount || a == other) revert InvalidInput();
        b.a = uint32(a);
        b.b = uint32(other);
        b.k = _decodeFloat(catalog.readBondWord(r.datasetId, start + 2));
        b.r0 = _decodeFloat(catalog.readBondWord(r.datasetId, start + 3));
        if (_negativeNonzero(b.k) || _negativeNonzero(b.r0)) revert InvalidInput();
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        if (address(numericalMath).codehash != mathCodeHash || address(bondKernel).codehash != kernelCodeHash ||
            address(registry).codehash != registryCodeHash || address(catalog).codehash != catalogCodeHash ||
            address(statePage).codehash != statePageCodeHash) revert ModuleCodeChanged();
        manifest = registry.assertProtocol(protocolId);
        registry.assertModule(protocolId, address(numericalMath), mathCodeHash);
        registry.assertModule(protocolId, address(bondKernel), kernelCodeHash);
        registry.assertModule(protocolId, address(catalog), catalogCodeHash);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }

    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _decodeFloat(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _negativeNonzero(bytes16 value) private pure returns (bool) {
        uint128 bits = uint128(value);
        return (bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0;
    }
}

contracts/core/PartitionedInputCatalog.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {DataPage} from "./DataPage.sol";

/// @notice Append-and-seal input streams with constant-address page lookup.
/// @dev A stream descriptor binds every page in canonical order. assertStream
///      checks descriptor sealing; every actual read authenticates touched pages.
contract PartitionedInputCatalog {
    error Unauthorized();
    error InvalidConfiguration();
    error StreamExists();
    error UnknownStream();
    error StreamSealed();
    error IncompleteStream();
    error InvalidPage();
    error PageAlreadyUsed();
    error PageChanged();
    error InvalidRead();

    uint256 public constant PAGE_WORDS = 4096;
    uint256 public constant MAX_BATCH_WORDS = 128;
    address public immutable owner;
    struct PageRecord { address page; bytes32 codeHash; bytes32 digest; uint32 wordCount; }
    struct Stream {
        bytes32 role;
        uint64 totalWords;
        uint64 appendedWords;
        uint64 pageCount;
        bool isSealed;
        bool exists;
        bytes32 rollingDigest;
        bytes32 commitment;
        mapping(uint256 => PageRecord) pages;
    }
    mapping(bytes32 => Stream) private _streams;
    mapping(address => bool) public isCatalogPage;
    mapping(address => bool) public pageUsed;
    event PageCreated(address indexed page, bytes32 indexed role, uint32 capacityWords);
    event StreamBegun(bytes32 indexed stream, bytes32 indexed role, uint64 totalWords);
    event PageAppended(bytes32 indexed stream, uint64 indexed pageIndex, address page, bytes32 digest);
    event StreamFrozen(bytes32 indexed stream, bytes32 commitment, uint64 totalWords);

    modifier onlyOwner() { if (msg.sender != owner) revert Unauthorized(); _; }
    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
    }
    function createPage(bytes32 role, uint32 capacityWords) external onlyOwner returns (address page) {
        page = address(new DataPage(owner, role, capacityWords));
        isCatalogPage[page] = true;
        emit PageCreated(page, role, capacityWords);
    }
    function beginStream(bytes32 id, bytes32 role, uint64 totalWords) external onlyOwner {
        if (id == bytes32(0) || role == bytes32(0)) revert InvalidConfiguration();
        if (_streams[id].exists) revert StreamExists();
        Stream storage s = _streams[id];
        s.role = role; s.totalWords = totalWords; s.exists = true;
        s.rollingDigest = keccak256(abi.encode(bytes32("ORVIA-PARTITIONED-INPUT-v1"),
            block.chainid, address(this), id, role, totalWords));
        emit StreamBegun(id, role, totalWords);
    }
    function appendPage(bytes32 id, address page) external onlyOwner {
        Stream storage s = _get(id);
        if (s.isSealed) revert StreamSealed();
        if (!isCatalogPage[page] || page.code.length == 0) revert InvalidPage();
        if (pageUsed[page]) revert PageAlreadyUsed();
        uint256 remaining = uint256(s.totalWords) - s.appendedWords;
        uint256 expected = remaining > PAGE_WORDS ? PAGE_WORDS : remaining;
        DataPage p = DataPage(page);
        if (expected == 0 || !p.isSealed() || p.role() != s.role ||
            p.wordCount() != expected || p.capacityWords() != expected) revert InvalidPage();
        PageRecord memory record = PageRecord(page, page.codehash, p.rollingDigest(), uint32(expected));
        s.pages[s.pageCount] = record; pageUsed[page] = true;
        s.rollingDigest = keccak256(abi.encode(s.rollingDigest, s.pageCount,
            record.page, record.codeHash, record.wordCount, record.digest));
        emit PageAppended(id, s.pageCount, page, record.digest);
        ++s.pageCount; s.appendedWords += uint64(expected);
    }
    function sealStream(bytes32 id) external onlyOwner returns (bytes32 commitment) {
        Stream storage s = _get(id);
        if (s.isSealed) revert StreamSealed();
        if (s.appendedWords != s.totalWords) revert IncompleteStream();
        commitment = keccak256(abi.encode(bytes32("ORVIA-SEALED-INPUT-v1"),
            block.chainid, address(this), id, s.role, s.totalWords, s.pageCount, s.rollingDigest));
        s.commitment = commitment; s.isSealed = true;
        emit StreamFrozen(id, commitment, s.totalWords);
    }
    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 wordCount) {
        Stream storage s = _sealed(id); return (s.commitment, s.totalWords);
    }
    function readWord(bytes32 id, uint64 index) external view returns (bytes32) {
        Stream storage s = _sealed(id);
        if (index >= s.totalWords) revert InvalidRead();
        PageRecord storage p = s.pages[uint256(index) / PAGE_WORDS]; _assertPage(p);
        return DataPage(p.page).readWord(uint256(index) % PAGE_WORDS);
    }
    function readWords(bytes32 id, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        Stream storage s = _sealed(id);
        if (count > MAX_BATCH_WORDS || start > s.totalWords || count > s.totalWords - start) revert InvalidRead();
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint256 index = uint256(start) + done;
            uint256 local = index % PAGE_WORDS;
            uint256 length = uint256(count) - done;
            if (length > PAGE_WORDS - local) length = PAGE_WORDS - local;
            PageRecord storage p = s.pages[index / PAGE_WORDS]; _assertPage(p);
            bytes32[] memory words = DataPage(p.page).readWords(local, length);
            for (uint256 i; i < length; ++i) values[done + i] = words[i];
            done += length;
        }
    }
    function streamInfo(bytes32 id) external view returns (
        bytes32 role, uint64 totalWords, uint64 appendedWords, uint64 pageCount, bool isSealed, bytes32 commitment
    ) {
        Stream storage s = _get(id);
        return (s.role, s.totalWords, s.appendedWords, s.pageCount, s.isSealed, s.commitment);
    }
    function pageInfo(bytes32 id, uint64 pageIndex) external view returns (
        address page, bytes32 codeHash, bytes32 digest, uint32 wordCount
    ) {
        Stream storage s = _get(id); if (pageIndex >= s.pageCount) revert InvalidRead();
        PageRecord storage p = s.pages[pageIndex]; return (p.page, p.codeHash, p.digest, p.wordCount);
    }
    function _assertPage(PageRecord storage p) private view {
        if (p.page.codehash != p.codeHash || p.page.code.length == 0) revert PageChanged();
        DataPage page = DataPage(p.page);
        if (!page.isSealed() || page.rollingDigest() != p.digest || page.wordCount() != p.wordCount)
            revert PageChanged();
    }
    function _get(bytes32 id) private view returns (Stream storage s) {
        s = _streams[id]; if (!s.exists) revert UnknownStream();
    }
    function _sealed(bytes32 id) private view returns (Stream storage s) {
        s = _get(id); if (!s.isSealed) revert IncompleteStream();
    }
}

contracts/core/PeriodicDataset.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {DataPage} from "./DataPage.sol";
import {DynamicsDataset} from "./DynamicsDataset.sol";

/// @notice Frozen periodic configuration and nonbonded inputs, layered over dynamics data.
/// @dev Stream values are schema-checked when read. Numerical particle/exception
///      validity and sorted canonical exception pairs are checked by the coordinator.
contract PeriodicDataset {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidRole();
    error InvalidDataset();
    error AlreadyRegistered();
    error UnknownDataset();
    error InvalidPageList();
    error DuplicatePage(address page);
    error UntrustedPage(address page);
    error InvalidPage(address page);
    error PageChanged(address page);
    error DynamicsCatalogChanged();
    error DynamicsDatasetChanged();
    error InvalidCoverage();
    error InvalidRead();
    error NoncanonicalWord();

    bytes32 public constant NONBONDED_ROLE = keccak256("ORVIA.NONBONDED.v1");
    bytes32 public constant EXCEPTION_ROLE = keccak256("ORVIA.EXCEPTIONS.v1");
    bytes32 public constant DATASET_DOMAIN = keccak256("ORVIA.PERIODIC.DATASET.v1");
    uint256 public constant MAX_PAGES_PER_STREAM = 16;
    uint32 public constant MAX_EXCEPTIONS = 4096;
    address public immutable owner;
    DynamicsDataset public immutable dynamicsCatalog;
    bytes32 public immutable dynamicsCatalogCodeHash;

    struct PageRecord { address page; bytes32 codeHash; bytes32 digest; uint32 wordCount; }
    struct Registration {
        bytes32 dynamicsDatasetId;
        address[] nonbondedPages;
        address[] exceptionPages;
        uint32 exceptionCount;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
    }
    struct Dataset {
        bytes32 commitment;
        bytes32 dynamicsDatasetId;
        bytes32 dynamicsCommitment;
        // atoms, bonds, angles, torsions, exceptions
        uint32[5] counts;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        bytes32[2] streamCommitments;
        bool exists;
        PageRecord[][2] streams;
        mapping(address => bool) usedPages;
    }
    mapping(address => bool) public isCatalogPage;
    mapping(bytes32 => Dataset) private _datasets;

    event PageCreated(address indexed page, bytes32 indexed role, uint32 capacityWords);
    event DatasetRegistered(bytes32 indexed datasetId, bytes32 indexed dynamicsDatasetId, bytes32 commitment);

    constructor(address owner_, address dynamicsCatalog_) {
        if (owner_ == address(0) || dynamicsCatalog_.code.length == 0) revert InvalidConfiguration();
        owner = owner_;
        dynamicsCatalog = DynamicsDataset(dynamicsCatalog_);
        dynamicsCatalogCodeHash = dynamicsCatalog_.codehash;
    }

    function createPage(bytes32 role, uint32 capacityWords) external returns (address page) {
        if (msg.sender != owner) revert Unauthorized();
        if (role != NONBONDED_ROLE && role != EXCEPTION_ROLE) revert InvalidRole();
        page = address(new DataPage(owner, role, capacityWords));
        isCatalogPage[page] = true;
        emit PageCreated(page, role, capacityWords);
    }

    function registerDataset(bytes32 id, Registration calldata input) external returns (bytes32 commitment) {
        if (msg.sender != owner) revert Unauthorized();
        _begin(id, input);
        _freezeStream(id, 0, input.nonbondedPages);
        _freezeStream(id, 1, input.exceptionPages);
        commitment = _finish(id);
    }

    function datasetInfo(bytes32 id) external view returns (
        bytes32 commitment, bytes32 dynamicsDatasetId, uint32 atomCount, uint32 bondCount,
        uint32 angleCount, uint32 torsionCount, uint32 pairCount
    ) {
        Dataset storage d = _get(id);
        uint32 n = d.counts[0];
        return (d.commitment, d.dynamicsDatasetId, n, d.counts[1], d.counts[2], d.counts[3], n * (n - 1) / 2);
    }

    function periodicInfo(bytes32 id) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Dataset storage d = _get(id);
        return (d.box, d.switchDistance, d.cutoff, d.prefactor, d.counts[4]);
    }

    function assertDataset(bytes32 id) external view returns (bytes32 commitment) {
        Dataset storage d = _get(id);
        _assertDynamics(d);
        for (uint256 s; s < 2; ++s) {
            for (uint256 i; i < d.streams[s].length; ++i) _assertPage(d.streams[s][i]);
        }
        return d.commitment;
    }

    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id); _checkDynamicsCode();
        return dynamicsCatalog.readPositionWord(d.dynamicsDatasetId, index);
    }
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id); _checkDynamicsCode();
        return dynamicsCatalog.readBondWord(d.dynamicsDatasetId, index);
    }
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id); _checkDynamicsCode();
        return dynamicsCatalog.readParticleWord(d.dynamicsDatasetId, index);
    }
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id); _checkDynamicsCode();
        return dynamicsCatalog.readAngleWord(d.dynamicsDatasetId, index);
    }
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32) {
        Dataset storage d = _get(id); _checkDynamicsCode();
        return dynamicsCatalog.readTorsionWord(d.dynamicsDatasetId, index);
    }
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 0, index); }
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32) { return _read(_get(id), 1, index); }

    function pageCount(bytes32 id, uint8 stream) external view returns (uint256) {
        if (stream > 1) revert InvalidRead();
        return _get(id).streams[stream].length;
    }
    function pageInfo(bytes32 id, uint8 stream, uint256 index)
        external view returns (address page, bytes32 codeHash, bytes32 digest, uint32 wordCount)
    {
        if (stream > 1) revert InvalidRead();
        PageRecord[] storage pages = _get(id).streams[stream];
        if (index >= pages.length) revert InvalidRead();
        PageRecord storage p = pages[index];
        return (p.page, p.codeHash, p.digest, p.wordCount);
    }

    function _begin(bytes32 id, Registration calldata input) private {
        if (id == bytes32(0) || input.exceptionCount > MAX_EXCEPTIONS) revert InvalidDataset();
        if (_datasets[id].exists) revert AlreadyRegistered();
        _checkConfiguration(input);
        _checkDynamicsCode();
        bytes32 frozen = dynamicsCatalog.assertDataset(input.dynamicsDatasetId);
        (bytes32 reported,, uint32 atoms, uint32 bonds, uint32 angles, uint32 torsions, uint32 pairs) =
            dynamicsCatalog.datasetInfo(input.dynamicsDatasetId);
        if (atoms < 2 || atoms > 4096 || bonds == 0 || pairs != 0 || reported != frozen) revert InvalidDataset();
        if (input.exceptionCount > uint256(atoms) * (atoms - 1) / 2) revert InvalidDataset();
        Dataset storage d = _datasets[id];
        d.dynamicsDatasetId = input.dynamicsDatasetId;
        d.dynamicsCommitment = frozen;
        d.counts = [atoms, bonds, angles, torsions, input.exceptionCount];
        d.box = input.box;
        d.switchDistance = input.switchDistance;
        d.cutoff = input.cutoff;
        d.prefactor = input.prefactor;
    }

    function _checkConfiguration(Registration calldata input) private pure {
        uint128 rs = uint128(input.switchDistance);
        uint128 rc = uint128(input.cutoff);
        if (!_positiveFinite(rs) || !_positiveFinite(rc) || rs >= rc) revert InvalidConfiguration();
        // 2*cutoff < box is equivalent to cutoff < box/2. Doubling a positive
        // binary128 value is exact, including subnormals, unless it overflows.
        uint128 exponent = rc >> 112;
        if (exponent == 0x7ffe) revert InvalidConfiguration();
        uint128 twiceCutoff = exponent == 0 ? rc << 1 : rc + (uint128(1) << 112);
        for (uint256 axis; axis < 3; ++axis) {
            uint128 length = uint128(input.box[axis]);
            if (!_positiveFinite(length) || twiceCutoff >= length) revert InvalidConfiguration();
        }
        uint128 p = uint128(input.prefactor);
        uint128 magnitude = p & 0x7fffffffffffffffffffffffffffffff;
        if ((magnitude >> 112) == 0x7fff || (p >> 127 != 0 && magnitude != 0)) revert InvalidConfiguration();
    }
    function _positiveFinite(uint128 bits) private pure returns (bool) {
        return bits != 0 && bits >> 127 == 0 && bits >> 112 != 0x7fff;
    }

    function _freezeStream(bytes32 id, uint8 stream, address[] calldata pages) private {
        Dataset storage d = _datasets[id];
        uint256 count = stream == 0 ? d.counts[0] : d.counts[4];
        if (pages.length > MAX_PAGES_PER_STREAM || (count == 0 ? pages.length != 0 : pages.length == 0)) revert InvalidPageList();
        bytes32 role = _role(stream);
        bytes32 digest = keccak256(abi.encode(role, pages.length));
        uint256 words;
        for (uint256 i; i < pages.length; ++i) {
            address page = pages[i];
            if (d.usedPages[page]) revert DuplicatePage(page);
            if (!isCatalogPage[page]) revert UntrustedPage(page);
            DataPage inputPage = DataPage(page);
            if (page.code.length == 0 || inputPage.role() != role || !inputPage.isSealed()) revert InvalidPage(page);
            uint256 size = inputPage.wordCount();
            if (size == 0 || size > inputPage.capacityWords()) revert InvalidPage(page);
            d.usedPages[page] = true;
            PageRecord memory p = PageRecord(page, page.codehash, inputPage.rollingDigest(), uint32(size));
            d.streams[stream].push(p);
            words += size;
            digest = keccak256(abi.encode(digest, i, p.page, p.codeHash, p.wordCount, p.digest));
        }
        if (words != count * _width(stream)) revert InvalidCoverage();
        d.streamCommitments[stream] = digest;
    }

    function _finish(bytes32 id) private returns (bytes32 commitment) {
        Dataset storage d = _datasets[id];
        bytes32 dynamicsHeader = keccak256(abi.encode(
            address(dynamicsCatalog), dynamicsCatalogCodeHash, d.dynamicsDatasetId, d.dynamicsCommitment, d.counts
        ));
        bytes32 configuration = keccak256(abi.encode(d.box, d.switchDistance, d.cutoff, d.prefactor));
        commitment = keccak256(abi.encode(DATASET_DOMAIN, block.chainid, address(this), id,
            dynamicsHeader, configuration, d.streamCommitments));
        d.commitment = commitment;
        d.exists = true;
        emit DatasetRegistered(id, d.dynamicsDatasetId, commitment);
    }

    function _read(Dataset storage d, uint8 stream, uint256 index) private view returns (bytes32 word) {
        uint256 width = _width(stream);
        uint256 count = stream == 0 ? d.counts[0] : d.counts[4];
        if (index >= count * width) revert InvalidRead();
        uint256 globalOffset = index % width;
        PageRecord[] storage pages = d.streams[stream];
        for (uint256 i; i < pages.length; ++i) {
            PageRecord storage p = pages[i];
            if (index < p.wordCount) {
                _assertPage(p);
                word = DataPage(p.page).readWord(index);
                uint256 bits = stream == 1 && globalOffset < 3 ? 32 : 128;
                if (uint256(word) >> bits != 0) revert NoncanonicalWord();
                return word;
            }
            index -= p.wordCount;
        }
        revert InvalidRead();
    }
    function _assertPage(PageRecord storage p) private view {
        if (p.page.code.length == 0 || p.page.codehash != p.codeHash) revert PageChanged(p.page);
        DataPage page = DataPage(p.page);
        if (!page.isSealed() || page.rollingDigest() != p.digest || page.wordCount() != p.wordCount) revert PageChanged(p.page);
    }
    function _checkDynamicsCode() private view {
        if (address(dynamicsCatalog).codehash != dynamicsCatalogCodeHash) revert DynamicsCatalogChanged();
    }
    function _assertDynamics(Dataset storage d) private view {
        _checkDynamicsCode();
        if (dynamicsCatalog.assertDataset(d.dynamicsDatasetId) != d.dynamicsCommitment) revert DynamicsDatasetChanged();
    }
    function _role(uint8 stream) private pure returns (bytes32) { return stream == 0 ? NONBONDED_ROLE : EXCEPTION_ROLE; }
    function _width(uint8 stream) private pure returns (uint256) { return stream == 0 ? 3 : 6; }
    function _get(bytes32 id) private view returns (Dataset storage d) {
        d = _datasets[id];
        if (!d.exists) revert UnknownDataset();
    }
}

contracts/core/PeriodicDynamicsCoordinat.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {FloatMath} from "../math/FloatMath.sol";

interface IPeriodicDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function periodicInfo(bytes32 id) external view returns (bytes16[3] memory, bytes16, bytes16, bytes16, uint32);
}
interface IPeriodicDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface IPeriodicDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface IPeriodicDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface IPeriodicDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface IPeriodicDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface IPeriodicDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}
interface IPeriodicDynamicsIntegrator {
    function drift(bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextPosition, bytes16[3] memory halfVelocity);
    function kick(bytes16[3] calldata halfVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity);
}

interface IPeriodicGeometry {
    function displacement(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata box)
        external view returns (bytes16[3] memory);
    function validateBox(bytes16[3] calldata box, bytes16 cutoff) external view;
}
interface IPeriodicNonbonded {
    function ljKernel() external view returns (address);
    function coulombKernel() external view returns (address);
    function evaluate(bytes16[3] calldata displacement, bytes16 sigma, bytes16 epsilon,
        bytes16 chargeProduct, bytes16 prefactor, bytes16 switchDistance, bytes16 cutoff, bool exception)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}

/// @notice Bounded, double-buffered velocity Verlet with orthorhombic minimum images.
/// @dev All unordered pairs are enumerated on-chain. Regular interactions use
///      switched LJ and conducting-limit reaction field; exceptions are explicit.
///      No Ewald/PME, neighbor-list cache, thermostat or free-energy estimator.
contract PeriodicDynamicsCoordinator {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_STEPS = 4096;
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address integrator;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
    }
    Modules public modules;
    bytes32[12] public moduleCodeHashes;
    WorkingStatePage public statePage;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingExceptions, InitialBonds, InitialAngles, InitialTorsions, InitialPairs,
        Drift, NextBonds, NextAngles, NextTorsions, NextPairs, Kick, Completed
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        bytes16 dt;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 completedSteps;
        uint32 targetSteps;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        Status status;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; }
    struct ParticleParameters { bytes16 sigma; bytes16 epsilon; bytes16 charge; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event StepCommitted(uint256 indexed experimentId, uint256 completedSteps, uint256 activeBuffer);

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = modules_;
        address[12] memory addresses = _moduleAddresses(modules_);
        bytes32[12] memory hashes;
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 12; ++i) {
            if (IPeriodicDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (IPeriodicDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            IPeriodicDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        if (IPeriodicNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
            IPeriodicNonbonded(modules_.nonbonded).coulombKernel() != modules_.coulomb) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function bindWorkingPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this)) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, bytes16 dt, uint32 steps)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(dt);
        if (steps == 0 || steps > MAX_STEPS) revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = IPeriodicDynamicsData(modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = IPeriodicDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 ||
            r.pairCount != uint256(r.atomCount) * (r.atomCount - 1) / 2) revert InvalidInput();
        (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount) =
            IPeriodicDynamicsData(modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount) revert InvalidInput();
        _requirePositive(r.switchDistance); _requirePositive(r.cutoff); _requireNonnegative(r.prefactor);
        if (FloatMath(modules.math).compare(r.switchDistance, r.cutoff) >= 0) revert InvalidInput();
        IPeriodicGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId;
        r.datasetId = datasetId;
        r.datasetCommitment = datasetCommitment;
        r.dt = dt;
        r.targetSteps = steps;
        r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-PERIODIC-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-PERIODIC-RUN-v1"), block.chainid, address(this),
            experimentId, manifest, datasetId, datasetCommitment, configurationHash, dt, steps, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (r.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (IPeriodicDynamicsData(modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && r.status != Status.Completed) {
            _process(r);
            ++processed;
            ++r.cursor;
            if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
        }
        completed = r.status == Status.Completed;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 completedSteps, uint256 targetSteps, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId;
        datasetId = r.datasetId;
        commitment = r.commitment;
        stateNamespace = r.stateNamespace;
        cursor = r.cursor;
        completedSteps = r.completedSteps;
        targetSteps = r.targetSteps;
        atomCount = r.atomCount;
        activeBuffer = r.activeBuffer;
        status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }

    function stateAt(uint256 experimentId, uint256 atom) external view returns (
        bytes16[3] memory position, bytes16[3] memory velocity, bytes16[3] memory force
    ) {
        Run storage r = _get(experimentId);
        if (atom >= r.atomCount) revert InvalidInput();
        position = _readVector(r, r.activeBuffer, atom, 0);
        velocity = _readVector(r, r.activeBuffer, atom, 3);
        force = _readVector(r, r.activeBuffer, atom, 6);
    }

    function experimentParameters(uint256 experimentId) external view returns (
        bytes16 dt, uint32 bondCount, uint32 angleCount, uint32 torsionCount, uint32 pairCount, bytes32 datasetCommitment
    ) {
        Run storage r = _get(experimentId);
        return (r.dt, r.bondCount, r.angleCount, r.torsionCount, r.pairCount, r.datasetCommitment);
    }

    function periodicParameters(uint256 experimentId) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Run storage r = _get(experimentId);
        return (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount);
    }

    function _process(Run storage r) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions) _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Drift) _drift(r);
        else if (r.status <= Status.NextPairs) _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.Kick) _kick(r);
        else revert InvalidInput();
    }

    function _finishStage(Run storage r, uint256 experimentId) private {
        if (r.status == Status.Kick) {
            r.activeBuffer = 1 - r.activeBuffer;
            ++r.completedSteps;
            emit StepCommitted(experimentId, r.completedSteps, r.activeBuffer);
            if (r.completedSteps == r.targetSteps) {
                statePage.sealNamespace(r.stateNamespace);
                r.status = Status.Completed;
                return;
            }
            r.status = Status.Drift;
        } else r.status = Status(uint8(r.status) + 1);
        r.cursor = 0;
        // Empty optional interaction streams consume no artificial work units.
        while (_stageCount(r) == 0) r.status = Status(uint8(r.status) + 1);
    }

    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (r.status == Status.Loading || r.status == Status.Drift || r.status == Status.Kick) return r.atomCount;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        return r.pairCount;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingExceptions) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status) - 6;
        if (status >= Status.NextBonds && status <= Status.NextPairs) return uint8(status) - 11;
        revert InvalidInput();
    }

    function _load(Run storage r) private {
        uint256 atom = r.cursor;
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        bytes16 mass = _decode(data.readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
        _parameters(r, atom);
        bytes32[] memory words = new bytes32[](6);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            words[d + 3] = _encode(_decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)));
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }

    function _drift(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
        (bytes16[3] memory position, bytes16[3] memory halfVelocity) = IPeriodicDynamicsIntegrator(modules.integrator).drift(
            _readVector(r, r.activeBuffer, r.cursor, 0), _readVector(r, r.activeBuffer, r.cursor, 3),
            _readVector(r, r.activeBuffer, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(position[d]);
            _requireFinite(halfVelocity[d]);
            words[d] = _encode(position[d]);
            words[d + 3] = _encode(halfVelocity[d]);
            // Remaining three words deliberately clear old inactive-buffer forces.
        }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }

    function _kick(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        bytes16[3] memory velocity = IPeriodicDynamicsIntegrator(modules.integrator).kick(
            _readVector(r, next, r.cursor, 3), _readVector(r, next, r.cursor, 6), _mass(r, r.cursor), r.dt
        );
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) { _requireFinite(velocity[d]); words[d] = _encode(velocity[d]); }
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 3), words);
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = IPeriodicDynamicsPairKernel(modules.bond).evaluate(
            zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            IPeriodicDynamicsAngleKernel(modules.angle).evaluate(_bondedDisplacement(r, buffer, a.b, a.a),
                zero, _bondedDisplacement(r, buffer, a.b, a.c), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            IPeriodicDynamicsTorsionKernel(modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, index);
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = IPeriodicNonbonded(modules.nonbonded).evaluate(
            displacement, p.sigma, p.epsilon, p.chargeProduct,
            r.prefactor, r.switchDistance, r.cutoff, p.kind == 2);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory)
    {
        return IPeriodicGeometry(modules.geometry).displacement(
            _readVector(r, buffer, a, 0), _readVector(r, buffer, b, 0), r.box);
    }

    function _bondedDisplacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory displacement)
    {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(Run storage r, bytes16[3] memory displacement) private view {
        FloatMath m = FloatMath(modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) == 0) revert InvalidInput();
        }
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(modules.math).compare(a.theta0, IPeriodicDynamicsElementary(modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = IPeriodicDynamicsElementary(modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _parameters(Run storage r, uint256 atom) private view returns (ParticleParameters memory p) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon);
    }

    function _exception(Run storage r, uint256 index) private view returns (Pair memory p) {
        IPeriodicDynamicsData data = IPeriodicDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readExceptionWord(r.datasetId, offset + 1), r.atomCount);
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(data.readExceptionWord(r.datasetId, offset + 5));
        if (p.kind == 1) {
            if (p.sigma != bytes16(0) || p.epsilon != bytes16(0) || p.chargeProduct != bytes16(0)) revert InvalidInput();
        } else { _requirePositive(p.sigma); _requireNonnegative(p.epsilon); }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
    }

    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][uint256(p.a) * r.atomCount + p.b];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        p.chargeProduct = m.mul(a.charge, b.charge);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(IPeriodicDynamicsData(modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[12] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 12; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash) revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 12; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[12] memory) {
        return [m.registry, m.dataset, m.math, m.integrator, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary, m.geometry, m.nonbonded];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/PeriodicMinimizer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {WorkingStatePage} from "./WorkingStatePage.sol";
import {FloatMath} from "../math/FloatMath.sol";

interface IMinimizerDynamicsData {
    function datasetInfo(bytes32 id) external view returns (bytes32, bytes32, uint32, uint32, uint32, uint32, uint32);
    function assertDataset(bytes32 id) external view returns (bytes32);
    function readPositionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readBondWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readParticleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readAngleWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readTorsionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readNonbondedWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readExceptionWord(bytes32 id, uint256 index) external view returns (bytes32);
    function periodicInfo(bytes32 id) external view returns (bytes16[3] memory, bytes16, bytes16, bytes16, uint32);
}
interface IMinimizerDynamicsMathIdentity { function numericalMath() external view returns (address); }
interface IMinimizerDynamicsAngularIdentity { function elementaryMath() external view returns (address); }
interface IMinimizerDynamicsElementary {
    function PI() external view returns (bytes16);
    function TWO_PI() external view returns (bytes16);
}
interface IMinimizerDynamicsPairKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 p, bytes16 q)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}
interface IMinimizerDynamicsAngleKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16 k, bytes16 theta0)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC);
}
interface IMinimizerDynamicsTorsionKernel {
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view returns
        (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD);
}

interface IMinimizerGeometry {
    function displacement(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata box)
        external view returns (bytes16[3] memory);
    function validateBox(bytes16[3] calldata box, bytes16 cutoff) external view;
}
interface IMinimizerNonbonded {
    function ljKernel() external view returns (address);
    function coulombKernel() external view returns (address);
    function evaluate(bytes16[3] calldata displacement, bytes16 sigma, bytes16 epsilon,
        bytes16 chargeProduct, bytes16 prefactor, bytes16 switchDistance, bytes16 cutoff, bool exception)
        external view returns (bytes16 energy, bytes16[3] memory forceA);
}

/// @notice Resumable steepest descent with complete periodic forces and Armijo backtracking.
/// @dev Current state is unchanged until a complete trial passes acceptance.
///      This minimizes the declared cutoff Hamiltonian; it is not equilibration.
contract PeriodicMinimizer {
    error Unauthorized();
    error InvalidConfiguration();
    error AlreadyConfigured();
    error NotConfigured();
    error ModuleCodeChanged();
    error DatasetChanged();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();

    uint256 public constant MAX_WORK = 8;
    uint256 public constant MAX_ATOMS = 1024;
    uint256 public constant MAX_ITERATIONS = 4096;
    uint256 public constant MAX_TRIALS = 64;
    bytes16 public constant MIN_FORCE_TOLERANCE = 0x3c170000000000000000000000000000; // 2^-1000
    address public immutable owner;
    bytes32 public immutable coreConfigurationHash;

    struct Modules {
        address registry;
        address dataset;
        address math;
        address bond;
        address angle;
        address torsion;
        address lj;
        address coulomb;
        address elementary;
        address geometry;
        address nonbonded;
    }
    Modules public modules;
    bytes32[11] public moduleCodeHashes;
    WorkingStatePage public statePage;
    bytes32 public statePageCodeHash;
    bytes32 public configurationHash;
    uint256 public nextExperimentId = 1;

    enum Status {
        Missing, Loading, ValidatingBonds, ValidatingAngles, ValidatingTorsions,
        ValidatingExceptions, InitialBonds, InitialAngles, InitialTorsions, InitialPairs,
        AssessInitial, Propose, TrialBonds, TrialAngles, TrialTorsions, TrialPairs,
        AssessTrial, Decide, Converged, Failed
    }
    enum Failure { None, LineSearchLimit, IterationLimit, StepUnderflow }
    struct Settings {
        bytes16 initialStep;
        bytes16 forceTolerance;
        bytes16 armijo;
        uint32 maxIterations;
        uint32 maxTrials;
    }
    struct Run {
        bytes32 protocolId;
        bytes32 datasetId;
        bytes32 datasetCommitment;
        bytes32 commitment;
        bytes32 stateNamespace;
        Settings settings;
        bytes16 stepSize;
        bytes16 gradientSquared;
        bytes16 trialGradientSquared;
        bytes16 rmsForce;
        bytes16 trialRmsForce;
        bytes16 maximumForceSquared;
        bytes16 trialMaximumForceSquared;
        bytes16[3] box;
        bytes16 switchDistance;
        bytes16 cutoff;
        bytes16 prefactor;
        uint32 exceptionCount;
        uint32 lastExceptionKey;
        uint32 cursor;
        uint32 iterations;
        uint32 trials;
        uint32 rejectedTrials;
        uint32 atomCount;
        uint32 bondCount;
        uint32 angleCount;
        uint32 torsionCount;
        uint32 pairCount;
        uint8 activeBuffer;
        bool trialInvalid;
        Status status;
        Failure failure;
    }
    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Angle { uint32 a; uint32 b; uint32 c; bytes16 k; bytes16 theta0; }
    struct Torsion { uint32 a; uint32 b; uint32 c; uint32 d; uint32 periodicity; bytes16 k; bytes16 phase; }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigma; bytes16 epsilon; bytes16 chargeProduct; }
    struct ParticleParameters { bytes16 sigma; bytes16 epsilon; bytes16 charge; }
    struct FourEvaluation { bytes16 energy; bytes16[3][4] force; }
    mapping(uint256 => Run) private _runs;
    mapping(bytes32 => mapping(uint256 => uint256)) private _exceptionIndex;

    event WorkingPageBound(address indexed page, bytes32 configurationHash);
    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed datasetId, bytes32 commitment);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, Status status, uint256 cursor);
    event TrialAccepted(uint256 indexed experimentId, uint256 iteration, bytes16 energy, bytes16 rmsForce);
    event TrialRejected(uint256 indexed experimentId, uint256 trial, bool invalidGeometry);

    constructor(address owner_, Modules memory modules_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        modules = modules_;
        address[11] memory addresses = _moduleAddresses(modules_);
        bytes32[11] memory hashes;
        for (uint256 i; i < 11; ++i) {
            if (addresses[i].code.length == 0) revert InvalidConfiguration();
            hashes[i] = addresses[i].codehash;
            moduleCodeHashes[i] = hashes[i];
        }
        for (uint256 i = 3; i < 11; ++i) {
            if (IMinimizerDynamicsMathIdentity(addresses[i]).numericalMath() != modules_.math) revert InvalidConfiguration();
        }
        if (IMinimizerDynamicsAngularIdentity(modules_.angle).elementaryMath() != modules_.elementary ||
            IMinimizerDynamicsAngularIdentity(modules_.torsion).elementaryMath() != modules_.elementary) revert InvalidConfiguration();
        if (IMinimizerNonbonded(modules_.nonbonded).ljKernel() != modules_.lj ||
            IMinimizerNonbonded(modules_.nonbonded).coulombKernel() != modules_.coulomb) revert InvalidConfiguration();
        coreConfigurationHash = keccak256(abi.encode(modules_, hashes));
    }

    function bindWorkingPage(address page) external {
        if (msg.sender != owner) revert Unauthorized();
        if (address(statePage) != address(0)) revert AlreadyConfigured();
        if (page.code.length == 0 || WorkingStatePage(page).writer() != address(this)) revert InvalidConfiguration();
        statePage = WorkingStatePage(page);
        statePageCodeHash = page.codehash;
        configurationHash = keccak256(abi.encode(coreConfigurationHash, page, page.codehash));
        emit WorkingPageBound(page, configurationHash);
    }

    function registerExperiment(bytes32 protocolId, bytes32 datasetId, Settings calldata settings)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        _requirePositive(settings.initialStep); _requirePositive(settings.forceTolerance); _requirePositive(settings.armijo);
        if (FloatMath(modules.math).compare(settings.forceTolerance, MIN_FORCE_TOLERANCE) < 0) revert InvalidInput();
        if (settings.maxIterations == 0 || settings.maxIterations > MAX_ITERATIONS || settings.maxTrials == 0 ||
            settings.maxTrials > MAX_TRIALS || FloatMath(modules.math).compare(settings.armijo, FloatMath(modules.math).fromUInt(1)) >= 0)
            revert InvalidInput();
        bytes32 manifest = _assertDependencies(protocolId);
        bytes32 datasetCommitment = IMinimizerDynamicsData(modules.dataset).assertDataset(datasetId);
        experimentId = nextExperimentId++;
        Run storage r = _runs[experimentId];
        (,, r.atomCount, r.bondCount, r.angleCount, r.torsionCount, r.pairCount) = IMinimizerDynamicsData(modules.dataset).datasetInfo(datasetId);
        if (r.atomCount < 2 || r.atomCount > MAX_ATOMS || r.bondCount == 0 || r.bondCount > 16384 ||
            r.angleCount > 4096 || r.torsionCount > 4096 || r.pairCount != uint256(r.atomCount) * (r.atomCount - 1) / 2) revert InvalidInput();
        (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount) = IMinimizerDynamicsData(modules.dataset).periodicInfo(datasetId);
        if (r.exceptionCount > 4096 || r.exceptionCount > r.pairCount) revert InvalidInput();
        _requirePositive(r.switchDistance); _requirePositive(r.cutoff); _requireNonnegative(r.prefactor);
        if (FloatMath(modules.math).compare(r.switchDistance, r.cutoff) >= 0) revert InvalidInput();
        IMinimizerGeometry(modules.geometry).validateBox(r.box, r.cutoff);
        r.protocolId = protocolId; r.datasetId = datasetId; r.datasetCommitment = datasetCommitment;
        r.settings = settings; r.stepSize = settings.initialStep; r.status = Status.Loading;
        r.stateNamespace = keccak256(abi.encode(bytes32("ORVIA-MINIMIZER-STATE-v1"), block.chainid, address(this), experimentId));
        r.commitment = keccak256(abi.encode(bytes32("ORVIA-MINIMIZER-RUN-v1"), block.chainid, address(this), experimentId,
            manifest, datasetId, datasetCommitment, configurationHash, settings, r.stateNamespace));
        statePage.createNamespace(r.stateNamespace, r.atomCount * 18 + 2);
        emit ExperimentRegistered(experimentId, datasetId, r.commitment);
    }

    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool converged)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage r = _get(experimentId);
        if (_terminal(r)) revert ExperimentCompleted();
        _assertDependencies(r.protocolId);
        if (IMinimizerDynamicsData(modules.dataset).assertDataset(r.datasetId) != r.datasetCommitment) revert DatasetChanged();
        while (processed < workLimit && !_terminal(r)) {
            if (r.status == Status.Decide) { _decide(r, experimentId); ++processed; continue; }
            bool rejected;
            if (r.status == Status.Propose || (r.status >= Status.TrialBonds && r.status <= Status.AssessTrial)) {
                try this.processTrialRecord(experimentId) {} catch (bytes memory reason) {
                    if (!_recoverable(reason)) assembly { revert(add(reason, 32), mload(reason)) }
                    r.trialInvalid = true; r.status = Status.Decide; r.cursor = 0; rejected = true;
                }
            } else _process(r, experimentId);
            ++processed;
            if (!rejected && !_terminal(r)) {
                ++r.cursor;
                if (r.cursor == _stageCount(r)) _finishStage(r, experimentId);
            }
        }
        converged = r.status == Status.Converged;
        emit ExperimentAdvanced(experimentId, processed, r.status, r.cursor);
    }

    /// @dev Self-call isolates partial trial work on a known numerical-domain error.
    ///      Empty/OOG, panic and unknown failures revert the entire transaction.
    function processTrialRecord(uint256 experimentId) external {
        if (msg.sender != address(this)) revert Unauthorized();
        Run storage r = _get(experimentId);
        if (r.status == Status.Propose) _propose(r);
        else if (r.status == Status.AssessTrial) _assess(r);
        else if (r.status >= Status.TrialBonds && r.status <= Status.TrialPairs)
            _calculate(r, 1 - r.activeBuffer, _kind(r.status), r.cursor);
        else revert InvalidInput();
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 datasetId, bytes32 commitment, bytes32 stateNamespace,
        uint256 cursor, uint256 iterations, uint256 trials, uint256 atomCount,
        uint256 activeBuffer, Status status, bytes16 potentialEnergy
    ) {
        Run storage r = _get(experimentId);
        protocolId = r.protocolId; datasetId = r.datasetId; commitment = r.commitment;
        stateNamespace = r.stateNamespace; cursor = r.cursor; iterations = r.iterations;
        trials = r.trials; atomCount = r.atomCount; activeBuffer = r.activeBuffer; status = r.status;
        potentialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
    }
    function stateAt(uint256 experimentId, uint256 atom) external view returns (bytes16[3] memory position, bytes16[3] memory force) {
        Run storage r = _get(experimentId); if (atom >= r.atomCount) revert InvalidInput();
        return (_readVector(r, r.activeBuffer, atom, 0), _readVector(r, r.activeBuffer, atom, 6));
    }
    function minimizerInfo(uint256 experimentId) external view returns (
        Settings memory settings, bytes16 stepSize, bytes16 rmsForce, bytes16 maximumForce,
        uint32 rejectedTrials, bool lastTrialInvalid, Failure failure
    ) {
        Run storage r = _get(experimentId);
        return (r.settings, r.stepSize, r.rmsForce, FloatMath(modules.math).sqrt(r.maximumForceSquared),
            r.rejectedTrials, r.trialInvalid, r.failure);
    }
    function periodicParameters(uint256 experimentId) external view returns (
        bytes16[3] memory box, bytes16 switchDistance, bytes16 cutoff, bytes16 prefactor, uint32 exceptionCount
    ) {
        Run storage r = _get(experimentId); return (r.box, r.switchDistance, r.cutoff, r.prefactor, r.exceptionCount);
    }
    function _process(Run storage r, uint256 experimentId) private {
        if (r.status == Status.Loading) _load(r);
        else if (r.status <= Status.ValidatingExceptions) _validate(r, _kind(r.status), r.cursor);
        else if (r.status <= Status.InitialPairs) _calculate(r, r.activeBuffer, _kind(r.status), r.cursor);
        else if (r.status == Status.AssessInitial || r.status == Status.AssessTrial) _assess(r);
        else if (r.status == Status.Decide) _decide(r, experimentId);
        else revert InvalidInput();
    }
    function _finishStage(Run storage r, uint256) private {
        if (r.status == Status.AssessInitial) {
            r.rmsForce = FloatMath(modules.math).sqrt(FloatMath(modules.math).div(r.gradientSquared, FloatMath(modules.math).fromUInt(r.atomCount)));
            if (FloatMath(modules.math).compare(r.rmsForce, r.settings.forceTolerance) <= 0) { _stop(r, Failure.None); return; }
        } else if (r.status == Status.AssessTrial) {
            r.trialRmsForce = FloatMath(modules.math).sqrt(FloatMath(modules.math).div(r.trialGradientSquared, FloatMath(modules.math).fromUInt(r.atomCount)));
        }
        r.status = Status(uint8(r.status) + 1); r.cursor = 0;
        while (_stageCount(r) == 0) r.status = Status(uint8(r.status) + 1);
    }
    function _stageCount(Run storage r) private view returns (uint256) {
        if (r.status == Status.ValidatingExceptions) return r.exceptionCount;
        if (r.status == Status.Loading || r.status == Status.Propose || r.status == Status.AssessInitial || r.status == Status.AssessTrial) return r.atomCount;
        if (r.status == Status.Decide) return 1;
        uint256 kind = _kind(r.status);
        if (kind == 0) return r.bondCount;
        if (kind == 1) return r.angleCount;
        if (kind == 2) return r.torsionCount;
        return r.pairCount;
    }
    function _kind(Status status) private pure returns (uint256) {
        if (status >= Status.ValidatingBonds && status <= Status.ValidatingExceptions) return uint8(status) - 2;
        if (status >= Status.InitialBonds && status <= Status.InitialPairs) return uint8(status) - 6;
        if (status >= Status.TrialBonds && status <= Status.TrialPairs) return uint8(status) - 12;
        revert InvalidInput();
    }
    function _load(Run storage r) private {
        uint256 atom = r.cursor; IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        _mass(r, atom); _parameters(r, atom);
        bytes32[] memory words = new bytes32[](3);
        for (uint256 d; d < 3; ++d) {
            words[d] = _encode(_decode(data.readPositionWord(r.datasetId, atom * 3 + d)));
            _decode(data.readParticleWord(r.datasetId, atom * 4 + d + 1)); // Validate, but do not integrate velocities.
        }
        statePage.writeWords(r.stateNamespace, atom * 9, words);
    }
    function _propose(Run storage r) private {
        uint256 next = 1 - r.activeBuffer;
        if (r.cursor == 0) {
            statePage.writeWord(r.stateNamespace, _energyIndex(r, next), bytes32(0));
            r.trialInvalid = false; r.trialGradientSquared = bytes16(0); r.trialMaximumForceSquared = bytes16(0);
        }
        bytes16[3] memory x = _readVector(r, r.activeBuffer, r.cursor, 0);
        bytes16[3] memory f = _readVector(r, r.activeBuffer, r.cursor, 6);
        bytes32[] memory words = new bytes32[](9);
        for (uint256 d; d < 3; ++d) words[d] = _encode(FloatMath(modules.math).add(x[d], FloatMath(modules.math).mul(r.stepSize, f[d])));
        statePage.writeWords(r.stateNamespace, _vectorIndex(r, next, r.cursor, 0), words);
    }
    function _assess(Run storage r) private {
        bool trial = r.status == Status.AssessTrial;
        bytes16[3] memory f = _readVector(r, trial ? 1 - r.activeBuffer : r.activeBuffer, r.cursor, 6);
        FloatMath m = FloatMath(modules.math); bytes16 squared;
        for (uint256 d; d < 3; ++d) squared = m.add(squared, m.mul(f[d], f[d]));
        if (trial) {
            r.trialGradientSquared = m.add(r.trialGradientSquared, squared);
            if (m.compare(squared, r.trialMaximumForceSquared) > 0) r.trialMaximumForceSquared = squared;
        } else {
            r.gradientSquared = m.add(r.gradientSquared, squared);
            if (m.compare(squared, r.maximumForceSquared) > 0) r.maximumForceSquared = squared;
        }
    }
    function armijoAccept(uint256 experimentId) external view returns (bool) {
        if (msg.sender != address(this)) revert Unauthorized();
        Run storage r = _get(experimentId);
        if (r.status != Status.Decide || r.trialInvalid) revert InvalidInput();
        FloatMath m = FloatMath(modules.math);
        bytes16 oldEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, r.activeBuffer)));
        bytes16 trialEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, 1 - r.activeBuffer)));
        bytes16 requiredDecrease = m.mul(m.mul(r.settings.armijo, r.stepSize), r.gradientSquared);
        return m.compare(trialEnergy, oldEnergy) < 0 && m.compare(trialEnergy, m.sub(oldEnergy, requiredDecrease)) <= 0;
    }
    function _decide(Run storage r, uint256 experimentId) private {
        FloatMath m = FloatMath(modules.math);
        bytes16 newEnergy = _decode(statePage.readWord(r.stateNamespace, _energyIndex(r, 1 - r.activeBuffer)));
        bool accepted;
        if (!r.trialInvalid) {
            try this.armijoAccept(experimentId) returns (bool value) { accepted = value; }
            catch (bytes memory reason) {
                if (!_recoverable(reason)) assembly { revert(add(reason, 32), mload(reason)) }
                r.trialInvalid = true;
            }
        }
        if (accepted) {
            r.activeBuffer = 1 - r.activeBuffer; ++r.iterations;
            r.gradientSquared = r.trialGradientSquared; r.rmsForce = r.trialRmsForce;
            r.maximumForceSquared = r.trialMaximumForceSquared;
            emit TrialAccepted(experimentId, r.iterations, newEnergy, r.rmsForce);
            if (m.compare(r.rmsForce, r.settings.forceTolerance) <= 0) { _stop(r, Failure.None); return; }
            if (r.iterations == r.settings.maxIterations) { _stop(r, Failure.IterationLimit); return; }
            r.stepSize = r.settings.initialStep; r.trials = 0;
        } else {
            ++r.trials; ++r.rejectedTrials; emit TrialRejected(experimentId, r.trials, r.trialInvalid);
            if (r.trials == r.settings.maxTrials) { _stop(r, Failure.LineSearchLimit); return; }
            r.stepSize = m.div(r.stepSize, m.fromUInt(2));
            if (m.isZero(r.stepSize)) { _stop(r, Failure.StepUnderflow); return; }
        }
        r.status = Status.Propose; r.cursor = 0;
    }
    function _stop(Run storage r, Failure reason) private {
        r.failure = reason; r.status = reason == Failure.None ? Status.Converged : Status.Failed;
        statePage.sealNamespace(r.stateNamespace);
    }
    function _terminal(Run storage r) private view returns (bool) { return r.status == Status.Converged || r.status == Status.Failed; }
    function _recoverable(bytes memory reason) private pure returns (bool) {
        if (reason.length != 4) return false;
        bytes4 selector; assembly { selector := mload(add(reason, 32)) }
        return selector == bytes4(keccak256("ZeroSeparation()")) || selector == bytes4(keccak256("SingularGeometry()")) ||
            selector == bytes4(keccak256("NonFinite()")) || selector == bytes4(keccak256("NonFiniteInput()")) ||
            selector == bytes4(keccak256("NonFiniteNumber()")) || selector == bytes4(keccak256("ImageRangeExceeded()")) ||
            selector == bytes4(keccak256("UnresolvedImage()")) || selector == bytes4(keccak256("InvalidInput()")) ||
            selector == bytes4(keccak256("DivisionByZero()")) || selector == bytes4(keccak256("NegativeSquareRoot()"));
    }

    function _validate(Run storage r, uint256 kind, uint256 index) private {
        if (kind == 0) _bond(r, index);
        else if (kind == 1) _angle(r, index);
        else if (kind == 2) _torsion(r, index);
        else _validateException(r, index);
    }
    function _calculate(Run storage r, uint256 buffer, uint256 kind, uint256 index) private {
        if (kind == 0) _calculateBond(r, buffer, index);
        else if (kind == 1) _calculateAngle(r, buffer, index);
        else if (kind == 2) _calculateTorsion(r, buffer, index);
        else _calculatePair(r, buffer, index);
    }

    function _calculateBond(Run storage r, uint256 buffer, uint256 index) private {
        Bond memory b = _bond(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory force) = IMinimizerDynamicsPairKernel(modules.bond).evaluate(
            zero, _bondedDisplacement(r, buffer, b.a, b.b), b.k, b.r0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, b.a, force, false);
        _addForce(r, buffer, b.b, force, true);
    }
    function _calculateAngle(Run storage r, uint256 buffer, uint256 index) private {
        Angle memory a = _angle(r, index);
        bytes16[3] memory zero;
        (bytes16 energy, bytes16[3] memory fa, bytes16[3] memory fb, bytes16[3] memory fc) =
            IMinimizerDynamicsAngleKernel(modules.angle).evaluate(_bondedDisplacement(r, buffer, a.b, a.a),
                zero, _bondedDisplacement(r, buffer, a.b, a.c), a.k, a.theta0);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, a.a, fa, false);
        _addForce(r, buffer, a.b, fb, false);
        _addForce(r, buffer, a.c, fc, false);
    }
    function _calculateTorsion(Run storage r, uint256 buffer, uint256 index) private {
        Torsion memory t = _torsion(r, index);
        FourEvaluation memory result = _evaluateTorsion(r, buffer, t);
        _addEnergy(r, buffer, result.energy);
        _addForce(r, buffer, t.a, result.force[0], false);
        _addForce(r, buffer, t.b, result.force[1], false);
        _addForce(r, buffer, t.c, result.force[2], false);
        _addForce(r, buffer, t.d, result.force[3], false);
    }
    function _evaluateTorsion(Run storage r, uint256 buffer, Torsion memory t)
        private view returns (FourEvaluation memory result)
    {
        bytes16[3][4] memory positions;
        positions[1] = _bondedDisplacement(r, buffer, t.a, t.b);
        bytes16[3] memory bc = _bondedDisplacement(r, buffer, t.b, t.c);
        bytes16[3] memory cd = _bondedDisplacement(r, buffer, t.c, t.d);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            positions[2][d] = m.add(positions[1][d], bc[d]);
            positions[3][d] = m.add(positions[2][d], cd[d]);
        }
        (result.energy, result.force[0], result.force[1], result.force[2], result.force[3]) =
            IMinimizerDynamicsTorsionKernel(modules.torsion).evaluate(positions[0], positions[1], positions[2], positions[3],
                t.periodicity, t.k, t.phase);
    }
    function _calculatePair(Run storage r, uint256 buffer, uint256 index) private {
        Pair memory p = _pair(r, index);
        if (p.kind == 1) return; // Declared exclusions perform no geometric evaluation.
        bytes16[3] memory displacement = _displacement(r, buffer, p.a, p.b);
        if (p.kind == 2) _requireUniqueImage(r, displacement);
        (bytes16 energy, bytes16[3] memory force) = IMinimizerNonbonded(modules.nonbonded).evaluate(
            displacement, p.sigma, p.epsilon, p.chargeProduct,
            r.prefactor, r.switchDistance, r.cutoff, p.kind == 2);
        _addEnergy(r, buffer, energy);
        _addForce(r, buffer, p.a, force, false);
        _addForce(r, buffer, p.b, force, true);
    }

    function _displacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory)
    {
        return IMinimizerGeometry(modules.geometry).displacement(
            _readVector(r, buffer, a, 0), _readVector(r, buffer, b, 0), r.box);
    }

    function _bondedDisplacement(Run storage r, uint256 buffer, uint256 a, uint256 b)
        private view returns (bytes16[3] memory displacement)
    {
        displacement = _displacement(r, buffer, a, b);
        _requireUniqueImage(r, displacement);
    }

    /// @dev A nearest image is nonunique at an exact half-box component. Bonded
    ///      terms and uncut exceptions reject that nondifferentiable geometry.
    function _requireUniqueImage(Run storage r, bytes16[3] memory displacement) private view {
        FloatMath m = FloatMath(modules.math);
        bytes16 two = m.fromUInt(2);
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.abs(displacement[axis]), m.div(r.box[axis], two)) == 0) revert InvalidInput();
        }
    }

    function _bond(Run storage r, uint256 index) private view returns (Bond memory b) {
        IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        uint256 offset = index * 4;
        b.a = _atom(data.readBondWord(r.datasetId, offset), r.atomCount);
        b.b = _atom(data.readBondWord(r.datasetId, offset + 1), r.atomCount);
        if (b.a == b.b) revert InvalidInput();
        b.k = _decode(data.readBondWord(r.datasetId, offset + 2));
        b.r0 = _decode(data.readBondWord(r.datasetId, offset + 3));
        _requireNonnegative(b.k); _requireNonnegative(b.r0);
    }
    function _angle(Run storage r, uint256 index) private view returns (Angle memory a) {
        IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        uint256 offset = index * 5;
        a.a = _atom(data.readAngleWord(r.datasetId, offset), r.atomCount);
        a.b = _atom(data.readAngleWord(r.datasetId, offset + 1), r.atomCount);
        a.c = _atom(data.readAngleWord(r.datasetId, offset + 2), r.atomCount);
        if (a.a == a.b || a.a == a.c || a.b == a.c) revert InvalidInput();
        a.k = _decode(data.readAngleWord(r.datasetId, offset + 3));
        a.theta0 = _decode(data.readAngleWord(r.datasetId, offset + 4));
        _requireNonnegative(a.k); _requireNonnegative(a.theta0);
        if (FloatMath(modules.math).compare(a.theta0, IMinimizerDynamicsElementary(modules.elementary).PI()) > 0) revert InvalidInput();
    }
    function _torsion(Run storage r, uint256 index) private view returns (Torsion memory t) {
        IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        uint256 offset = index * 7;
        t.a = _atom(data.readTorsionWord(r.datasetId, offset), r.atomCount);
        t.b = _atom(data.readTorsionWord(r.datasetId, offset + 1), r.atomCount);
        t.c = _atom(data.readTorsionWord(r.datasetId, offset + 2), r.atomCount);
        t.d = _atom(data.readTorsionWord(r.datasetId, offset + 3), r.atomCount);
        if (t.a == t.b || t.a == t.c || t.a == t.d || t.b == t.c || t.b == t.d || t.c == t.d) revert InvalidInput();
        uint256 n = uint256(data.readTorsionWord(r.datasetId, offset + 4));
        if (n == 0 || n > 6) revert InvalidInput();
        t.periodicity = uint32(n);
        t.k = _decode(data.readTorsionWord(r.datasetId, offset + 5));
        t.phase = _decode(data.readTorsionWord(r.datasetId, offset + 6));
        _requireNonnegative(t.k);
        FloatMath m = FloatMath(modules.math);
        bytes16 twoPi = IMinimizerDynamicsElementary(modules.elementary).TWO_PI();
        if (m.compare(t.phase, m.neg(twoPi)) < 0 || m.compare(t.phase, twoPi) > 0) revert InvalidInput();
    }
    function _parameters(Run storage r, uint256 atom) private view returns (ParticleParameters memory p) {
        IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        p.sigma = _decode(data.readNonbondedWord(r.datasetId, atom * 3));
        p.epsilon = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 1));
        p.charge = _decode(data.readNonbondedWord(r.datasetId, atom * 3 + 2));
        _requirePositive(p.sigma); _requireNonnegative(p.epsilon);
    }

    function _exception(Run storage r, uint256 index) private view returns (Pair memory p) {
        IMinimizerDynamicsData data = IMinimizerDynamicsData(modules.dataset);
        uint256 offset = index * 6;
        p.a = _atom(data.readExceptionWord(r.datasetId, offset), r.atomCount);
        p.b = _atom(data.readExceptionWord(r.datasetId, offset + 1), r.atomCount);
        uint256 kind = uint256(data.readExceptionWord(r.datasetId, offset + 2));
        if (p.a >= p.b || kind < 1 || kind > 2) revert InvalidInput();
        p.kind = uint32(kind);
        p.sigma = _decode(data.readExceptionWord(r.datasetId, offset + 3));
        p.epsilon = _decode(data.readExceptionWord(r.datasetId, offset + 4));
        p.chargeProduct = _decode(data.readExceptionWord(r.datasetId, offset + 5));
        if (p.kind == 1) {
            if (p.sigma != bytes16(0) || p.epsilon != bytes16(0) || p.chargeProduct != bytes16(0)) revert InvalidInput();
        } else { _requirePositive(p.sigma); _requireNonnegative(p.epsilon); }
    }

    function _validateException(Run storage r, uint256 index) private {
        Pair memory p = _exception(r, index);
        uint32 key = p.a * r.atomCount + p.b;
        if (index != 0 && key <= r.lastExceptionKey) revert InvalidInput();
        r.lastExceptionKey = key;
        _exceptionIndex[r.stateNamespace][key] = index + 1;
    }

    function _pair(Run storage r, uint256 index) private view returns (Pair memory p) {
        (p.a, p.b) = _pairIndices(index, r.atomCount);
        uint256 exceptionIndex = _exceptionIndex[r.stateNamespace][uint256(p.a) * r.atomCount + p.b];
        if (exceptionIndex != 0) return _exception(r, exceptionIndex - 1);
        ParticleParameters memory a = _parameters(r, p.a);
        ParticleParameters memory b = _parameters(r, p.b);
        FloatMath m = FloatMath(modules.math);
        p.sigma = m.div(m.add(a.sigma, b.sigma), m.fromUInt(2));
        p.epsilon = m.sqrt(m.mul(a.epsilon, b.epsilon));
        p.chargeProduct = m.mul(a.charge, b.charge);
    }

    /// @dev Lexicographic unordered-pair inversion, at most ten iterations for N<=1024.
    function _pairIndices(uint256 index, uint256 count) private pure returns (uint32 a, uint32 b) {
        uint256 low;
        uint256 high = count - 1;
        while (low + 1 < high) {
            uint256 mid = (low + high) / 2;
            if (mid * (2 * count - mid - 1) / 2 <= index) low = mid;
            else high = mid;
        }
        a = uint32(low);
        b = uint32(low + 1 + index - low * (2 * count - low - 1) / 2);
    }

    function _mass(Run storage r, uint256 atom) private view returns (bytes16 mass) {
        mass = _decode(IMinimizerDynamicsData(modules.dataset).readParticleWord(r.datasetId, atom * 4));
        _requirePositive(mass);
    }
    function _readVector(Run storage r, uint256 buffer, uint256 atom, uint256 field)
        private view returns (bytes16[3] memory result)
    {
        bytes32[] memory words = statePage.readWords(r.stateNamespace, _vectorIndex(r, buffer, atom, field), 3);
        for (uint256 d; d < 3; ++d) result[d] = _decode(words[d]);
    }
    function _addForce(Run storage r, uint256 buffer, uint256 atom, bytes16[3] memory force, bool subtract) private {
        uint256 offset = _vectorIndex(r, buffer, atom, 6);
        bytes32[] memory words = statePage.readWords(r.stateNamespace, offset, 3);
        FloatMath m = FloatMath(modules.math);
        for (uint256 d; d < 3; ++d) {
            _requireFinite(force[d]);
            bytes16 previous = _decode(words[d]);
            bytes16 next = subtract ? m.sub(previous, force[d]) : m.add(previous, force[d]);
            _requireFinite(next);
            words[d] = _encode(next);
        }
        statePage.writeWords(r.stateNamespace, offset, words);
    }
    function _addEnergy(Run storage r, uint256 buffer, bytes16 energy) private {
        _requireFinite(energy);
        uint256 offset = _energyIndex(r, buffer);
        bytes16 next = FloatMath(modules.math).add(_decode(statePage.readWord(r.stateNamespace, offset)), energy);
        _requireFinite(next);
        statePage.writeWord(r.stateNamespace, offset, _encode(next));
    }
    function _vectorIndex(Run storage r, uint256 buffer, uint256 atom, uint256 field) private view returns (uint256) {
        return buffer * 9 * uint256(r.atomCount) + atom * 9 + field;
    }
    function _energyIndex(Run storage r, uint256 buffer) private view returns (uint256) {
        return uint256(r.atomCount) * 18 + buffer;
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(statePage) == address(0)) revert NotConfigured();
        address[11] memory addresses = _moduleAddresses(modules);
        for (uint256 i; i < 11; ++i) if (addresses[i].codehash != moduleCodeHashes[i]) revert ModuleCodeChanged();
        if (address(statePage).codehash != statePageCodeHash) revert ModuleCodeChanged();
        ExperimentRegistry registry = ExperimentRegistry(modules.registry);
        manifest = registry.assertProtocol(protocolId);
        for (uint256 i = 1; i < 11; ++i) registry.assertModule(protocolId, addresses[i], moduleCodeHashes[i]);
        registry.assertModule(protocolId, address(statePage), statePageCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }
    function _moduleAddresses(Modules memory m) private pure returns (address[11] memory) {
        return [m.registry, m.dataset, m.math, m.bond, m.angle, m.torsion, m.lj, m.coulomb, m.elementary, m.geometry, m.nonbonded];
    }
    function _get(uint256 experimentId) private view returns (Run storage r) {
        r = _runs[experimentId];
        if (r.status == Status.Missing) revert UnknownExperiment();
    }
    function _atom(bytes32 word, uint256 count) private pure returns (uint32) {
        uint256 value = uint256(word);
        if (value >= count) revert InvalidInput();
        return uint32(value);
    }
    function _decode(bytes32 word) private pure returns (bytes16 value) {
        if (uint256(word) >> 128 != 0) revert InvalidInput();
        value = bytes16(uint128(uint256(word)));
        _requireFinite(value);
    }
    function _encode(bytes16 value) private pure returns (bytes32) { return bytes32(uint256(uint128(value))); }
    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }
    function _requireNonnegative(bytes16 value) private pure {
        _requireFinite(value);
        uint128 bits = uint128(value);
        if ((bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0) revert InvalidInput();
    }
    function _requirePositive(bytes16 value) private pure {
        _requireNonnegative(value);
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) revert InvalidInput();
    }
}

contracts/core/ResumableBondEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";

interface IOrviaFloatMath {
    function add(bytes16 a, bytes16 b) external view returns (bytes16);
    function sub(bytes16 a, bytes16 b) external view returns (bytes16);
}

interface IOrviaBondKernel {
    function numericalMath() external view returns (address);
    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 k, bytes16 r0)
        external view returns (bytes16 energy, bytes16[3] memory forceOnA);
}

/// @notice Component-validation engine: resumable harmonic-bond force/energy accumulation.
/// @dev This is not the complete ORVIA molecular dynamics or binding free-energy engine.
/// Coordinates are fixed for the entire force evaluation and outputs are committed transactionally.
contract ResumableBondEngine {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidInput();
    error NonFiniteNumber();
    error UnknownExperiment();
    error InvalidWorkLimit();
    error ExperimentCompleted();
    error ModuleCodeChanged();

    uint256 public constant MAX_WORK = 16;
    uint256 public constant MAX_ATOMS = 128;
    uint256 public constant MAX_BONDS = 256;
    address public immutable owner;
    IOrviaFloatMath public immutable numericalMath;
    IOrviaBondKernel public immutable bondKernel;
    ExperimentRegistry public immutable registry;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable kernelCodeHash;
    bytes32 public immutable registryCodeHash;
    uint256 public nextExperimentId = 1;

    enum Status { Missing, Ready, Running, Completed }

    struct Bond { uint32 a; uint32 b; bytes16 k; bytes16 r0; }
    struct Run {
        bytes32 protocolId;
        bytes32 inputHash;
        bytes32 commitment;
        uint32 cursor;
        Status status;
        bytes16 totalEnergy;
        bytes16[3][] positions;
        bytes16[3][] forces;
        Bond[] bonds;
    }
    mapping(uint256 => Run) private _runs;

    event ExperimentRegistered(uint256 indexed experimentId, bytes32 indexed protocolId, bytes32 commitment, uint256 atoms, uint256 bonds);
    event ExperimentAdvanced(uint256 indexed experimentId, uint256 processed, uint256 cursor, bytes16 totalEnergy, Status status);

    constructor(address owner_, address math_, address kernel_, address registry_) {
        if (owner_ == address(0) || math_.code.length == 0 || kernel_.code.length == 0 || registry_.code.length == 0) {
            revert InvalidConfiguration();
        }
        if (IOrviaBondKernel(kernel_).numericalMath() != math_) revert InvalidConfiguration();
        owner = owner_;
        numericalMath = IOrviaFloatMath(math_);
        bondKernel = IOrviaBondKernel(kernel_);
        registry = ExperimentRegistry(registry_);
        mathCodeHash = math_.codehash;
        kernelCodeHash = kernel_.codehash;
        registryCodeHash = registry_.codehash;
    }

    /// @notice Atomically register and seal a complete component-test input.
    /// @dev The declared protocol must contain this engine, its math module and its kernel.
    function registerExperiment(bytes32 protocolId, bytes16[3][] calldata positions, Bond[] calldata bonds)
        external returns (uint256 experimentId)
    {
        if (msg.sender != owner) revert Unauthorized();
        if (positions.length < 2 || positions.length > MAX_ATOMS || bonds.length == 0 || bonds.length > MAX_BONDS) {
            revert InvalidInput();
        }
        bytes32 protocolManifest = _assertDependencies(protocolId);
        for (uint256 i; i < positions.length; ++i) {
            for (uint256 d; d < 3; ++d) _requireFinite(positions[i][d]);
        }
        for (uint256 i; i < bonds.length; ++i) {
            Bond calldata bond = bonds[i];
            if (bond.a >= positions.length || bond.b >= positions.length || bond.a == bond.b) revert InvalidInput();
            _requireFinite(bond.k);
            _requireFinite(bond.r0);
            if (_negativeNonzero(bond.k) || _negativeNonzero(bond.r0)) revert InvalidInput();
        }

        experimentId = nextExperimentId++;
        Run storage run = _runs[experimentId];
        run.protocolId = protocolId;
        run.inputHash = keccak256(abi.encode(positions, bonds));
        run.commitment = keccak256(abi.encode(
            bytes32("ORVIA-BOND-FIXTURE-v1"), block.chainid, address(this), experimentId,
            protocolManifest, run.inputHash, address(numericalMath), mathCodeHash,
            address(bondKernel), kernelCodeHash, address(registry), registryCodeHash
        ));
        run.status = Status.Ready;
        for (uint256 i; i < positions.length; ++i) {
            run.positions.push(positions[i]);
            run.forces.push();
        }
        for (uint256 i; i < bonds.length; ++i) run.bonds.push(bonds[i]);
        emit ExperimentRegistered(experimentId, protocolId, run.commitment, positions.length, bonds.length);
    }

    /// @notice Anyone may fund a bounded batch; inputs and the operation order are fixed.
    /// @dev Any failing kernel/math call reverts the whole transaction, including earlier work in this batch.
    function advanceExperiment(uint256 experimentId, uint256 workLimit)
        external returns (uint256 processed, bool completed)
    {
        if (workLimit == 0 || workLimit > MAX_WORK) revert InvalidWorkLimit();
        Run storage run = _get(experimentId);
        if (run.status == Status.Completed) revert ExperimentCompleted();
        _assertDependencies(run.protocolId);
        uint256 start = run.cursor;
        uint256 end = start + workLimit;
        if (end > run.bonds.length) end = run.bonds.length;
        for (uint256 i = start; i < end; ++i) {
            Bond storage bond = run.bonds[i];
            (bytes16 energy, bytes16[3] memory forceA) = bondKernel.evaluate(
                run.positions[bond.a], run.positions[bond.b], bond.k, bond.r0
            );
            _requireFinite(energy);
            run.totalEnergy = numericalMath.add(run.totalEnergy, energy);
            _requireFinite(run.totalEnergy);
            for (uint256 d; d < 3; ++d) {
                _requireFinite(forceA[d]);
                run.forces[bond.a][d] = numericalMath.add(run.forces[bond.a][d], forceA[d]);
                run.forces[bond.b][d] = numericalMath.sub(run.forces[bond.b][d], forceA[d]);
                _requireFinite(run.forces[bond.a][d]);
                _requireFinite(run.forces[bond.b][d]);
            }
        }
        processed = end - start;
        run.cursor = uint32(end);
        completed = end == run.bonds.length;
        run.status = completed ? Status.Completed : Status.Running;
        emit ExperimentAdvanced(experimentId, processed, end, run.totalEnergy, run.status);
    }

    function runInfo(uint256 experimentId) external view returns (
        bytes32 protocolId, bytes32 inputHash, bytes32 commitment, uint256 cursor,
        uint256 bondCount, uint256 atomCount, Status status, bytes16 totalEnergy
    ) {
        Run storage run = _get(experimentId);
        return (run.protocolId, run.inputHash, run.commitment, run.cursor,
            run.bonds.length, run.positions.length, run.status, run.totalEnergy);
    }

    function positionAt(uint256 experimentId, uint256 index) external view returns (bytes16[3] memory) {
        return _get(experimentId).positions[index];
    }

    function forceAt(uint256 experimentId, uint256 index) external view returns (bytes16[3] memory) {
        return _get(experimentId).forces[index];
    }

    function bondAt(uint256 experimentId, uint256 index) external view returns (Bond memory) {
        return _get(experimentId).bonds[index];
    }

    function _assertDependencies(bytes32 protocolId) private view returns (bytes32 manifest) {
        if (address(numericalMath).codehash != mathCodeHash || address(bondKernel).codehash != kernelCodeHash ||
            address(registry).codehash != registryCodeHash) revert ModuleCodeChanged();
        manifest = registry.assertProtocol(protocolId);
        registry.assertModule(protocolId, address(numericalMath), mathCodeHash);
        registry.assertModule(protocolId, address(bondKernel), kernelCodeHash);
        registry.assertModule(protocolId, address(this), address(this).codehash);
    }

    function _get(uint256 experimentId) private view returns (Run storage run) {
        run = _runs[experimentId];
        if (run.status == Status.Missing) revert UnknownExperiment();
    }

    function _requireFinite(bytes16 value) private pure {
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert NonFiniteNumber();
    }

    function _negativeNonzero(bytes16 value) private pure returns (bool) {
        uint128 bits = uint128(value);
        return (bits >> 127) != 0 && (bits & 0x7fffffffffffffffffffffffffffffff) != 0;
    }
}

contracts/core/ShardedWorkingState.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Factory-created state shard. Only its immutable router can write history.
///      Every retained epoch reads a predecessor in at most 64 binary-search rounds.
contract VersionedStateShard {
    error Unauthorized();
    error InvalidRange();
    error InvalidEpoch();
    uint256 public constant WORDS = 4096;
    address public immutable router;
    struct Version { uint64 epoch; bytes32 value; }
    mapping(uint256 => Version[]) private _history;

    constructor(address router_) { router = router_; }

    function writeWords(uint256 start, bytes32[] calldata values, uint64 epoch) external {
        if (msg.sender != router) revert Unauthorized();
        if (epoch == 0) revert InvalidEpoch();
        if (values.length == 0 || values.length > 128 || start >= WORDS || values.length > WORDS - start)
            revert InvalidRange();
        for (uint256 i; i < values.length; ++i) {
            Version[] storage versions = _history[start + i];
            uint256 length = versions.length;
            if (length != 0 && versions[length - 1].epoch > epoch) revert InvalidEpoch();
            if (length != 0 && versions[length - 1].epoch == epoch) versions[length - 1].value = values[i];
            else versions.push(Version(epoch, values[i]));
        }
    }

    function readWords(uint256 start, uint256 count, uint64 epoch) external view returns (bytes32[] memory values) {
        if (count > 128 || start > WORDS || count > WORDS - start) revert InvalidRange();
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            Version[] storage versions = _history[start + i];
            uint256 low; uint256 high = versions.length;
            if (high == 0) continue;
            if (versions[high - 1].epoch <= epoch) { values[i] = versions[high - 1].value; continue; }
            // A word gains at most one entry per uint64 epoch. Upper bound is
            // 2**64-1 entries, so this loop has a hard maximum of 64 iterations.
            while (low < high) {
                uint256 middle = low + (high - low) / 2;
                if (versions[middle].epoch <= epoch) low = middle + 1;
                else high = middle;
            }
            if (low != 0) values[i] = versions[low - 1].value;
        }
    }
}

/// @notice Global word namespaces with bounded authenticated cross-shard access.
/// @dev WorkingStatePage-compatible mutable ABI; snapshots add immutable namespaces.
///      Semantic step completeness is enforced by the pinned writer before snapshot.
contract ShardedWorkingState {
    error Unauthorized();
    error InvalidWriter();
    error InvalidNamespace();
    error NamespaceExists();
    error UnknownNamespace();
    error InvalidCapacity();
    error NamespaceSealed();
    error InvalidBatch();
    error OutOfBounds();
    error InvalidSnapshotSource();
    error NotSnapshot();
    error EpochExhausted();
    error ShardChanged();

    uint256 public constant MAX_CAPACITY_WORDS = type(uint32).max;
    uint256 public constant MAX_BATCH_WORDS = 128;
    uint256 public constant SHARD_WORDS = 4096;
    address public immutable writer;
    bytes32 public immutable writerCodeHash;

    struct Shard { address page; bytes32 codeHash; }
    struct Namespace {
        uint32 capacityWords;
        bool isSealed;
        bool isSnapshot;
        uint64 epoch;
        bytes32 source;
        bytes32 writeDigest;
        bytes32 commitment;
        mapping(uint256 => Shard) shards;
    }
    mapping(bytes32 => Namespace) private _namespaces;

    event NamespaceCreated(bytes32 indexed namespace, uint32 capacityWords);
    event ShardCreated(bytes32 indexed namespace, uint256 indexed shardIndex, address page, bytes32 codeHash);
    event WordsWritten(bytes32 indexed namespace, uint256 start, uint256 count, bytes32 writeDigest);
    event NamespaceFrozen(bytes32 indexed namespace);
    event SnapshotCreated(bytes32 indexed source, bytes32 indexed snapshot, uint64 epoch, bytes32 commitment);

    modifier onlyWriter() {
        if (msg.sender != writer || writer.codehash != writerCodeHash) revert Unauthorized();
        _;
    }

    constructor(address writer_) {
        if (writer_ == address(0) || writer_.code.length == 0) revert InvalidWriter();
        writer = writer_; writerCodeHash = writer_.codehash;
    }

    function createNamespace(bytes32 namespace, uint32 capacityWords) external onlyWriter {
        if (namespace == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[namespace].capacityWords != 0) revert NamespaceExists();
        if (capacityWords == 0) revert InvalidCapacity();
        Namespace storage n = _namespaces[namespace];
        n.capacityWords = capacityWords; n.epoch = 1;
        n.writeDigest = keccak256(abi.encode(bytes32("ORVIA-SHARDED-STATE-v1"), block.chainid,
            address(this), writer, namespace, capacityWords));
        emit NamespaceCreated(namespace, capacityWords);
    }

    function writeWord(bytes32 namespace, uint256 index, bytes32 value) external onlyWriter {
        bytes32[] memory values = new bytes32[](1); values[0] = value;
        _write(namespace, index, values);
    }
    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values) external onlyWriter {
        _write(namespace, start, values);
    }
    function _write(bytes32 namespace, uint256 start, bytes32[] memory values) private {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        if (values.length == 0 || values.length > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(n.capacityWords, start, values.length);
        uint256 done;
        while (done < values.length) {
            uint256 index = start + done;
            uint256 local = index % SHARD_WORDS;
            uint256 count = values.length - done;
            if (count > SHARD_WORDS - local) count = SHARD_WORDS - local;
            Shard storage shard = n.shards[index / SHARD_WORDS];
            if (shard.page == address(0)) {
                shard.page = address(new VersionedStateShard{salt: keccak256(abi.encode(namespace, index / SHARD_WORDS))}(address(this)));
                shard.codeHash = shard.page.codehash;
                emit ShardCreated(namespace, index / SHARD_WORDS, shard.page, shard.codeHash);
            } else _assertShard(shard);
            bytes32[] memory chunk = new bytes32[](count);
            for (uint256 i; i < count; ++i) {
                chunk[i] = values[done + i];
                n.writeDigest = keccak256(abi.encode(n.writeDigest, index + i, chunk[i]));
            }
            VersionedStateShard(shard.page).writeWords(local, chunk, n.epoch);
            done += count;
        }
        emit WordsWritten(namespace, start, values.length, n.writeDigest);
    }

    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32) {
        return _read(namespace, index, 1)[0];
    }
    function readWords(bytes32 namespace, uint256 start, uint256 count) external view returns (bytes32[] memory) {
        return _read(namespace, start, count);
    }
    function _read(bytes32 namespace, uint256 start, uint256 count) private view returns (bytes32[] memory values) {
        Namespace storage viewNamespace = _get(namespace);
        if (count > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(viewNamespace.capacityWords, start, count);
        bytes32 source = viewNamespace.isSnapshot ? viewNamespace.source : namespace;
        Namespace storage n = _namespaces[source];
        uint64 epoch = viewNamespace.isSnapshot ? viewNamespace.epoch : n.epoch;
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint256 index = start + done;
            uint256 local = index % SHARD_WORDS;
            uint256 length = count - done;
            if (length > SHARD_WORDS - local) length = SHARD_WORDS - local;
            Shard storage shard = n.shards[index / SHARD_WORDS];
            if (shard.page != address(0)) {
                _assertShard(shard);
                bytes32[] memory chunk = VersionedStateShard(shard.page).readWords(local, length, epoch);
                for (uint256 i; i < length; ++i) values[done + i] = chunk[i];
            }
            done += length;
        }
    }

    /// @notice Called by a code-pinned coordinator only after its complete-state barrier.
    /// @dev Names bind the writer's run/step identity; commitment additionally binds
    ///      source, exact retained epoch, capacity and every ordered word write.
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external onlyWriter returns (bytes32 commitment) {
        Namespace storage n = _get(source);
        if (n.isSnapshot) revert InvalidSnapshotSource();
        if (snapshot == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[snapshot].capacityWords != 0) revert NamespaceExists();
        if (n.epoch == type(uint64).max) revert EpochExhausted();
        Namespace storage s = _namespaces[snapshot];
        s.capacityWords = n.capacityWords; s.isSealed = true; s.isSnapshot = true;
        s.epoch = n.epoch; s.source = source; s.writeDigest = n.writeDigest;
        commitment = keccak256(abi.encode(bytes32("ORVIA-STATE-SNAPSHOT-v1"), block.chainid,
            address(this), writer, source, snapshot, s.epoch, s.capacityWords, s.writeDigest));
        s.commitment = commitment;
        ++n.epoch;
        emit SnapshotCreated(source, snapshot, s.epoch, commitment);
    }

    function snapshotInfo(bytes32 snapshot) external view returns (
        bytes32 source, uint64 epoch, uint32 capacityWords, bytes32 writeDigest, bytes32 commitment
    ) {
        Namespace storage s = _get(snapshot);
        if (!s.isSnapshot) revert NotSnapshot();
        return (s.source, s.epoch, s.capacityWords, s.writeDigest, s.commitment);
    }
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacityWords, bool isSealed) {
        Namespace storage n = _get(namespace); return (n.capacityWords, n.isSealed);
    }
    function namespaceCommitment(bytes32 namespace) external view returns (bytes32 writeDigest, uint64 epoch) {
        Namespace storage n = _get(namespace); return (n.writeDigest, n.epoch);
    }
    function shardInfo(bytes32 namespace, uint256 shardIndex) external view returns (address page, bytes32 codeHash) {
        Namespace storage n = _get(namespace);
        if (shardIndex >= (uint256(n.capacityWords) + SHARD_WORDS - 1) / SHARD_WORDS) revert OutOfBounds();
        if (n.isSnapshot) n = _namespaces[n.source];
        Shard storage s = n.shards[shardIndex]; return (s.page, s.codeHash);
    }
    function sealNamespace(bytes32 namespace) external onlyWriter {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        n.isSealed = true; emit NamespaceFrozen(namespace);
    }
    function _assertShard(Shard storage shard) private view {
        if (shard.page.codehash != shard.codeHash || shard.page.code.length == 0) revert ShardChanged();
    }
    function _get(bytes32 namespace) private view returns (Namespace storage n) {
        n = _namespaces[namespace]; if (n.capacityWords == 0) revert UnknownNamespace();
    }
    function _range(uint32 capacity, uint256 start, uint256 count) private pure {
        if (start > capacity || count > uint256(capacity) - start) revert OutOfBounds();
    }
}

contracts/core/WorkingStatePage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Bounded, isolated word namespaces controlled by one immutable writer.
/// @dev Values are raw bits. The writer must enforce numerical and run-state rules.
contract WorkingStatePage {
    error Unauthorized();
    error InvalidWriter();
    error InvalidNamespace();
    error NamespaceExists();
    error UnknownNamespace();
    error InvalidCapacity();
    error NamespaceSealed();
    error InvalidBatch();
    error OutOfBounds();

    uint256 public constant MAX_CAPACITY_WORDS = 65536;
    uint256 public constant MAX_BATCH_WORDS = 128;
    address public immutable writer;

    struct Namespace {
        uint32 capacityWords;
        bool isSealed;
        mapping(uint256 => bytes32) words;
    }

    mapping(bytes32 => Namespace) private _namespaces;

    event NamespaceCreated(bytes32 indexed namespace, uint32 capacityWords);
    event WordWritten(bytes32 indexed namespace, uint256 index, bytes32 value);
    event WordsWritten(bytes32 indexed namespace, uint256 start, uint256 count);
    event NamespaceFrozen(bytes32 indexed namespace);

    modifier onlyWriter() {
        if (msg.sender != writer) revert Unauthorized();
        _;
    }

    constructor(address writer_) {
        if (writer_ == address(0) || writer_.code.length == 0) revert InvalidWriter();
        writer = writer_;
    }

    function createNamespace(bytes32 namespace, uint32 capacityWords) external onlyWriter {
        if (namespace == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[namespace].capacityWords != 0) revert NamespaceExists();
        if (capacityWords == 0 || capacityWords > MAX_CAPACITY_WORDS) revert InvalidCapacity();
        _namespaces[namespace].capacityWords = capacityWords;
        emit NamespaceCreated(namespace, capacityWords);
    }

    function writeWord(bytes32 namespace, uint256 index, bytes32 value) external onlyWriter {
        Namespace storage state = _getNamespace(namespace);
        if (state.isSealed) revert NamespaceSealed();
        if (index >= state.capacityWords) revert OutOfBounds();
        state.words[index] = value;
        emit WordWritten(namespace, index, value);
    }

    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values) external onlyWriter {
        Namespace storage state = _getNamespace(namespace);
        if (state.isSealed) revert NamespaceSealed();
        if (values.length == 0 || values.length > MAX_BATCH_WORDS) revert InvalidBatch();
        _checkRange(state.capacityWords, start, values.length);
        for (uint256 i; i < values.length; ++i) state.words[start + i] = values[i];
        emit WordsWritten(namespace, start, values.length);
    }

    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32) {
        Namespace storage state = _getNamespace(namespace);
        if (index >= state.capacityWords) revert OutOfBounds();
        return state.words[index];
    }

    function readWords(bytes32 namespace, uint256 start, uint256 count)
        external
        view
        returns (bytes32[] memory values)
    {
        Namespace storage state = _getNamespace(namespace);
        if (count > MAX_BATCH_WORDS) revert InvalidBatch();
        _checkRange(state.capacityWords, start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) values[i] = state.words[start + i];
    }

    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacityWords, bool isSealed) {
        Namespace storage state = _getNamespace(namespace);
        return (state.capacityWords, state.isSealed);
    }

    function sealNamespace(bytes32 namespace) external onlyWriter {
        Namespace storage state = _getNamespace(namespace);
        if (state.isSealed) revert NamespaceSealed();
        state.isSealed = true;
        emit NamespaceFrozen(namespace);
    }

    function _getNamespace(bytes32 namespace) private view returns (Namespace storage state) {
        state = _namespaces[namespace];
        if (state.capacityWords == 0) revert UnknownNamespace();
    }

    function _checkRange(uint32 capacityWords, uint256 start, uint256 count) private pure {
        // Subtraction after the start check avoids overflow for adversarial indices.
        if (start > capacityWords || count > uint256(capacityWords) - start) revert OutOfBounds();
    }
}

