// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice One direct Coulomb pair, U = prefactor*chargeProduct/r.
/// @dev The caller supplies the signed charge product and a nonnegative unit-
///      consistent prefactor. No dielectric convention or force field is chosen
///      here. There is no cutoff, reaction field, periodic image or Ewald/PME sum.
contract CoulombPairKernel {
    error InvalidMathContract();
    error NonFiniteInput();
    error NegativePrefactor();
    error ZeroSeparation();

    FloatMath public immutable numericalMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.CoulombPairKernel.v0.2");

    constructor(address numericalMath_) {
        if (numericalMath_.code.length == 0) revert InvalidMathContract();
        numericalMath = FloatMath(numericalMath_);
    }

    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 chargeProduct, bytes16 prefactor)
        external
        view
        returns (bytes16 energy, bytes16[3] memory forceOnA)
    {
        FloatMath m = numericalMath;
        if (!m.isFinite(chargeProduct) || !m.isFinite(prefactor)) revert NonFiniteInput();
        if (m.isNegative(prefactor)) revert NegativePrefactor();

        bytes16[3] memory displacement;
        bytes16 rSquared;
        for (uint256 axis; axis < 3; ++axis) {
            if (!m.isFinite(a[axis]) || !m.isFinite(b[axis])) revert NonFiniteInput();
            displacement[axis] = m.sub(b[axis], a[axis]);
            rSquared = m.add(rSquared, m.mul(displacement[axis], displacement[axis]));
        }
        if (m.isZero(rSquared)) revert ZeroSeparation();
        // Zero strength still requires valid, nonsingular geometry.
        if (m.isZero(prefactor) || m.isZero(chargeProduct)) return (energy, forceOnA);

        bytes16 r = m.sqrt(rSquared);
        energy = m.div(m.mul(prefactor, chargeProduct), r);
        // For d = b-a, like charges repel: F_A = -U*d/r^2.
        bytes16 scale = m.neg(m.div(energy, rSquared));
        for (uint256 axis; axis < 3; ++axis) {
            forceOnA[axis] = m.mul(scale, displacement[axis]);
        }
    }
}

contracts/kernels/CounterRandom.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {ScalarMath} from "../math/ScalarMath.sol";
import {ElementaryMath} from "../math/ElementaryMath.sol";

/// @notice Stateless, reproducible scientific random streams from registered counters.
/// @dev No block entropy, sender, address or mutable draw counter enters the stream.
contract CounterRandom {
    error InvalidDependency();

    FloatMath public immutable numericalMath;
    ScalarMath public immutable scalarMath;
    ElementaryMath public immutable elementaryMath;
    bytes32 public constant DOMAIN = keccak256("ORVIA.CounterRandom.v1");
    bytes32 public constant GENERATOR_ID = keccak256("ORVIA.CounterRandom.v0.5.Keccak112midpoint.BoxMuller");
    bytes16 private constant TWO_TO_MINUS_113 = 0x3f8e0000000000000000000000000000;

    constructor(address math_, address scalar_, address elementary_) {
        if (math_.code.length == 0 || scalar_.code.length == 0 || elementary_.code.length == 0) revert InvalidDependency();
        if (address(ScalarMath(scalar_).numericalMath()) != math_
            || address(ElementaryMath(elementary_).numericalMath()) != math_) revert InvalidDependency();
        numericalMath = FloatMath(math_);
        scalarMath = ScalarMath(scalar_);
        elementaryMath = ElementaryMath(elementary_);
    }

    function word(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw, uint8 lane)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(DOMAIN, seed, experiment, replica, step, draw, lane));
    }

    function uniform(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw)
        external view returns (bytes16)
    {
        return _uniform(word(seed, experiment, replica, step, draw, 0));
    }

    /// @notice Two standard-normal approximations from two independent hash lanes.
    function normalPair(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw)
        external view returns (bytes16 first, bytes16 second)
    {
        FloatMath m = numericalMath;
        bytes16 u = _uniform(word(seed, experiment, replica, step, draw, 0));
        bytes16 v = _uniform(word(seed, experiment, replica, step, draw, 1));
        bytes16 radius = m.sqrt(m.mul(m.fromInt(-2), scalarMath.ln(u)));
        (bytes16 sine, bytes16 cosine) = elementaryMath.sinCos(m.mul(elementaryMath.TWO_PI(), v));
        first = m.mul(radius, cosine);
        second = m.mul(radius, sine);
    }

    function _uniform(bytes32 bits) private view returns (bytes16) {
        // Odd integer/2^113 is exactly representable, and always strictly in (0,1).
        uint256 midpointNumerator = 2 * (uint256(bits) >> 144) + 1;
        return numericalMath.mul(numericalMath.fromUInt(midpointNumerator), TWO_TO_MINUS_113);
    }
}

contracts/kernels/DistanceConstraintKern.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice One mass-weighted SHAKE position or RATTLE velocity correction.
/// @dev A coordinator must iterate coupled constraints to a registered tolerance
///      and reject nonconvergence before committing a timestep.
contract DistanceConstraintKernel {
    error InvalidDependency();
    error InvalidInput();
    error NoLocalSolution();
    FloatMath public immutable numericalMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.DistanceConstraintKernel.v1");

    struct PositionInput {
        bytes16[3] oldDisplacement;
        bytes16[3] trialDisplacement;
        bytes16 massA;
        bytes16 massB;
        bytes16 target;
    }
    struct VelocityInput {
        bytes16[3] displacement;
        bytes16[3] relativeVelocity;
        bytes16 massA;
        bytes16 massB;
    }

    constructor(address math_) {
        if (math_.code.length == 0) revert InvalidDependency();
        numericalMath = FloatMath(math_);
    }

    /// @notice Corrections are added to A and B; displacements use B-A.
    function positionCorrection(PositionInput calldata p) external view
        returns (bytes16[3] memory correctionA, bytes16[3] memory correctionB, bytes16 relativeResidual)
    {
        FloatMath m = numericalMath;
        _positive(p.massA); _positive(p.massB); _positive(p.target);
        bytes16 oldSquared = _dot(p.oldDisplacement, p.oldDisplacement);
        _positive(oldSquared);
        bytes16 dot = _dot(p.oldDisplacement, p.trialDisplacement);
        // Restrict to the continuous local SHAKE root, not a bond orientation flip.
        if (m.compare(dot, bytes16(0)) <= 0) revert NoLocalSolution();
        bytes16 targetSquared = m.mul(p.target, p.target);
        _positive(targetSquared);
        bytes16 defect = m.sub(_dot(p.trialDisplacement, p.trialDisplacement), targetSquared);
        relativeResidual = m.div(m.abs(defect), targetSquared);
        bytes16 discriminant = m.sub(m.mul(dot, dot), m.mul(oldSquared, defect));
        if (m.compare(discriminant, bytes16(0)) < 0) revert NoLocalSolution();
        // x=defect/(dot+sqrt(dot^2-oldSquared*defect)) avoids subtractive cancellation.
        bytes16 x = m.div(defect, m.add(dot, m.sqrt(discriminant)));
        (correctionA, correctionB) = _corrections(p.oldDisplacement, x, p.massA, p.massB);
    }

    function velocityCorrection(VelocityInput calldata p) external view
        returns (bytes16[3] memory correctionA, bytes16[3] memory correctionB, bytes16 relativeResidual)
    {
        _positive(p.massA); _positive(p.massB);
        FloatMath m = numericalMath;
        bytes16 squared = _dot(p.displacement, p.displacement);
        _positive(squared);
        bytes16 x = m.div(_dot(p.displacement, p.relativeVelocity), squared);
        // Residual has units inverse time; it is distinct from position tolerance.
        relativeResidual = m.abs(x);
        (correctionA, correctionB) = _corrections(p.displacement, x, p.massA, p.massB);
    }

    function _corrections(bytes16[3] memory direction, bytes16 x, bytes16 massA, bytes16 massB)
        private view returns (bytes16[3] memory a, bytes16[3] memory b)
    {
        FloatMath m = numericalMath;
        bytes16 totalMass = m.add(massA, massB);
        bytes16 shareA = m.mul(x, m.div(massB, totalMass));
        bytes16 shareB = m.neg(m.mul(x, m.div(massA, totalMass)));
        for (uint256 axis; axis < 3; ++axis) {
            a[axis] = m.mul(shareA, direction[axis]);
            b[axis] = m.mul(shareB, direction[axis]);
        }
    }

    function _dot(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16 sum) {
        for (uint256 axis; axis < 3; ++axis) {
            if (!numericalMath.isFinite(a[axis]) || !numericalMath.isFinite(b[axis])) revert InvalidInput();
            sum = numericalMath.add(sum, numericalMath.mul(a[axis], b[axis]));
        }
    }

    function _positive(bytes16 value) private view {
        if (!numericalMath.isFinite(value) || numericalMath.compare(value, bytes16(0)) <= 0) revert InvalidInput();
    }
}

contracts/kernels/EwaldCorrections.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {EwaldKernelBase} from "./EwaldKernelBase.sol";
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Tin-foil Ewald self, neutralizing-background and pair-exception terms.
contract EwaldCorrections is EwaldKernelBase {
    bytes32 public constant KERNEL_ID =
        keccak256("ORVIA.EwaldCorrections.v0.5");
    bytes16 private constant HALF = 0x3ffe0000000000000000000000000000;
    struct ExceptionParameters {
        bytes16 original;
        bytes16 desired;
        bytes16 prefactor;
        bytes16 alpha;
    }

    constructor(
        address math_,
        address scalar_
    ) EwaldKernelBase(math_, scalar_) {}

    function selfEnergy(
        bytes16 charge,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(charge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 result = m.mul(charge, charge);
        result = m.mul(result, INV_SQRT_PI);
        result = m.mul(result, alpha);
        result = m.neg(m.mul(result, prefactor));
        _finite(result);
        return result;
    }

    /// @notice Uniform neutralizing plasma: -K*pi*Q^2/(2*alpha^2*V).
    /// @dev Zero coordinate force at fixed volume; pressure derivatives are not returned.
    function backgroundEnergy(
        bytes16 totalCharge,
        bytes16[3] calldata box,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(totalCharge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 denominator = m.mul(alpha, alpha);
        denominator = m.mul(denominator, _volume(box));
        denominator = m.mul(TWO, denominator);
        bytes16 numerator = m.mul(totalCharge, totalCharge);
        numerator = m.mul(numerator, PI);
        numerator = m.mul(numerator, prefactor);
        bytes16 result = m.neg(m.div(numerator, denominator));
        _finite(result);
        return result;
    }

    /// @notice K*(desiredQ-originalQ*erf(alpha*r))/r, replacing an omitted real pair.
    /// @dev Reciprocal factors retain original atomic charges. Caller must omit this
    ///      pair's screened real term, then add this term once with no cutoff.
    function exception(
        bytes16[3] calldata displacement,
        bytes16 originalChargeProduct,
        bytes16 desiredChargeProduct,
        bytes16 prefactor,
        bytes16 alpha
    ) external view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        return
            _exception(
                displacement,
                ExceptionParameters(
                    originalChargeProduct,
                    desiredChargeProduct,
                    prefactor,
                    alpha
                )
            );
    }

    function _exception(
        bytes16[3] memory displacement,
        ExceptionParameters memory p
    ) private view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        _finite(p.original);
        _finite(p.desired);
        _nonnegative(p.prefactor);
        _positive(p.alpha);
        FloatMath m = numericalMath;
        bytes16 r2 = _normSquared(displacement);
        if (m.isZero(r2)) {
            for (uint256 axis; axis < 3; ++axis)
                if (!m.isZero(displacement[axis])) revert OutsideDomain();
            if (!m.isZero(p.desired)) revert ZeroSeparation();
            energy = m.mul(TWO, m.mul(p.alpha, INV_SQRT_PI));
            energy = m.mul(energy, p.original);
            energy = m.neg(m.mul(energy, p.prefactor));
            _finite(energy);
            return (energy, forceOnA);
        }
        bytes16 r = m.sqrt(r2);
        bytes16 x = m.mul(p.alpha, r);
        if (m.compare(x, SIXTEEN) > 0) revert OutsideDomain();
        bytes16 erfX = scalarMath.erf(x);
        energy = m.mul(p.original, erfX);
        energy = m.div(m.sub(p.desired, energy), r);
        energy = m.mul(p.prefactor, energy);
        bytes16 scale = m.mul(
            p.original,
            _gaussianForceScale(x, r, r2, p.alpha, erfX)
        );
        bytes16 direct = m.mul(r2, r);
        direct = m.div(p.desired, direct);
        scale = m.sub(scale, direct);
        scale = m.mul(p.prefactor, scale);
        _finite(energy);
        for (uint256 axis; axis < 3; ++axis) {
            forceOnA[axis] = m.mul(scale, displacement[axis]);
            _finite(forceOnA[axis]);
        }
    }

    /// @dev Stable (erf(x)-2*x*exp(-x*x)/sqrt(pi))/r^3 at small x.
    function _gaussianForceScale(
        bytes16 x,
        bytes16 r,
        bytes16 r2,
        bytes16 alpha,
        bytes16 erfX
    ) private view returns (bytes16) {
        FloatMath m = numericalMath;
        if (m.compare(x, HALF) <= 0) {
            bytes16 negativeSquared = m.neg(m.mul(x, x));
            bytes16 term = ONE;
            bytes16 sum = m.div(ONE, m.fromUInt(3));
            for (uint256 n = 1; n < 24; ++n) {
                term = m.div(m.mul(term, negativeSquared), m.fromUInt(n));
                sum = m.add(sum, m.div(term, m.fromUInt(2 * n + 3)));
            }
            bytes16 factor = m.mul(alpha, alpha);
            factor = m.mul(factor, alpha);
            factor = m.mul(factor, m.mul(FOUR, INV_SQRT_PI));
            return m.mul(factor, sum);
        }
        bytes16 gaussian = scalarMath.exp(m.neg(m.mul(x, x)));
        bytes16 numerator = m.mul(INV_SQRT_PI, gaussian);
        numerator = m.mul(numerator, x);
        numerator = m.mul(TWO, numerator);
        numerator = m.sub(erfX, numerator);
        return m.div(numerator, m.mul(r2, r));
    }
}

