// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "./FloatMath.sol";

/// @notice Bounded, deterministic binary128-format angular functions.
/// @dev Polynomial truncation and upstream arithmetic are not a correctly-rounded IEEE guarantee.
contract ElementaryMath {
    error InvalidMathContract();
    error NonFiniteInput();
    error UndefinedAngle();
    error OutsideDomain();

    FloatMath public immutable numericalMath;
    bytes16 public constant PI = 0x4000921fb54442d18469898cc51701b8;
    bytes16 public constant TWO_PI = 0x4001921fb54442d18469898cc51701b8;
    bytes16 public constant HALF_PI = 0x3fff921fb54442d18469898cc51701b8;
    bytes16 public constant MAX_TRIG_ARGUMENT = 0x4005921fb54442d18469898cc51701b8; // 32*pi
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant TWO = 0x40000000000000000000000000000000;

    constructor(address math_) {
        if (math_.code.length == 0) revert InvalidMathContract();
        numericalMath = FloatMath(math_);
    }

    /// @notice Principal angle in [-pi, pi]; signed zero is treated as numerical zero.
    function atan2(bytes16 y, bytes16 x) public view returns (bytes16 angle) {
        FloatMath m = numericalMath;
        _finite(x); _finite(y);
        if (m.isZero(x)) {
            if (m.isZero(y)) revert UndefinedAngle();
            return m.isNegative(y) ? m.neg(HALF_PI) : HALF_PI;
        }
        bytes16 ax = m.abs(x);
        bytes16 ay = m.abs(y);
        bool inverted = m.compare(ay, ax) > 0;
        bytes16 ratio = inverted ? m.div(ax, ay) : m.div(ay, ax);
        angle = _atanUnit(ratio);
        if (inverted) angle = m.sub(HALF_PI, angle);
        if (m.isNegative(x)) angle = m.sub(PI, angle);
        if (m.isNegative(y)) angle = m.neg(angle);
    }

    function _atanUnit(bytes16 ratio) private view returns (bytes16) {
        FloatMath m = numericalMath;
        // One half-angle reduction bounds the alternating-series argument by sqrt(2)-1.
        bytes16 t = m.mul(ratio, ratio);
        t = m.add(ONE, t);
        t = m.sqrt(t);
        t = m.add(ONE, t);
        t = m.div(ratio, t);
        bytes16 negativeSquared = m.neg(m.mul(t, t));
        bytes16 power = t;
        bytes16 sum = t;
        for (uint256 i = 1; i < 48; ++i) {
            power = m.mul(power, negativeSquared);
            bytes16 term = m.fromUInt(2 * i + 1);
            term = m.div(power, term);
            sum = m.add(sum, term);
        }
        return m.mul(TWO, sum);
    }

    /// @notice Sine and cosine for finite arguments with absolute value <= 32*pi.
    function sinCos(bytes16 angle) external view returns (bytes16 sine, bytes16 cosine) {
        FloatMath m = numericalMath;
        _finite(angle);
        if (m.compare(m.abs(angle), MAX_TRIG_ARGUMENT) > 0) revert OutsideDomain();
        bytes16 x = angle;
        bytes16 negativePi = m.neg(PI);
        // The explicit domain bounds reduction to at most 16 full turns.
        for (uint256 i; i < 16; ++i) {
            if (m.compare(x, PI) > 0) x = m.sub(x, TWO_PI);
            else if (m.compare(x, negativePi) < 0) x = m.add(x, TWO_PI);
            else break;
        }
        if (m.compare(x, PI) > 0 || m.compare(x, negativePi) < 0) revert OutsideDomain();
        bytes16 negativeSquared = m.neg(m.mul(x, x));
        bytes16 sineTerm = x;
        bytes16 cosineTerm = ONE;
        sine = x;
        cosine = ONE;
        for (uint256 i = 1; i <= 32; ++i) {
            sineTerm = m.mul(sineTerm, negativeSquared);
            sineTerm = m.div(sineTerm, m.fromUInt((2 * i) * (2 * i + 1)));
            cosineTerm = m.mul(cosineTerm, negativeSquared);
            cosineTerm = m.div(cosineTerm, m.fromUInt((2 * i - 1) * (2 * i)));
            sine = m.add(sine, sineTerm);
            cosine = m.add(cosine, cosineTerm);
        }
    }

    function acos(bytes16 x) external view returns (bytes16) {
        FloatMath m = numericalMath;
        _finite(x);
        if (m.compare(m.abs(x), ONE) > 0) revert OutsideDomain();
        bytes16 product = m.mul(m.sub(ONE, x), m.add(ONE, x));
        return atan2(m.sqrt(product), x);
    }

    function _finite(bytes16 x) private view {
        if (!numericalMath.isFinite(x)) revert NonFiniteInput();
    }
}

contracts/math/Fixed96EwaldMath.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Fixed96Math} from "./Fixed96Math.sol";

/// @dev Bounded Q96 policy, not correctly rounded binary128 transcendental math.
/// Series lengths and continued fraction are protocol constants, never adaptive
/// transaction-work settings. Values below fixed-point resolution can become zero.
abstract contract Fixed96EwaldMath is Fixed96Math {
    int256 internal constant PI96 = 248902613312231085230521944622;
    int256 internal constant INV_SQRT_PI96 = 44699704014176752299205233279;

    /// @dev exp(-z), 0 <= z <= 256. Reduce by 256, 32 Taylor terms, 8 squarings.
    function _expNegative(int256 z) internal pure returns (int256 value) {
        if (z < 0 || z > 256 * ONE) revert ArithmeticDomain();
        int256 x = -z / 256;
        int256 term = ONE;
        value = ONE;
        for (uint256 n = 1; n <= 32; ++n) {
            term = _mul(term, x) / int256(n);
            if (term == 0) break; // Every later Q96 recurrence term is also zero.
            value = _add(value, term);
        }
        for (uint256 n; n < 8; ++n) value = _mul(value, value);
        if (value < 0 || value > ONE) revert ArithmeticDomain();
    }

    /// @dev Nonnegative erfc, using the same positive series / DLMF 7.9.2
    /// continued-fraction division as the binary128 reference, with Q96 arithmetic.
    function _erfcPositive(int256 x) internal pure returns (int256 value) {
        if (x < 0 || x > 16 * ONE) revert ArithmeticDomain();
        int256 z = _mul(x, x);
        int256 gaussian = _expNegative(z);
        if (x < 2 * ONE) {
            int256 term = x;
            int256 sum = x;
            for (uint256 n = 1; n < 64; ++n) {
                term = _mul(term, 2 * z) / int256(2 * n + 1);
                if (term == 0) break;
                sum = _add(sum, term);
            }
            value = _sub(ONE, _mul(_mul(2 * INV_SQRT_PI96, gaussian), sum));
        } else {
            int256 base = z + ONE / 2;
            int256 tail;
            for (uint256 n = 128; n > 0; --n) {
                int256 numerator = int256(n * (2 * n - 1)) * (ONE / 2);
                tail = _div(numerator, _sub(base + int256(2 * n) * ONE, tail));
            }
            value = _div(_mul(_mul(x, gaussian), INV_SQRT_PI96), _sub(base, tail));
        }
        if (value < 0 || value > ONE) revert ArithmeticDomain();
    }

    /// @dev Argument already reduced to [-pi,pi]. Taylor terms through degree 65/64.
    function _sinCosReduced(int256 x) internal pure returns (int256 sine, int256 cosine) {
        if (x < -PI96 || x > PI96) revert ArithmeticDomain();
        int256 negativeSquared = -_mul(x, x);
        int256 sineTerm = x;
        int256 cosineTerm = ONE;
        sine = x;
        cosine = ONE;
        for (uint256 n = 1; n <= 32; ++n) {
            sineTerm = _mul(sineTerm, negativeSquared) / int256((2*n)*(2*n+1));
            cosineTerm = _mul(cosineTerm, negativeSquared) / int256((2*n-1)*(2*n));
            if (sineTerm == 0 && cosineTerm == 0) break;
            sine = _add(sine, sineTerm);
            cosine = _add(cosine, cosineTerm);
        }
    }
}

contracts/math/Fixed96Math.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Shared bounded Q96.96 arithmetic; see each evaluator's declared policy.
abstract contract Fixed96Math {
    error NonFinite();
    error ArithmeticDomain();
    error InvalidParameter();
    error ZeroSeparation();
    int256 internal constant ONE = 1 << 96;
    int256 internal constant LIMIT = 1 << 126;
    uint256 internal constant SIGN = 1 << 127;
    uint256 internal constant FRACTION = (1 << 112)-1;
    function _bounded(int256 x) internal pure returns(int256) { if (x > LIMIT || x < -LIMIT) revert ArithmeticDomain(); return x; }
    function _add(int256 a,int256 b) internal pure returns(int256) { return _bounded(a+b); }
    function _sub(int256 a,int256 b) internal pure returns(int256) { return _bounded(a-b); }
    function _mul(int256 a,int256 b) internal pure returns(int256) { return _bounded((a*b)/ONE); }
    function _div(int256 a,int256 b) internal pure returns(int256) { if (b == 0) revert ArithmeticDomain(); return _bounded((a*ONE)/b); }

    function _sqrt(int256 a) internal pure returns(int256) {
        if (a <= 0) revert ArithmeticDomain();
        uint256 n = uint256(a)*uint256(ONE);
        uint256 r = uint256(1) << ((_log2(n)+2)/2);
        for (uint256 i; i < 16; ++i) {
            uint256 next = (r+n/r)/2;
            if (next >= r) return _bounded(int256(r));
            r = next;
        }
        revert ArithmeticDomain();
    }
    function _log2(uint256 value) internal pure returns(uint256 r) {
        if (value >> 128 != 0) { value >>= 128; r += 128; }
        if (value >> 64 != 0) { value >>= 64; r += 64; }
        if (value >> 32 != 0) { value >>= 32; r += 32; }
        if (value >> 16 != 0) { value >>= 16; r += 16; }
        if (value >> 8 != 0) { value >>= 8; r += 8; }
        if (value >> 4 != 0) { value >>= 4; r += 4; }
        if (value >> 2 != 0) { value >>= 2; r += 2; }
        if (value >> 1 != 0) r += 1;
    }
    function _fixed(bytes16 encoded) internal pure returns(int256) {
        uint256 bits = uint128(encoded);
        uint256 exponent = (bits >> 112) & 0x7fff;
        if (exponent == 0x7fff) revert NonFinite();
        uint256 mantissa = bits & FRACTION;
        if (exponent == 0 && mantissa == 0) return 0;
        if (exponent == 0 || exponent > 16413) revert ArithmeticDomain();
        mantissa |= 1 << 112;
        int256 shift = int256(exponent)-16399;
        uint256 raw;
        if (shift >= 0) raw = mantissa << uint256(shift);
        else {
            uint256 k = uint256(-shift);
            if (k >= 128) revert ArithmeticDomain();
            raw = mantissa >> k;
            uint256 rem = mantissa & ((uint256(1) << k)-1);
            uint256 half = uint256(1) << (k-1);
            if (rem > half || (rem == half && raw & 1 == 1)) ++raw;
        }
        if (raw == 0 || raw > uint256(LIMIT)) revert ArithmeticDomain();
        return bits & SIGN == 0 ? int256(raw) : -int256(raw);
    }
    function _quad(int256 x) internal pure returns(bytes16) {
        if (x == 0) return bytes16(0);
        _bounded(x);
        uint256 sign = x < 0 ? SIGN : 0;
        uint256 raw = uint256(x < 0 ? -x : x);
        uint256 hi = _log2(raw);
        int256 exponent = int256(hi)-96;
        uint256 mantissa;
        if (hi <= 112) mantissa = raw << (112-hi);
        else {
            uint256 k = hi-112;
            mantissa = raw >> k;
            uint256 rem = raw & ((uint256(1) << k)-1);
            uint256 half = uint256(1) << (k-1);
            if (rem > half || (rem == half && mantissa & 1 == 1)) ++mantissa;
            if (mantissa == 1 << 113) { mantissa >>= 1; ++exponent; }
        }
        return bytes16(uint128(sign | (uint256(exponent+16383) << 112) | (mantissa & FRACTION)));
    }
}

